export type ArticleSection = { heading: string; paragraphs: string[]; examples?: string[]; bullets?: string[]; links?: { label: string; url: string }[] };
export type Article = { slug: string; category: string; title: string; excerpt: string; time: string; icon: string; keywords?: string[]; body: string[]; sections?: ArticleSection[] };

const section = (heading: string, paragraphs: string[], examples?: string[], bullets?: string[], links?: { label: string; url: string }[]): ArticleSection => ({ heading, paragraphs, ...(examples ? { examples } : {}), ...(bullets ? { bullets } : {}), ...(links ? { links } : {}) });
const article = (slug: string, category: string, title: string, excerpt: string, icon: string, keywords: string[], intro: string, sections: ArticleSection[], time = "6 min"): Article => ({ slug, category, title, excerpt, time, icon, keywords, body: [intro], sections });

const articleDrafts: Article[] = [
  article("praticar-o-th", "Pronúncia", "Como pronunciar o ‘th’ em inglês (think e this) sem travar", "Aprenda a fazer os dois sons do ‘th’ em inglês: a posição da língua, a diferença entre o /θ/ de think e o /ð/ de this, exercícios e os erros mais comuns de brasileiros.", "◉", ["pronúncia th inglês", "como pronunciar th", "som th think this", "th surdo sonoro", "th inglês para brasileiros", "exercícios pronúncia th"], "O som ‘th’ é um dos que mais assustam quem aprende inglês, porque não existe em português — e, por isso, o cérebro tende a trocá-lo pelo som mais próximo (t, d, f ou s). Mas o ‘th’ não é difícil: é só uma posição de língua nova, que você treina em poucos minutos por dia. Há dois ‘th’, um surdo e um sonoro, e neste guia você aprende a posição certa, a diferença entre eles e exercícios simples para soltar o som sem travar.", [
    section("A posição da língua: a base de tudo", ["O segredo do ‘th’ está em um gesto só: colocar a ponta da língua levemente entre os dentes (ou tocando a borda dos dentes de cima) e deixar o ar passar por ela. É isso que diferencia o ‘th’ do t, d, f e s, em que a língua fica atrás dos dentes.", "No começo, exagere: deixe a pontinha da língua aparecer um pouco entre os dentes. Com o tempo, o movimento fica pequeno e natural. Se a língua está atrás dos dentes, não é ‘th’."], undefined, ["Ponta da língua entre os dentes (ou tocando os de cima)", "Deixe o ar passar — não bloqueie como no t/d", "Se a língua fica atrás dos dentes, o som vira t, d, f ou s"]),
    section("Os dois sons do th: surdo e sonoro", ["Existem dois ‘th’. O surdo /θ/ (sem vibração na garganta) aparece em think, three, thing, bath, mouth. O sonoro /ð/ (com a voz vibrando) aparece em this, that, the, mother, brother. A boca faz o mesmo gesto; o que muda é ligar ou não a voz.", "Um truque: ponha a mão na garganta. No /ð/ de this você sente a vibração; no /θ/ de think, não."], ["think, three, thank, bath — /θ/ (surdo, sem voz)", "this, that, the, mother — /ð/ (sonoro, com voz)", "thin /θ/ x then /ð/ — compare os dois"]),
    section("Exercício em passos curtos", ["Treine devagar e em blocos de poucos minutos. 1) Ponha a língua entre os dentes e solte o ar: ‘ththth’. 2) Diga think bem devagar, sentindo a língua. 3) Compare com this, agora ligando a voz. 4) Junte em frases curtas.", "Repita todos os dias por pouco tempo, em vez de muito de uma vez. A pronúncia melhora com repetição curta e frequente, não com maratonas."], ["I think this is the third one. — Acho que este é o terceiro.", "My mother and my brother. — Minha mãe e meu irmão.", "Thank you for the three things. — Obrigado pelas três coisas."]),
    section("Erros comuns de brasileiros", ["Como o ‘th’ não existe em português, o reflexo é substituí-lo. Os mais comuns: trocar think por ‘tink’ (t) ou ‘fink’ (f), e this por ‘dis’ (d) ou ‘zis’ (z). Nenhum está totalmente errado como ‘sotaque’, mas treinar a língua entre os dentes aproxima muito a sua fala da natural.", "Pratique em pares que contrastam: think x sink, three x tree, they x day. Ouvir um modelo e repetir a palavra inteira ajuda mais que repetir só o som isolado."], ["think ≠ tink / fink — use a língua entre os dentes", "this ≠ dis / zis — ligue a voz com a língua à frente", "three ≠ tree — /θr/, não /tr/"]),
    section("Perguntas frequentes", ["O ‘th’ é sempre igual? Não — há o surdo /θ/ (think) e o sonoro /ð/ (this). Posso trocar por ‘f’ ou ‘d’? Você será entendido, mas treinar o som certo melhora a clareza. A leitura de voz do navegador avalia minha pronúncia? Não — serve para ouvir um modelo; para avaliar, grave a si mesmo se quiser. Quanto tempo até sair natural? Poucos minutos por dia, por algumas semanas, costumam bastar."]),
    section("Continue praticando", ["O ‘th’ é só uma das peças da pronúncia. Combine este treino com o estudo das vogais e da fala conectada, e pratique em frases reais nas aulas do curso."], undefined, undefined, [{label:"Vogais curtas e longas: ship e sheep",url:"/blog/vogais-curtas-longas-ingles"},{label:"Word stress: a sílaba tônica",url:"/blog/word-stress-pronuncia-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "7 min"),
  article("rotina-15-minutos", "Rotina de estudos", "15 minutos de inglês por dia: uma rotina simples que funciona", "Monte uma rotina de inglês de 15 minutos por dia com leitura, escuta e recuperação ativa. Veja por que pouco e constante vence maratonas e como não desistir.", "↗", ["rotina de inglês 15 minutos", "estudar inglês todos os dias", "como criar rotina de estudo inglês", "aprender inglês pouco tempo", "plano de estudo inglês", "hábito de estudar inglês"], "Falta de tempo é a desculpa número um para não estudar inglês — e a boa notícia é que 15 minutos bem usados todos os dias rendem mais que três horas de vez em quando. O que faz você aprender não é a duração de cada sessão, e sim a constância e a qualidade da prática. Neste guia você monta uma rotina curta e repetível, com leitura, escuta e recuperação ativa, e aprende a manter o hábito mesmo nos dias difíceis.", [
    section("Por que pouco e constante vence", ["A memória se fortalece com repetição espaçada — encontrar a mesma informação em dias diferentes. Uma maratona de três horas no domingo e nada o resto da semana trabalha contra isso: você esquece boa parte antes de revisar. Já 15 minutos diários mantêm o contato frequente, que é o que fixa o idioma.", "Além disso, uma meta pequena é fácil de cumprir, e cumprir cria motivação. Metas gigantes assustam e levam ao abandono."]),
    section("Uma sequência de 15 minutos", ["Divida o tempo em três blocos de cinco minutos: leitura (um texto curto no seu nível), escuta (um áudio ou vídeo curto) e recuperação ativa (tentar lembrar, sem olhar, as palavras e ideias que apareceram). Esse trio cobre entrada e saída de língua em pouco tempo.", "Não precisa ser exatamente 5-5-5. Em alguns dias você pode focar mais na escuta, em outros no vocabulário. O importante é manter os três ingredientes ao longo da semana."], undefined, ["5 min — ler algo curto no seu nível", "5 min — ouvir um áudio ou vídeo curto", "5 min — recuperação ativa: lembrar palavras e ideias sem olhar"]),
    section("Escolha um objetivo por sessão", ["Quinze minutos não dão para ‘aprender inglês’ — mas dão para uma meta pequena e clara: fixar três expressões novas, entender a ideia central de um texto, ou treinar uma estrutura (perguntas, passado). Um foco por dia rende mais que tentar tudo de uma vez.", "No fim da sessão, pergunte-se: o que eu consigo dizer ou entender agora que não conseguia antes? Essa checagem rápida é a sua recuperação ativa."], ["Hoje: aprender 3 expressões sobre rotina.", "Hoje: entender um diálogo curto sem legenda.", "Hoje: fazer 5 perguntas no passado."]),
    section("Como não quebrar a corrente", ["O segredo de um hábito é o gatilho: encaixe o inglês em algo que você já faz todo dia — depois do café, no trajeto, antes de dormir. Deixe o material pronto para não perder tempo decidindo. E use um marcador visível (um app, um calendário) para ver a sequência crescer.", "Se faltar um dia, não transforme em desculpa para parar. Retome no seguinte. Progresso não precisa ser uma sequência perfeita — precisa continuar."]),
    section("O que evitar", ["Fuja de três armadilhas: material difícil demais (frustra e cansa), estudar só gramática solta (sem uso real) e trocar de método toda semana (sem dar tempo de funcionar). Prefira material um pouco abaixo ou no seu nível, com prática de uso, e dê semanas a cada abordagem.", "E lembre: 15 minutos é o mínimo sustentável, não o teto. Nos dias animados, siga em frente — mas sem se cobrar manter o pique todo dia."]),
    section("Perguntas frequentes", ["15 minutos é suficiente? Para progredir de forma constante, sim — o segredo é a frequência. Posso juntar a semana num dia só? Rende menos; o contato diário é o que fixa. Qual a melhor hora? A que você consegue manter todo dia. Em quanto tempo vejo resultado? Semanas de constância já mostram diferença; pense em progresso, não em prazo fixo."]),
    section("Continue praticando", ["Uma boa rotina combina entrada (leitura e escuta) com recuperação ativa e uso. Aplique esses 15 minutos nas aulas do curso e reforce com estratégias de vocabulário e leitura."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como aprender e fixar vocabulário",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Como melhorar a leitura em inglês",url:"/blog/como-melhorar-leitura-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "7 min"),

  article("como-dizer-horas-em-ingles", "Vocabulário cotidiano", "Como dizer as horas em inglês? Guia completo com exemplos", "Aprenda a perguntar e informar horários em inglês: a forma digital, o sistema com past e to, a.m. e p.m., o relógio de 24 horas e expressões do dia a dia.", "◷", ["horas em inglês", "como dizer as horas em inglês", "que horas são em inglês", "what time is it", "past to horas inglês", "am pm inglês horas"], "Dizer as horas é uma das primeiras coisas úteis que você aprende em inglês — aparece em conversas, compromissos, viagens e provas. Há dois sistemas: a forma digital (hora + minutos), mais simples e cada vez mais comum, e o sistema tradicional com past e to. Neste guia você aprende os dois, como usar a.m. e p.m., como perguntar as horas e as expressões de rotina que mais aparecem.", [
    section("A forma digital: simples e natural", ["O jeito mais fácil é dizer a hora e depois os minutos, como num relógio digital. It’s seven fifteen (7:15), it’s nine thirty (9:30). Para horas ‘cheias’, use o’clock: it’s three o’clock (3:00) — o’clock só se usa com a hora exata.", "Para minutos de 1 a 9, acrescente oh (a letra O) antes do número: 7:05 é seven oh five. Essa forma funciona em qualquer situação e é a preferida por muitos falantes."], ["It’s 7:15. — It’s seven fifteen. — São 7h15.", "It’s 9:30. — It’s nine thirty. — São 9h30.", "It’s 8:05. — It’s eight oh five. — São 8h05.", "It’s 6:00. — It’s six o’clock. — São 6h em ponto."]),
    section("O sistema com past e to", ["O sistema tradicional divide o relógio em duas metades. Até a meia hora, use past (minutos depois da hora): ten past three (3:10). Depois da meia hora, use to (minutos que faltam para a próxima hora): twenty to four (3:40).", "Nesse sistema há palavras especiais: a quarter para 15 minutos, half para 30 minutos. Então 3:15 é a quarter past three, 3:30 é half past three e 3:45 é a quarter to four."], ["It’s quarter past three. — São 3h15.", "It’s half past three. — São 3h30.", "It’s quarter to four. — São 3h45.", "It’s ten to six. — São 5h50."]),
    section("a.m., p.m. e o relógio de 24 horas", ["O inglês do dia a dia usa o relógio de 12 horas com a.m. (madrugada e manhã, 0h–11h59) e p.m. (tarde e noite, 12h–23h59). Assim, 9 a.m. é 9h da manhã e 9 p.m. é 21h.", "O relógio de 24 horas (fourteen hundred para 14:00) existe, mas é mais restrito a contextos militares, aeroportos e horários oficiais. Na conversa comum, prefira a.m./p.m. ou expressões como in the morning, in the afternoon, in the evening e at night."], ["The class starts at 9:30 a.m. — A aula começa às 9h30 da manhã.", "The movie is at 8 p.m. — O filme é às 20h.", "I wake up at six in the morning. — Acordo às seis da manhã."]),
    section("Como perguntar e responder as horas", ["A pergunta mais comum é What time is it? (Que horas são?) ou, de forma mais educada, Could you tell me the time, please? Para perguntar o horário de um evento, use What time…? com o verbo: What time does it start?", "Para responder com um horário de evento ou rotina, use a preposição at: at two o’clock, at noon (meio-dia), at midnight (meia-noite)."], ["What time is it? — Que horas são?", "What time does the meeting start? — A que horas começa a reunião?", "It’s at two o’clock. — É às duas horas.", "Do you have the time? — Você tem horas?"]),
    section("Expressões úteis sobre horários", ["Vale aprender alguns termos que aparecem muito: noon (meio-dia), midnight (meia-noite), midday, in the morning/afternoon/evening, at night. E expressões aproximadas: about five / around five (por volta das cinco), sharp (em ponto): at nine sharp.", "Para falar de pontualidade, lembre: on time (na hora marcada) e in time (a tempo, com folga)."], ["It’s noon. — É meio-dia.", "Let’s meet at around seven. — Vamos nos encontrar por volta das sete.", "The train leaves at 8 o’clock sharp. — O trem sai às 8 em ponto."]),
    section("Perguntas frequentes sobre as horas", ["É ‘o’clock’ em qualquer horário? Não — só com horas cheias (five o’clock), nunca com minutos. Preciso usar past e to? Não; a forma digital (five forty) é aceita e simples. É ‘half past three’ ou ‘three and a half’? Em inglês, half past three — nunca a tradução literal do português. Como escrevo 12h? Use noon ou 12 p.m. para meio-dia e midnight ou 12 a.m. para meia-noite."]),
    section("Continue praticando", ["Horários aparecem junto com as preposições de tempo (at, in, on) e com a rotina diária — temas das primeiras aulas do curso. Pratique dizendo a que horas você faz cada coisa no seu dia."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: in, on e at para tempo e lugar",url:"/blog/in-on-at-tempo-lugar"},{label:"Como marcar um horário por telefone em inglês",url:"/blog/marcar-consulta-por-telefone-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("say-tell-speak-talk-diferenca", "Vocabulário e uso", "Say, tell, speak e talk: qual é a diferença e como usar cada um?", "Quatro verbos, duas traduções (‘dizer’ e ‘falar’) e estruturas diferentes. Veja a regra prática, exemplos, expressões fixas e os erros que mais confundem.", "Aa", ["say tell speak talk diferença", "verbos falar inglês", "como usar say e tell", "diferença say tell", "speak ou talk", "say tell speak talk exemplos"], "Say, tell, speak e talk traduzem ‘dizer’ ou ‘falar’, mas o inglês escolhe cada um conforme a estrutura da frase, não o significado isolado. A chave é lembrar o que costuma vir depois de cada verbo: say foca no conteúdo, tell exige a pessoa que recebe a informação, e speak e talk descrevem o ato de conversar. Neste guia você vê a regra prática com muitos exemplos e os deslizes mais comuns de brasileiros.", [
    section("A regra prática em uma frase", ["Para não travar na hora de falar, guarde este resumo: você say something (diz algo), tell someone something (conta algo a alguém), e speak/talk about something (fala sobre algo, conversa). A diferença mais útil é entre say e tell.", "Say costuma vir direto com o que foi dito. Tell quase sempre precisa da pessoa logo depois: tell me, tell him, tell us. Já speak e talk são verbos de conversa, geralmente com to ou about."], undefined, ["say + algo dito: say something (to someone)", "tell + pessoa + algo: tell someone something", "speak / talk + to/about: speak to someone, talk about something"]),
    section("Say: o foco está no conteúdo", ["Say destaca as palavras ditas. Se você quiser mencionar quem ouviu, precisa da preposição to: say something to someone — nunca say me.", "Say também aparece em discurso indireto e em frases muito comuns do dia a dia."], ["She said hello. — Ela disse olá.", "He said (that) he was tired. — Ele disse que estava cansado.", "Can you say that again? — Pode repetir isso?", "say me ✗ → say to me ✓"]),
    section("Tell: informação dirigida a alguém", ["Tell normalmente vem seguido da pessoa que recebe a informação, sem preposição: tell me, tell her, tell them. Por isso é o verbo de instruções e informações diretas.", "Tell também forma várias expressões fixas que vale memorizar: tell a story, tell the truth, tell a lie, tell the time, tell the difference."], ["Tell me your name. — Diga-me seu nome.", "They told us a story. — Eles nos contaram uma história.", "Always tell the truth. — Sempre diga a verdade.", "tell to me ✗ → tell me ✓"]),
    section("Speak e talk: falar e conversar", ["Speak e talk descrevem o ato de falar. São muito próximos, mas speak pode soar um pouco mais formal e aparece com idiomas (speak English) e em situações de fala formal (speak to a manager). Talk é mais associado a conversa informal.", "Os dois usam to someone (ou with someone) e about something. Em muitos contextos são intercambiáveis: I need to speak/talk to you."], ["Do you speak English? — Você fala inglês?", "I talked to my friend for an hour. — Conversei com meu amigo por uma hora.", "Can I speak to the manager? — Posso falar com o gerente?", "We talked about the trip. — Conversamos sobre a viagem."]),
    section("Erros comuns com esses verbos", ["O erro mais comum é usar tell sem a pessoa (tell a word to the group ✗) ou say com a pessoa direta (he said me ✗). Também é frequente traduzir “falar inglês” como talk English, quando o natural é speak English.", "Para fixar, repita mini-frases trocando os verbos: say hello, tell me a secret, speak slowly, talk about music. A estrutura certa entra com repetição."], ["He said me the news. ✗ → He told me the news. ✓", "I want to tell something. ✗ → I want to tell you something. ✓", "I talk English. ✗ → I speak English. ✓"]),
    section("Perguntas frequentes", ["É “say to me” ou “tell me”? Ambos existem, mas com estruturas diferentes: say something to me ou tell me something. Qual uso para idiomas? Speak: she speaks three languages. Speak e talk são iguais? Quase: talk tende ao informal e à conversa; speak, ao formal e ao ato de falar. Na dúvida entre os dois, qualquer um costuma funcionar."]),
    section("Continue praticando", ["Esses quatro verbos aparecem o tempo todo em conversas e provas. As aulas do curso os apresentam em diálogos, e vale combinar este tema com o estudo de perguntas e de como se apresentar em inglês."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como se apresentar em inglês",url:"/blog/frases-para-se-apresentar-em-ingles"},{label:"Veja também: do ou make",url:"/blog/do-ou-make-em-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("do-ou-make-em-ingles", "Vocabulário e uso", "Do ou make em inglês: qual é a diferença e quando usar cada um?", "Do e make traduzem ‘fazer’, mas não são intercambiáveis. Veja a lógica por trás dos dois, as combinações mais comuns, listas prontas e os erros que mais confundem brasileiros.", "Do/Make", ["do ou make", "diferença do make", "do ou make em inglês", "quando usar do e make", "collocations do make", "do make inglês exemplos"], "Do e make são um clássico problema de quem aprende inglês: os dois significam ‘fazer’ em português, mas o inglês escolhe um ou outro conforme a palavra que vem junto. A escolha não é aleatória — existe uma tendência geral — mas o caminho mais seguro é aprender as combinações (collocations) como blocos prontos. Neste guia você vê a lógica, as listas mais úteis e os deslizes mais frequentes.", [
    section("A diferença geral entre do e make", ["Como regra de bolso: do costuma aparecer com tarefas, obrigações e atividades gerais, muitas vezes sem resultado concreto visível. Make costuma aparecer quando você cria, produz ou causa algo — algo que passa a existir depois da ação.", "Pense assim: você do an activity (realiza uma atividade), mas make a product (produz um resultado). Essa imagem resolve muitos casos, mas não todos — por isso as listas abaixo são tão úteis quanto a regra."], undefined, ["do → tarefa, atividade, obrigação (foco no processo)", "make → criar, produzir, causar (foco no resultado)"]),
    section("Combinações comuns com DO", ["Do aparece em tarefas do dia a dia, trabalho, estudo e atividades físicas. Também é o verbo das tarefas domésticas em geral e de expressões vagas como do something ou do nothing.", "Guarde estas combinações como blocos — elas cobrem boa parte do uso cotidiano de do."], ["do homework / do the housework — fazer a lição / as tarefas de casa", "do the dishes / do the laundry — lavar a louça / a roupa", "do exercise / do yoga / do your best — fazer exercício / yoga / o seu melhor", "do a course / do business / do research — fazer um curso / negócios / pesquisa"]),
    section("Combinações comuns com MAKE", ["Make aparece quando algo é criado ou preparado — comida, planos, decisões — e em muitas expressões sobre comunicação e relações.", "Note que erros e barulho levam make: make a mistake, make noise. E decisões, planos e progresso também: make a decision, make plans, make progress."], ["make breakfast / make a cake / make coffee — preparar o café / um bolo / café", "make a decision / make a plan / make an appointment — tomar uma decisão / fazer um plano / marcar um horário", "make a mistake / make noise / make a mess — cometer um erro / fazer barulho / bagunça", "make friends / make money / make progress — fazer amigos / ganhar dinheiro / progredir"]),
    section("Erros comuns com do e make", ["O erro mais frequente é traduzir direto do português e escolher o verbo errado. “Fazer um erro” vira make a mistake, não do a mistake. “Fazer uma pergunta” não é make a question nem do a question, e sim ask a question. “Fazer uma festa” costuma ser have a party ou throw a party.", "Por isso, desconfie da tradução literal: muitas vezes o inglês nem usa do nem make. Quando surgir a dúvida, procure a collocation real em um dicionário de inglês e anote a frase inteira."], ["do a mistake ✗ → make a mistake ✓", "make a question ✗ → ask a question ✓", "do a party ✗ → have a party ✓", "make homework ✗ → do homework ✓"]),
    section("Como memorizar as collocations", ["Decorar listas soltas funciona pouco. O que fixa é encontrar a expressão em uma frase, repetir em contextos diferentes e produzir a sua própria frase. Escolha cinco combinações por semana e use cada uma em algo real da sua rotina.", "Um bom exercício é descrever o seu dia alternando os dois verbos: o que você do (tarefas) e o que você make (resultados)."], ["Every morning I make breakfast and do the dishes. — Toda manhã preparo o café e lavo a louça.", "I need to make a decision and do my homework today. — Preciso tomar uma decisão e fazer minha lição hoje."]),
    section("Perguntas frequentes sobre do e make", ["Existe uma regra que resolve todos os casos? Não. A tendência (do = atividade, make = criar) ajuda, mas há combinações fixas que você aprende pelo uso. É “do a favor” ou “make a favor”? É do someone a favor. É “make a shower”? Não — é have a shower ou take a shower.", "Quanto mais você ler e ouvir inglês, mais essas duplas entram no automático. Não tente deduzir cada uma: colecione as que aparecem com mais frequência."]),
    section("Continue ampliando o vocabulário", ["As collocations são a base de um inglês natural. As aulas do curso apresentam do e make em situações cotidianas, e vale combinar este tema com o estudo de como aprender e fixar vocabulário novo."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como aprender vocabulário e lembrar das palavras",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Veja também: say, tell, speak e talk",url:"/blog/say-tell-speak-talk-diferenca"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("in-on-at-tempo-lugar", "Gramática essencial", "Quando usar in, on e at para tempo e lugar?", "Um guia completo para escolher entre in, on e at em horários, datas e lugares, com exemplos, erros comuns e expressões fixas.", "⌖", ["in on at", "preposições inglês", "in on at tempo", "in on at lugar", "quando usar in on at", "preposições de tempo e lugar inglês"], "In, on e at estão entre as preposições mais usadas — e mais confundidas — do inglês. A boa notícia é que existe uma lógica de escala que resolve a maioria dos casos: pense em in para o que é amplo ou fechado, on para superfícies e dias, e at para pontos específicos. Neste guia você vai ver essa lógica aplicada a tempo e a lugar, os erros mais comuns de quem fala português e as expressões fixas que vale memorizar de uma vez.", [
    section("A lógica das três preposições", ["Antes de decorar listas, vale entender a imagem por trás de cada preposição. Pense em um zoom: in é a visão mais ampla ou algo que envolve por todos os lados; on é uma superfície ou uma linha; at é um ponto preciso no mapa ou no relógio.", "Essa mesma lógica vale para tempo e para lugar, o que facilita a memória. Um ano (in 2026) é um período longo; um dia (on Monday) é um ponto numa linha de dias; uma hora (at 7 o’clock) é um instante exato. Quando tiver dúvida, pergunte-se: isto é amplo, uma superfície ou um ponto?"], undefined, ["in → amplo ou fechado: in Brazil, in 2026, in the box", "on → superfície ou dia: on the table, on Monday, on the wall", "at → ponto exato: at home, at 8 o’clock, at the door"]),
    section("In, on e at para falar de tempo", ["Use in com períodos longos: meses, estações, anos, décadas, séculos e partes do dia. Use on com dias e datas específicas. Use at com horários exatos e alguns momentos pontuais.", "Repare que partes do dia levam in (in the morning, in the afternoon, in the evening), mas night é a exceção clássica: diz-se at night. Datas completas combinam on com o dia: on July 4th."], ["in July / in 2026 / in the winter / in the morning", "on Monday / on July 4th / on my birthday / on the weekend (EUA)", "at 8:30 / at noon / at night / at Christmas (o período)"], ["Períodos longos e partes do dia: in", "Dias e datas: on", "Horas e pontos no tempo: at"]),
    section("In, on e at para falar de lugar", ["Para lugar, use in com espaços fechados ou áreas amplas (países, cidades, cômodos, veículos onde você entra). Use on com superfícies, linhas e meios de transporte públicos. Use at com pontos específicos, endereços e eventos.", "A diferença entre in e at aparece bem com lugares: in London fala da cidade como área; at the station fala do ponto exato onde você está. Com transporte, note o contraste: in a car ou in a taxi, mas on a bus, on a train e on a plane."], ["in the kitchen / in Brazil / in a taxi", "on the table / on the second floor / on the bus", "at the bus stop / at the door / at a concert"]),
    section("Os erros mais comuns de quem fala português", ["Alguns usos não têm tradução direta e geram erro. Em português dizemos “na rua”, mas em inglês o comum é on the street (ou in the street em inglês britânico, com leve diferença de sentido). “Chegar” também confunde: usa-se arrive in com cidades e países e arrive at com lugares específicos, nunca arrive to.", "Outro ponto é o fim de semana: at the weekend no inglês britânico e on the weekend no americano. E cuidado com in time (a tempo, com folga) versus on time (pontualmente, na hora marcada)."], ["arrive in Brazil / arrive at the airport (não “arrive to”)", "on the street (EUA) — na rua", "We got there just in time. — Chegamos bem a tempo.", "The train left on time. — O trem saiu no horário."]),
    section("Expressões fixas que vale memorizar", ["Algumas combinações são convencionais e é mais rápido guardá-las como blocos do que aplicar a regra. Muitas ligam at a lugares do cotidiano sem artigo.", "Anote cada expressão junto de uma frase sua — assim você aprende o uso, não só a tradução da preposição isolada."], ["at home / at work / at school / at university", "in bed / in hospital / in prison", "on TV / on the radio / on the phone / on the internet", "in the end (enfim) / at the end (no final de algo)"]),
    section("Perguntas frequentes sobre in, on e at", ["É at night ou in the night? No uso geral, diz-se at night (I don’t work at night). In the night aparece em contextos mais específicos ou literários. É on ou in com dias? Dias levam on: on Friday, on my day off. É arrive in ou arrive at? Use arrive in para cidades e países e arrive at para pontos como aeroporto, estação ou escritório.", "Essas preposições só entram na memória com repetição em contexto. Faça frases sobre a sua própria rotina — a que horas você acorda (at), em que dias estuda (on) e em que meses viaja (in)."]),
    section("Continue praticando preposições", ["O jeito mais eficiente de fixar in, on e at é ver as três em frases reais e tentar produzir as suas. As aulas iniciais do curso trazem horários, dias e lugares exatamente nesses contextos, e os simulados cobram preposições em questões de uso."], undefined, undefined, [{label:"Comece pelas aulas de inglês do nível A1",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Veja também: como dizer as horas em inglês",url:"/blog/como-dizer-horas-em-ingles"},{label:"Treine com os simulados de inglês grátis",url:"/simulados"}]),
  ], "9 min"),
  article("simple-present-vs-present-continuous", "Gramática essencial", "Simple present ou present continuous: qual usar e quando?", "Compare o presente simples e o presente contínuo em inglês: hábitos e fatos contra ações de agora, com formas, marcadores de tempo, verbos de estado e erros comuns.", "↔", ["simple present present continuous", "presente simples contínuo", "diferença simple present present continuous", "quando usar present continuous", "ing presente inglês", "verbos de estado inglês"], "O simple present e o present continuous são os dois tempos do presente em inglês, e a dúvida entre eles é constante no começo. A diferença é de foco: o simple present fala de hábitos, rotinas e fatos gerais — coisas verdadeiras em geral; o present continuous fala do que está acontecendo agora ou de situações temporárias. Neste guia você vê as formas, os marcadores de tempo que ajudam a escolher e uma pegadinha importante: os verbos de estado.", [
    section("A diferença em uma frase", ["Use o simple present para o que é habitual ou permanente: I work in a bank (sempre), water boils at 100°C (fato). Use o present continuous para o que está em andamento agora ou nestes dias: I’m working from home this week (temporário).", "A mesma pessoa pode dizer as duas coisas: He works at a café (é o emprego dele) e He’s working late tonight (ação de hoje). O verbo é o mesmo; o tempo muda o sentido."], undefined, ["simple present → hábito, rotina, fato geral", "present continuous → ação agora, situação temporária"]),
    section("Como formar cada tempo", ["O simple present usa o verbo na forma base, acrescentando -s na terceira pessoa (he/she/it): I work, she works. Nas perguntas e negativas, use do/does: Do you work? She doesn’t work.", "O present continuous usa to be (am/is/are) + verbo com -ing: I am working, they are working. A pergunta inverte o be: Are you working? A negativa acrescenta not: She isn’t working."], ["I work / she works / they work", "Do you work here? / She doesn’t work on Sundays.", "I’m studying now. / Are you studying? / He isn’t studying."]),
    section("Marcadores de tempo que ajudam", ["Certas palavras denunciam o tempo certo. O simple present combina com always, usually, often, sometimes, never, every day, on Mondays. O present continuous combina com now, right now, at the moment, today, this week, currently.", "Esses marcadores são pistas úteis, mas não substituem o sentido da frase — o que decide é se a ação é habitual ou está em andamento."], ["I usually get up at seven. — Normalmente acordo às sete.", "Look! It’s raining right now. — Olha! Está chovendo agora.", "She’s learning French this year. — Ela está aprendendo francês este ano."]),
    section("A pegadinha: verbos de estado", ["Alguns verbos normalmente não entram no present continuous, mesmo falando do agora. São os verbos de estado (stative verbs): like, love, hate, want, need, know, understand, believe, remember, seem, e os sentidos como see, hear. Com eles, use o simple present.", "Por isso dizemos I understand (não I’m understanding) e I want coffee (não I’m wanting). O caso famoso de propaganda I’m lovin’ it é informal e proposital — o padrão é I love it."], ["I want a coffee. — Quero um café. (não ‘I’m wanting’)", "She knows the answer. — Ela sabe a resposta. (não ‘is knowing’)", "I don’t understand. — Não entendo. (não ‘I’m not understanding’)"]),
    section("Erros comuns de brasileiros", ["O erro mais frequente é esquecer o -s da terceira pessoa no simple present: She work ✗ → She works ✓. Outro é usar o present continuous para hábitos, por influência do gerúndio português: ‘Eu estou trabalhando todo dia’ não é I’m working every day, e sim I work every day.", "Também é comum colocar verbos de estado no -ing (I’m knowing ✗). Para fixar, descreva a sua rotina (simple present) e depois o que você está fazendo neste momento (present continuous)."], ["He study English. ✗ → He studies English. ✓", "I’m going to the gym every day. ✗ → I go to the gym every day. ✓", "I’m needing help. ✗ → I need help. ✓"]),
    section("Perguntas frequentes", ["O present continuous pode falar de futuro? Sim — para planos combinados: I’m meeting her tomorrow. Todo verbo com -ing é present continuous? Não; -ing também aparece em gerúndios e outros tempos. ‘Always’ nunca vai com continuous? Vai, para reclamar de algo repetitivo: He’s always losing his keys."]),
    section("Continue praticando", ["Dominar os dois presentes é a base para falar da sua rotina e do seu momento. As aulas iniciais do curso trabalham justamente rotina e ações em andamento, e este tema conecta bem com o estudo de advérbios de frequência."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Como fazer perguntas em inglês",url:"/blog/como-fazer-perguntas-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "9 min"),
  article("simple-past-verbos-regulares-irregulares", "Gramática essencial", "Simple past: como usar o passado em inglês com verbos regulares e irregulares", "Aprenda a formar frases no passado em inglês, com as regras do -ed, os verbos irregulares mais comuns, perguntas, negativas e os erros que mais confundem.", "D", ["simple past", "simple past verbos regulares irregulares", "passado em inglês", "como usar o simple past", "verbos irregulares inglês", "regra do ed passado"], "O simple past é o tempo que você usa para falar de ações concluídas no passado — o que aconteceu ontem, no ano passado ou em qualquer momento já encerrado. A forma afirmativa tem dois caminhos: verbos regulares recebem -ed e verbos irregulares têm formas próprias. Já as perguntas e negativas seguem um padrão único com did. Neste guia você vê as regras, os verbos mais frequentes e os deslizes mais comuns de quem fala português.", [
    section("Quando usar o simple past", ["Use o simple past para ações terminadas em um momento passado, muitas vezes com marcadores de tempo como yesterday, last week, in 2020, two days ago ou when I was young. O foco está no que aconteceu e já acabou.", "Diferente do português, o verbo não muda com a pessoa: I worked, you worked, she worked — a forma é a mesma para todos. Isso vale tanto para regulares quanto para irregulares."], ["I watched a film yesterday. — Assisti a um filme ontem.", "We traveled to Chile last year. — Viajamos para o Chile no ano passado.", "He finished the course two months ago. — Ele terminou o curso há dois meses."]),
    section("Verbos regulares: a regra do -ed", ["A maioria dos verbos é regular: basta acrescentar -ed à forma base. Mas há pequenos ajustes de ortografia. Verbos terminados em -e recebem só -d (live → lived). Verbos terminados em consoante + y trocam o y por -ied (study → studied). E verbos curtos terminados em consoante-vogal-consoante tônica dobram a última letra (stop → stopped).", "A escrita é regular, mas a pronúncia do -ed varia entre /t/, /d/ e /ɪd/. Vale treinar esse som à parte para não criar uma sílaba a mais onde não existe."], ["work → worked / play → played", "live → lived / arrive → arrived", "study → studied / try → tried", "stop → stopped / plan → planned"], ["Terminou em -e? Só -d.", "Consoante + y? Troque por -ied.", "Consoante-vogal-consoante tônica? Dobre a consoante."]),
    section("Verbos irregulares: os mais comuns", ["Os verbos irregulares não seguem o -ed e precisam ser aprendidos um a um — mas a boa notícia é que os mais usados no dia a dia são poucos e se repetem muito. Em vez de decorar uma lista enorme, aprenda os campeões de frequência dentro de frases.", "Repare que alguns mudam totalmente (go → went), outros mudam só a vogal (begin → began) e alguns ficam iguais (put → put, cut → cut)."], ["be → was/were / have → had / do → did", "go → went / come → came / get → got", "see → saw / make → made / take → took", "say → said / give → gave / know → knew"]),
    section("Perguntas e negativas com did", ["Aqui está a parte que simplifica tudo: nas perguntas e negativas, o passado fica no auxiliar did, e o verbo principal volta à forma base. Ou seja, você não repete o -ed nem a forma irregular.", "Esse é um dos erros mais comuns de brasileiros: dizer “Did you went?”. O certo é Did you go? — o did já marca o passado, então went volta a go."], ["Did you call her? — Você ligou para ela?", "I didn’t go to the party. — Eu não fui à festa.", "She didn’t finish the test. — Ela não terminou a prova.", "What did you do yesterday? — O que você fez ontem?"]),
    section("Erros comuns no simple past", ["Além do “Did you went?”, há outros tropeços frequentes. Um é esquecer o -ed em verbos regulares na fala (dizer I work yesterday em vez de I worked). Outro é usar was/were com did (She wasn’t went). E há a confusão com o present perfect: com um tempo passado definido, o inglês pede simple past, não present perfect.", "Para fixar, conte uma história curta sobre o seu dia de ontem em cinco frases. Ao errar, confira a forma do verbo e refaça — o erro mostra exatamente o que revisar."], ["I didn’t saw it. ✗ → I didn’t see it. ✓", "He goed home. ✗ → He went home. ✓", "I’ve seen him yesterday. ✗ → I saw him yesterday. ✓"]),
    section("Perguntas frequentes sobre o simple past", ["Preciso decorar todos os verbos irregulares? Não de uma vez. Comece pelos 20 ou 30 mais comuns, que cobrem a maior parte das conversas, e amplie aos poucos. O verbo muda com he, she e it? Não: ao contrário do present simple (he works), o passado não acrescenta -s (he worked, para todos).", "Como diferencio simple past de present perfect? Se há um momento passado definido (yesterday, last year), use simple past. Se o foco é a experiência ou o resultado até agora, sem dizer quando, costuma ser present perfect."]),
    section("Continue praticando o passado", ["O simple past aparece em praticamente toda conversa, então vale praticá-lo em frases sobre a sua vida. As aulas do curso apresentam os verbos irregulares em contexto e os simulados cobram o passado em questões de leitura e uso.", "Depois de dominar o simple past, o próximo passo natural é compará-lo com o present perfect, que muda o foco do tempo."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: present perfect ou simple past",url:"/blog/present-perfect-vs-simple-past"},{label:"Como pronunciar o -ed dos verbos",url:"/blog/pronunciar-ed-passado-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("como-fazer-perguntas-em-ingles", "Gramática essencial", "Como fazer perguntas em inglês? Estruturas e exemplos", "Aprenda a montar perguntas em inglês: yes/no questions, perguntas com to be, com do/does/did, com palavras interrogativas e as perguntas de sujeito, com erros comuns.", "?", ["perguntas em inglês", "como fazer perguntas inglês", "question words", "como montar pergunta inglês", "yes no questions", "wh questions inglês"], "Fazer perguntas é essencial para qualquer conversa, mas a estrutura do inglês é diferente da do português: em vez de mudar só a entonação, o inglês geralmente inverte a ordem ou usa um verbo auxiliar. A boa notícia é que há poucos padrões, e eles se repetem. Neste guia você vê os tipos de pergunta — com to be, com do/does/did, com palavras interrogativas (wh- questions) e as perguntas de sujeito — além dos erros mais comuns.", [
    section("Dois grandes tipos de pergunta", ["Há perguntas de sim/não (yes/no questions), que começam por um verbo ou auxiliar e se respondem com yes ou no, e perguntas abertas (wh- questions), que começam por uma palavra interrogativa (what, where, when…) e pedem informação.", "Em ambas, a chave é a inversão ou o uso de um auxiliar. Entendido isso, basta escolher o verbo certo."], undefined, ["yes/no → começa pelo verbo/auxiliar: Are you…? Do you…?", "wh- → começa pela palavra interrogativa: What…? Where…?"]),
    section("Perguntas com o verbo to be", ["Quando o verbo da frase é to be (am, is, are, was, were), a pergunta se forma invertendo o verbo e o sujeito — sem auxiliar. You are tired → Are you tired?", "Isso vale no presente e no passado do to be."], ["Are you tired? — Você está cansado?", "Is she your sister? — Ela é sua irmã?", "Where is the station? — Onde fica a estação?", "Were they at home? — Eles estavam em casa?"]),
    section("Perguntas com do, does e did", ["Quando o verbo principal NÃO é to be, você precisa de um auxiliar. No simple present, use do (I/you/we/they) ou does (he/she/it). No simple past, use did para todos. Depois do auxiliar, o verbo principal volta à forma base.", "É aqui que mora o erro mais comum: com does e did, o verbo principal não leva -s nem passado. Does she works ✗ → Does she work ✓."], ["Do you work here? — Você trabalha aqui?", "Does he speak English? — Ele fala inglês?", "Did she call you? — Ela ligou para você?", "What time does it start? — A que horas começa?"]),
    section("Perguntas com palavras interrogativas (wh-)", ["As wh- questions começam por who (quem), what (o quê), where (onde), when (quando), why (por quê), which (qual), whose (de quem) e how (como). A palavra interrogativa vem primeiro; depois segue a mesma estrutura com to be ou com auxiliar.", "How combina com outras palavras para medir: how much (quanto, incontável), how many (quantos), how long (quanto tempo), how old (que idade)."], ["What do you like? — Do que você gosta?", "Where are you from? — De onde você é?", "Why did you leave? — Por que você foi embora?", "How much is this? — Quanto custa isto?"]),
    section("A exceção: perguntas de sujeito", ["Há um caso especial. Quando a pergunta é sobre o sujeito da frase (quem ou o que faz a ação), você NÃO usa do/does/did — o verbo fica na forma afirmativa normal. Compare: Who called you? (quem é o sujeito) não leva did, mas Who did you call? (você é o sujeito) leva.", "Essa diferença confunde, mas a regra é: se who/what é quem pratica a ação, pergunte direto, sem auxiliar."], ["Who lives here? — Quem mora aqui? (não ‘Who does live’)", "What happened? — O que aconteceu? (não ‘What did happen’)", "Who wants coffee? — Quem quer café?"]),
    section("Erros comuns ao perguntar", ["Além do ‘Does she works?’, outros deslizes frequentes: esquecer o auxiliar (You like coffee? em vez de Do you like coffee?), usar auxiliar com to be (Do you are tired? ✗ → Are you tired? ✓), e repetir o passado (Did you went? ✗ → Did you go? ✓).", "Para fixar, transforme frases afirmativas em perguntas: She works here → Does she work here? He went home → Did he go home?"], ["Does she works? ✗ → Does she work? ✓", "Do you are happy? ✗ → Are you happy? ✓", "Did you went? ✗ → Did you go? ✓"]),
    section("Perguntas frequentes", ["Como faço uma pergunta educada e indireta? Use Could you tell me…? seguido da ordem afirmativa: Could you tell me where the station is? Preciso de do/does com ‘can’, ‘will’? Não — modais (can, will, should) invertem direto: Can you help? Where está sempre com to be? Não; depende do verbo: Where do you live? usa do."]),
    section("Continue praticando", ["Perguntar bem é o que mantém uma conversa viva. As aulas do curso trabalham perguntas desde o início, e vale combinar este tema com as perguntas indiretas e educadas e com o estudo do present e do past simple."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Perguntas indiretas e mais educadas",url:"/blog/perguntas-indiretas-educadas-ingles"},{label:"Simple present ou present continuous",url:"/blog/simple-present-vs-present-continuous"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("there-is-there-are", "Gramática essencial", "There is e there are: como dizer que algo existe em inglês", "Aprenda a usar there is e there are para dizer que algo existe ou está em um lugar, no singular, no plural, em perguntas, negativas e outros tempos verbais.", "∃", ["there is there are", "there is there are diferença", "existe em inglês", "como usar there is there are", "there was there were", "há em inglês there is"], "There is e there are são a forma de dizer em inglês que algo existe ou está presente em um lugar — equivalem ao nosso ‘há’, ‘tem’ ou ‘existe(m)’. A escolha entre os dois depende de uma coisa só: se o que vem depois está no singular ou no plural. Neste guia você aprende a regra, as contrações, as perguntas e negativas, as versões no passado e no futuro, e os erros mais comuns.", [
    section("A regra básica: singular ou plural", ["Use there is com um substantivo no singular ou incontável, e there are com substantivos contáveis no plural. O que decide o verbo é o substantivo que vem logo depois — não a ideia de quantidade em geral.", "Em português dizemos ‘há’ ou ‘tem’ para os dois casos; em inglês, o verbo concorda com o que existe. There is a book (um livro); there are three books (três livros)."], ["There is a café nearby. — Há um café aqui perto.", "There are two cafés on this street. — Há dois cafés nesta rua.", "There is some water in the bottle. — Há um pouco de água na garrafa."], ["there is → singular e incontáveis", "there are → plural"]),
    section("Contrações e uso na fala", ["Na fala e na escrita informal, there is vira there’s. Já there are raramente é contraído na escrita, mas na fala soa como there’re, bem reduzido.", "Um detalhe de inglês falado: quando há uma lista começando no singular, é comum ouvir there’s mesmo antes de um plural (There’s a pen and two books). É aceito na conversa, mas na escrita cuidadosa o ideal é concordar com o primeiro item."], ["There’s a problem. — Há um problema.", "There’s a café and two shops. — Tem um café e duas lojas. (fala)"]),
    section("Perguntas e respostas curtas", ["Para perguntar, inverta there e o verbo: Is there…? / Are there…? As respostas curtas repetem o verbo: Yes, there is / No, there isn’t; Yes, there are / No, there aren’t.", "Com perguntas, é muito comum usar any antes de plurais e incontáveis: Is there any milk? Are there any seats?"], ["Is there a bank nearby? — Há um banco aqui perto?", "Are there any questions? — Há alguma pergunta?", "Yes, there is. / No, there aren’t. — Há, sim. / Não há."]),
    section("Negativas: isn't, aren't e no/any", ["Para negar, acrescente not ao verbo: there isn’t, there aren’t. Com substantivos contáveis no plural e incontáveis, use any na negativa: there isn’t any, there aren’t any.", "Você também pode negar com no e sem any: There is no sugar = There isn’t any sugar. As duas formas são corretas."], ["There isn’t a pharmacy here. — Não há farmácia aqui.", "There aren’t any chairs. — Não há cadeiras.", "There is no time. — Não há tempo."]),
    section("There was, there were e there will be", ["There is / there are muda com o tempo verbal. No passado, use there was (singular/incontável) e there were (plural). No futuro, use there will be para os dois. Com modais e present perfect, é there might be, there has been, etc.", "A lógica de singular x plural continua a mesma no passado: o verbo concorda com o substantivo."], ["There was a party last night. — Houve uma festa ontem à noite.", "There were many people there. — Havia muitas pessoas lá.", "There will be a test next week. — Haverá uma prova na semana que vem."]),
    section("Erros comuns com there is / there are", ["O erro mais frequente de brasileiros é usar have para dizer ‘há’ ou ‘tem’: “Have a café here” (✗). Em inglês, existência é there is/there are; have é posse (I have a car). Outro deslize é não concordar o verbo: there is two books (✗) → there are two books.", "Cuidado também com it is x there is: It is a café = é um café (identifica); There is a café = há um café (afirma que existe)."], ["Have many people here. ✗ → There are many people here. ✓", "There is three rooms. ✗ → There are three rooms. ✓"]),
    section("Perguntas frequentes", ["There’s pode ser usado com plural? Na fala informal, às vezes sim, mas na escrita use there are com plural. Como digo ‘não tem nada’? There isn’t anything / There is nothing. Qual a diferença de there is para it is? There is afirma existência; it is identifica ou descreve algo específico."]),
    section("Continue praticando", ["There is e there are aparecem em descrições de lugares, casas e cidades — temas das primeiras aulas do curso. Vale combinar este tema com o estudo de artigos (a, an, the) e de quantificadores (some, any, much, many)."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: a, an e the",url:"/blog/a-an-the-artigos-ingles"},{label:"Some, any, much e many",url:"/blog/some-any-much-many"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("some-any-much-many", "Gramática essencial", "Some, any, much e many: como falar de quantidades em inglês", "Aprenda a escolher entre some, any, much, many e a lot of conforme o substantivo e o tipo de frase, com a base de contáveis e incontáveis e os erros mais comuns.", "∑", ["some any much many", "quantificadores inglês", "contáveis incontáveis", "diferença some any", "much ou many", "a lot of inglês"], "Some, any, much, many e a lot of são os quantificadores: palavras que indicam quantidade sem dar um número exato. Escolher o certo depende de duas coisas — se o substantivo é contável ou incontável, e se a frase é afirmativa, negativa ou pergunta. Entendida essa base, o resto se encaixa. Neste guia você vê a regra de cada um, como combiná-los e os deslizes mais comuns de brasileiros.", [
    section("A base: contáveis e incontáveis", ["Antes de escolher o quantificador, identifique o substantivo. Contáveis podem ser contados e têm plural: a book / two books, an apple / apples. Incontáveis não se contam em unidades e não têm plural normal: water, time, money, information, advice.", "Essa distinção decide muita coisa: many e few vão com contáveis; much e little vão com incontáveis. Alguns substantivos que são contáveis em português são incontáveis em inglês (information, advice, furniture), o que gera erro."], undefined, ["contáveis → a car, cars; an idea, ideas", "incontáveis → water, money, time, information"]),
    section("Many com contáveis, much com incontáveis", ["Use many com substantivos contáveis no plural (many books, many people) e much com incontáveis (much time, much water). Nas perguntas de quantidade, isso aparece em How many? (quantos) e How much? (quanto).", "Na prática, much e many em frases afirmativas soam formais; na conversa do dia a dia, a lot of é muito mais comum. Já em perguntas e negativas, much e many são naturais."], ["How many people are coming? — Quantas pessoas vêm?", "How much water do we need? — De quanta água precisamos?", "I don’t have much time. — Não tenho muito tempo.", "There aren’t many seats. — Não há muitos lugares."]),
    section("Some e any: a regra prática", ["Use some em frases afirmativas e em ofertas/pedidos educados; use any em perguntas neutras e em negativas. Os dois servem para contáveis no plural e para incontáveis.", "Há duas exceções importantes com some e any. Some aparece em perguntas quando você oferece ou pede algo (Would you like some coffee?). E any pode significar ‘qualquer’ em frases afirmativas (Any ticket works)."], ["We have some apples. — Temos algumas maçãs.", "Do you have any questions? — Você tem alguma pergunta?", "There isn’t any milk. — Não há leite nenhum.", "Would you like some tea? — Você aceita um chá?"]),
    section("A lot of: o coringa da conversa", ["A lot of (ou lots of, mais informal) combina tanto com contáveis quanto com incontáveis e é a forma mais usada na conversa para dizer ‘muito/muitos’ em frases afirmativas: a lot of friends, a lot of money.", "Por isso, quando estiver em dúvida entre much e many numa afirmação, a lot of quase sempre resolve e soa natural."], ["She has a lot of friends. — Ela tem muitos amigos.", "We spent a lot of money. — Gastamos muito dinheiro.", "There’s lots of time. — Há bastante tempo."]),
    section("Few, little e outras quantidades", ["Para pouca quantidade: a few vai com contáveis (a few friends = alguns amigos) e a little com incontáveis (a little time = um pouco de tempo). Sem o a, few e little ganham tom negativo (few friends = poucos amigos, quase nenhum).", "Esses quantificadores completam o quadro e deixam a fala mais precisa."], ["I have a few questions. — Tenho algumas perguntas.", "There’s a little milk left. — Sobrou um pouco de leite.", "Few people came. — Pouca gente veio."]),
    section("Erros comuns de brasileiros", ["Os deslizes mais frequentes: usar many com incontável (many informations ✗ → much information ✓, e sem -s: information não tem plural), usar some em pergunta neutra (Do you have some money? em vez de any), e traduzir ‘muito’ sempre por very (very people ✗ → many people ✓).", "Lembre também que advice, information, furniture e money são incontáveis: an advice ✗ → a piece of advice ✓."], ["many informations ✗ → much information ✓", "Do you have some time? (neutra) → Do you have any time? ✓", "very friends ✗ → many friends ✓"]),
    section("Perguntas frequentes", ["Some vai em pergunta? Sim, em ofertas e pedidos: Can I have some water? É much ou many com ‘money’? Money é incontável: much money. ‘A lot of’ é informal demais? Não — é neutro e serve em quase tudo; em textos muito formais, much/many podem ser preferidos. Qual a diferença de ‘few’ para ‘a few’? A few = alguns (positivo); few = poucos (negativo)."]),
    section("Continue praticando", ["Os quantificadores aparecem sempre que você fala de compras, comida, tempo e dinheiro. As aulas do curso os apresentam em contexto, e este tema conecta diretamente com there is/there are e com os artigos a, an, the."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: there is e there are",url:"/blog/there-is-there-are"},{label:"A, an e the: os artigos",url:"/blog/a-an-the-artigos-ingles"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("pronunciar-ed-passado-ingles", "Pronúncia", "Como pronunciar o -ed dos verbos no passado em inglês?", "A terminação -ed tem três sons: /t/, /d/ e /ɪd/. Aprenda a regra, por que ela existe, exemplos de cada caso e os erros de pronúncia mais comuns de brasileiros.", "ED", ["pronunciar ed inglês", "pronúncia verbos passado", "final ed", "três sons do ed", "ed id t d pronúncia", "como pronunciar ed passado"], "A terminação -ed dos verbos regulares no passado é escrita sempre igual, mas pronunciada de três formas diferentes: /t/, /d/ ou /ɪd/. A escolha não é aleatória — depende do último som do verbo antes do -ed. O erro mais comum de brasileiros é pronunciar todo -ed como ‘-ed’ ou ‘-did’, criando uma sílaba a mais onde não existe. Neste guia você aprende a regra, entende a lógica e pratica com exemplos de cada caso.", [
    section("As três pronúncias do -ed", ["O -ed pode soar como /ɪd/ (uma sílaba extra, tipo ‘id’), /t/ (sem sílaba extra) ou /d/ (sem sílaba extra). O que decide é o som final do verbo — não a letra, o som. Só o caso /ɪd/ acrescenta uma sílaba; nos outros dois, o -ed cola no verbo sem aumentar o número de sílabas.", "Essa é a base: na maioria dos verbos, o -ed NÃO vira uma sílaba nova. Dizer ‘work-ed’ com duas sílabas é o erro mais comum."], undefined, ["/ɪd/ → sílaba extra (depois de /t/ e /d/)", "/t/ → sem sílaba extra (depois de som surdo)", "/d/ → sem sílaba extra (depois de som sonoro ou vogal)"]),
    section("Som /ɪd/: a única sílaba extra", ["Quando o verbo termina no som /t/ ou /d/, o -ed é pronunciado /ɪd/ e cria uma sílaba a mais — porque seria impossível juntar os sons sem ela. Este é o único caso em que o -ed ‘ganha’ uma sílaba.", "Repare: want tem uma sílaba, wanted tem duas; need tem uma, needed tem duas."], ["wanted — /ˈwɒntɪd/ (want-ed)", "needed — /ˈniːdɪd/ (need-ed)", "decided, started, visited, ended — todos com /ɪd/"]),
    section("Som /t/: depois de sons surdos", ["Quando o verbo termina em som surdo (produzido sem vibração das cordas vocais) — como /p/, /k/, /f/, /s/, /ʃ/, /tʃ/ — o -ed soa /t/, sem sílaba extra. O verbo mantém o número de sílabas.", "Um truque: se você consegue sentir ‘ar’ saindo sem voz no final (como em wash, work), o -ed provavelmente é /t/."], ["worked — /wɜːkt/ (uma sílaba)", "washed — /wɒʃt/", "stopped, watched, laughed, kissed — todos com /t/"]),
    section("Som /d/: depois de sons sonoros e vogais", ["Quando o verbo termina em som sonoro (com vibração) ou em vogal — como /b/, /g/, /v/, /z/, /l/, /n/, /r/ e todas as vogais — o -ed soa /d/, também sem sílaba extra.", "A maioria dos verbos cai aqui, já que vogais e sons sonoros são muito comuns."], ["played — /pleɪd/ (uma sílaba)", "cleaned — /kliːnd/", "loved, lived, called, arrived, studied — todos com /d/"]),
    section("Por que isso acontece", ["A lógica é a facilidade de pronúncia. Depois de um som surdo, é natural emendar um /t/ (também surdo); depois de um som sonoro ou vogal, sai um /d/ (sonoro). E depois de /t/ ou /d/ já não dá para colar outro /t/ ou /d/, então entra o /ɪd/ para separar.", "Ou seja: você não precisa decorar listas enormes — basta sentir o último som do verbo e deixar o -ed acompanhar."]),
    section("Erros comuns de brasileiros", ["O erro mais frequente é transformar todo -ed em uma sílaba ‘-édi’ ou ‘-dÉ’: dizer ‘lík-ed’ para liked (o certo é /laɪkt/, uma sílaba) ou ‘uork-édi’ para worked. Isso acontece porque o português tende a pronunciar todas as letras. Treine sentindo que, na maioria dos verbos, o -ed é só um /t/ ou /d/ rápido no fim.", "Pratique em pares: want → wanted (/ɪd/) x like → liked (/t/) x love → loved (/d/). Ouça um modelo e repita o verbo inteiro, não só a terminação."], ["liked = /laɪkt/ (não ‘laik-édi’)", "worked = /wɜːkt/ (não ‘uork-édi’)", "só wanted, needed e parecidos ganham a sílaba extra"]),
    section("Perguntas frequentes", ["Todo -ed vira sílaba nova? Não — só depois de /t/ e /d/. Como sei se o som é /t/ ou /d/? Pelo último som do verbo: surdo → /t/, sonoro/vogal → /d/. Preciso decorar a lista de sons? Não; com prática, você passa a sentir qual sai naturalmente. Vale a leitura de voz do navegador? Para ouvir um modelo, sim; para avaliar a sua pronúncia, não."]),
    section("Continue praticando", ["A pronúncia do -ed anda junto com o aprendizado do simple past. Vale combinar este tema com a formação do passado e com a pronúncia do -s/-es do plural, que segue uma lógica parecida."], undefined, undefined, [{label:"Veja também: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Pronúncia do S e do ES no plural",url:"/blog/pronuncia-s-es-plurais-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("pronuncia-s-es-plurais-ingles", "Pronúncia", "Como pronunciar o S e o ES no final em inglês (plurais e verbos)?", "A terminação -s/-es tem três sons: /s/, /z/ e /ɪz/. Aprenda a regra pelo último som da palavra, com exemplos para plurais e verbos e os erros mais comuns.", "S/Z", ["pronúncia s plural inglês", "plural es pronúncia", "som z inglês", "três sons do s inglês", "pronúncia s z iz", "como pronunciar s final inglês"], "A terminação -s (ou -es) aparece o tempo todo em inglês: nos plurais (books, buses), nos verbos da terceira pessoa (she works, he watches) e nos possessivos. Embora seja sempre escrita igual, ela tem três pronúncias: /s/, /z/ e /ɪz/. E a lógica é a mesma do -ed do passado: o som final da palavra decide. Dominar isso deixa a fala muito mais natural. Neste guia você aprende a regra e pratica com exemplos.", [
    section("As três pronúncias do -s", ["O -s final pode soar /s/ (surdo), /z/ (sonoro) ou /ɪz/ (uma sílaba extra). O que define é o último som da palavra antes do -s — o som, não a letra. Só o caso /ɪz/ acrescenta uma sílaba; nos outros dois, o -s cola na palavra sem aumentar as sílabas.", "Essa regra vale igual para plurais de substantivos e para verbos na terceira pessoa (he/she/it)."], undefined, ["/ɪz/ → sílaba extra (depois de sons sibilantes)", "/s/ → sem sílaba extra (depois de som surdo)", "/z/ → sem sílaba extra (depois de som sonoro ou vogal)"]),
    section("Som /ɪz/: depois de sons sibilantes", ["Quando a palavra termina em um som sibilante — /s/, /z/, /ʃ/, /tʃ/, /dʒ/ (como em bus, buzz, wash, watch, judge) — o -es soa /ɪz/ e cria uma sílaba a mais, porque seria impossível emendar outro /s/ ou /z/ sem ela.", "Esses são justamente os casos em que a escrita costuma usar -es."], ["buses — /ˈbʌsɪz/ (bus-es, duas sílabas)", "watches — /ˈwɒtʃɪz/", "boxes, dishes, oranges, changes — todos com /ɪz/"]),
    section("Som /s/: depois de sons surdos", ["Quando a palavra termina em som surdo (sem vibração) — /p/, /t/, /k/, /f/ — o -s soa /s/, sem sílaba extra. A palavra mantém o número de sílabas.", "É o mesmo /s/ que você já conhece, bem leve no fim."], ["cups — /kʌps/", "cats — /kæts/", "books — /bʊks/", "works (verbo) — /wɜːks/"]),
    section("Som /z/: depois de vogais e sons sonoros", ["Quando a palavra termina em som sonoro (com vibração) ou em vogal — /b/, /d/, /g/, /l/, /m/, /n/, /r/, vogais — o -s soa /z/, também sem sílaba extra. A maioria das palavras cai aqui.", "Muita gente que fala português tende a pronunciar esse final como /s/; treinar o /z/ (com a voz vibrando) deixa a fala mais natural."], ["days — /deɪz/", "pens — /penz/", "plays (verbo) — /pleɪz/", "dogs, cars, names, lives — todos com /z/"]),
    section("A mesma lógica do -ed", ["Se você já estudou a pronúncia do -ed do passado, vai reconhecer o padrão: o som final da palavra escolhe entre surdo, sonoro e a sílaba extra. É a mesma física da fala — o que sai mais fácil depois de cada tipo de som.", "Por isso vale estudar os dois juntos: -ed e -s/-es seguem a mesma regra de três sons."]),
    section("Erros comuns de brasileiros", ["Os deslizes mais frequentes: pronunciar todo -s como /s/ (dizendo ‘dogs’ com /s/ em vez de /z/); criar uma sílaba extra onde não existe (falar ‘book-es’ para books); e esquecer o -s da terceira pessoa dos verbos (he work ✗). Treine em grupos: cats /s/, dogs /z/, buses /ɪz/, ouvindo um modelo e repetindo a palavra inteira.", "Prestar atenção ao /z/ sonoro é o que mais aproxima a sua pronúncia da natural."], ["dogs com /s/ ✗ → dogs com /z/ ✓", "book-es ✗ → books /bʊks/ ✓", "he work ✗ → he works ✓"]),
    section("Perguntas frequentes", ["Quando o -s vira sílaba nova? Só depois de sons sibilantes (/s/, /z/, /ʃ/, /tʃ/, /dʒ/). Como sei se é /s/ ou /z/? Pelo último som: surdo → /s/, sonoro/vogal → /z/. Serve para verbos também? Sim — he runs /z/, he works /s/, he watches /ɪz/. Precisa decorar a lista de sons? Não; com prática, sai naturalmente."]),
    section("Continue praticando", ["A pronúncia do -s anda junto com a do -ed e com os plurais. Combine este tema com a regra do -ed do passado e pratique a terceira pessoa do presente nas aulas do curso."], undefined, undefined, [{label:"Como pronunciar o -ed do passado",url:"/blog/pronunciar-ed-passado-ingles"},{label:"Simple present ou present continuous",url:"/blog/simple-present-vs-present-continuous"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("falsos-cognatos-ingles-portugues", "Vocabulário e uso", "Falsos cognatos em inglês: 20 palavras que enganam brasileiros", "Conheça os false friends mais comuns entre inglês e português — palavras parecidas com significado diferente — e aprenda a não cair nessas armadilhas.", "≠", ["falsos cognatos inglês português", "false friends", "palavras parecidas inglês", "falsos cognatos exemplos", "actually pretend push significado", "false friends inglês português"], "Falsos cognatos (ou false friends) são palavras que se parecem entre o inglês e o português, mas têm significados diferentes. Elas enganam porque o cérebro assume a tradução ‘óbvia’ — e erra. Dizer I pretend to travel achando que é ‘pretendo viajar’ (quando significa ‘finjo viajar’) é um clássico. Neste guia você vê os falsos cognatos que mais confundem brasileiros, agrupados para facilitar a memória, e aprende a confirmar o sentido antes de usar.", [
    section("O que são falsos cognatos", ["Cognatos de verdade são palavras parecidas com o mesmo significado (hospital, animal, important) e ajudam muito. Os falsos cognatos têm a forma parecida, mas o sentido mudou ao longo do tempo. Alguns são totalmente diferentes; outros coincidem em parte e divergem em certos usos.", "A semelhança não é inimiga — ela até ajuda a lembrar a palavra. O risco é confiar na tradução automática sem conferir o contexto."], undefined, ["cognato verdadeiro → forma e sentido parecidos (hospital)", "falso cognato → forma parecida, sentido diferente (actually = na verdade)"]),
    section("Os falsos cognatos mais comuns", ["Esta é a lista que mais pega brasileiros. Guarde o significado real de cada uma com uma frase.", "Repare que vários deles aparecem o tempo todo em textos e conversas, então vale priorizá-los."], undefined, ["actually = na verdade (não ‘atualmente’ → currently)", "pretend = fingir (não ‘pretender’ → intend/plan)", "parents = pais (não ‘parentes’ → relatives)", "push = empurrar (não ‘puxar’ → pull)", "realize = perceber (não ‘realizar’ → carry out)", "library = biblioteca (não ‘livraria’ → bookstore)", "fabric = tecido (não ‘fábrica’ → factory)", "college = faculdade (não ‘colégio’ → high school)"]),
    section("Mais armadilhas que valem memorizar", ["A lista continua com palavras do cotidiano e de textos formais. Muitos erros de prova de inglês vêm justamente desses pares.", "Anote os que você mais encontra nos seus estudos."], undefined, ["lunch = almoço (não ‘lanche’ → snack)", "costume = fantasia/traje (não ‘costume’ → habit/custom)", "exquisite = refinado (não ‘esquisito’ → weird/strange)", "comprehensive = abrangente (não ‘compreensivo’ → understanding)", "eventually = por fim (não ‘eventualmente’ → occasionally)", "notice = perceber/aviso (não ‘notícia’ → news)", "legend = lenda (não ‘legenda’ → subtitle/caption)", "attend = comparecer (não ‘atender’ → answer/assist)"]),
    section("Como confirmar o sentido de uma palavra", ["Quando uma palavra parecida aparecer, desconfie se a tradução ‘óbvia’ deixa a frase estranha. Leia a frase inteira, confira a classe gramatical (substantivo, verbo?) e consulte um dicionário de inglês, de preferência com exemplos.", "Um dicionário monolíngue (inglês-inglês) ajuda a ver o sentido real sem a interferência da tradução. Se ainda houver dúvida, procure a palavra em frases de fontes confiáveis."], ["I actually live in Recife. — Na verdade, moro em Recife.", "Push or pull? — Empurrar ou puxar?", "She works at a library. — Ela trabalha numa biblioteca (não livraria)."]),
    section("Aprenda a palavra dentro de uma frase", ["A melhor defesa contra falsos cognatos é aprender vocabulário em contexto, não em listas de tradução solta. Anote a palavra com uma combinação real e uma frase sua. Assim você fixa o significado e o uso ao mesmo tempo.", "Revise os falsos cognatos aos poucos — ao errar, confira e refaça o exemplo. O erro mostra exatamente qual par ainda engana você."]),
    section("Perguntas frequentes", ["Falsos cognatos são muitos? Há dezenas comuns, mas os que realmente aparecem no dia a dia são poucas dúzias — vale focar neles. ‘Actually’ nunca significa ‘atualmente’? Não; ‘atualmente’ é currently ou nowadays. Como ‘pretendo fazer algo’? I plan to / I intend to, nunca I pretend to (que é ‘finjo’)."]),
    section("Continue praticando", ["Reconhecer falsos cognatos melhora muito a leitura e evita gafes na fala. Combine este tema com os cognatos verdadeiros (que aceleram a leitura) e com estratégias de vocabulário."], undefined, undefined, [{label:"Veja também: cognatos que ajudam a aprender",url:"/blog/cognatos-verdadeiros-ingles-portugues"},{label:"Como aprender e fixar vocabulário",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("como-aprender-vocabulario-ingles", "Vocabulário", "Como aprender vocabulário em inglês e nunca mais esquecer as palavras", "Aprenda um método que funciona para construir vocabulário em inglês: contexto, collocations, recuperação ativa e revisão espaçada, com dicas práticas e erros a evitar.", "Aa", ["como aprender vocabulário inglês", "ampliar vocabulário", "aprender palavras inglês", "como memorizar palavras em inglês", "revisão espaçada vocabulário", "collocations aprender inglês"], "A maior frustração de quem estuda vocabulário é esquecer: você aprende uma palavra hoje e, na semana seguinte, ela sumiu. O problema quase nunca é memória ruim — é o método. Decorar listas de tradução solta é a forma menos eficiente de aprender. Neste guia você vê um processo que realmente fixa o vocabulário: escolher palavras úteis, aprendê-las em contexto com suas combinações, recuperá-las de memória e revisar de forma espaçada.", [
    section("Por que listas de tradução não funcionam", ["Uma lista com palavra em inglês de um lado e tradução do outro parece prática, mas ensina pouco sobre uso. Você memoriza um par (book = livro), mas não aprende como a palavra entra numa frase, com que outras palavras combina, nem quando é adequada.", "O vocabulário útil é o que você consegue usar — e isso exige ver e produzir a palavra em contexto, não só reconhecê-la numa lista."]),
    section("Escolha as palavras certas", ["Nem toda palavra desconhecida precisa ser estudada. Priorize as de alta frequência (as que aparecem o tempo todo) e as ligadas aos seus objetivos — trabalho, viagem, um exame, um assunto que você gosta. Guardar cada palavra rara de uma primeira leitura só gera sobrecarga.", "Uma regra prática: se a palavra apareceu mais de uma vez ou é central para entender o texto, vale aprender."], undefined, ["Priorize alta frequência e relevância ao seu objetivo", "Ignore, por ora, palavras raras e secundárias", "Foque em palavras que você vai realmente usar"]),
    section("Aprenda em contexto e com collocations", ["Registre a palavra dentro de uma frase e, principalmente, com suas combinações típicas (collocations). Em vez de só decision = decisão, aprenda make a decision e uma frase sua. Isso ensina significado e uso ao mesmo tempo.", "Um bom registro tem: a palavra, uma combinação comum e um exemplo pessoal — algo ligado à sua vida, que é mais fácil de lembrar."], ["make a decision — tomar uma decisão", "I need to make a decision today. — Preciso tomar uma decisão hoje.", "heavy rain (não ‘strong rain’) — chuva forte"]),
    section("Use a recuperação ativa", ["O que mais fixa memória não é reler, é tentar lembrar. Cubra a tradução e tente produzir a palavra; cubra a palavra e tente lembrar o significado e uma frase. Esse esforço de ‘puxar’ da memória (active recall) é o que fortalece o aprendizado.", "Flashcards (de papel ou apps) funcionam justamente por isso — mas só se você tentar lembrar antes de virar o cartão, não se apenas ler os dois lados."]),
    section("Revise de forma espaçada", ["Revisar tudo no mesmo dia e nunca mais é receita para esquecer. A revisão espaçada (spaced repetition) propõe revisar em intervalos crescentes — depois de um dia, de alguns dias, de uma semana — de preferência um pouco antes de esquecer.", "Vários apps automatizam isso, mostrando cada palavra na hora certa. O importante é voltar às palavras em dias diferentes, não tudo de uma vez."]),
    section("Produza para fixar de vez", ["Reconhecer uma palavra é diferente de saber usá-la. Para transformar vocabulário passivo em ativo, use as palavras novas: escreva uma frase, conte algo, descreva o seu dia usando-as. Ao errar, confira e refaça — o erro mostra exatamente o que revisar.", "Quanto mais você produz com a palavra, mais rápido ela vira parte do seu inglês automático."]),
    section("Perguntas frequentes", ["Quantas palavras por dia? Poucas e bem aprendidas valem mais que muitas superficiais — 5 a 10 por dia é sustentável. Preciso de app? Ajuda, mas um caderno com recuperação ativa também funciona. Devo decorar a pronúncia junto? Sim — anote ou ouça a pronúncia ao registrar. Esqueci uma palavra, e agora? Normal: reencontre-a em contexto e revise; esquecer e relembrar faz parte."]),
    section("Continue praticando", ["Vocabulário cresce com leitura, escuta e uso constante. Combine este método com estratégias de leitura e com o cuidado com falsos cognatos, e aplique tudo nas aulas e nos simulados."], undefined, undefined, [{label:"Como melhorar a leitura usando contexto",url:"/blog/como-melhorar-leitura-ingles"},{label:"Falsos cognatos: palavras que enganam",url:"/blog/falsos-cognatos-ingles-portugues"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("como-entender-ingles-falado-listening", "Listening", "Como entender inglês falado sem traduzir cada palavra", "Melhore seu listening em inglês com um método em etapas: por que você não entende, como treinar com e sem transcrição e como lidar com a fala rápida e conectada.", "♫", ["entender inglês falado", "listening inglês", "treinar compreensão oral", "como melhorar o listening", "entender inglês rápido", "por que não entendo inglês falado"], "Muita gente lê bem em inglês, mas ‘não entende nada’ quando o áudio começa — e conclui que tem um problema de ouvido. Quase sempre não é isso. Entender a fala exige lidar com velocidade, sons que se ligam e a tentação de traduzir cada palavra em tempo real, que faz você perder o resto. Listening é uma habilidade que se treina com método. Neste guia você vê por que trava e como praticar em etapas para entender cada vez mais.", [
    section("Por que você não entende a fala", ["Há três motivos principais. Primeiro, a velocidade: você tenta traduzir palavra por palavra e o áudio já avançou. Segundo, a fala conectada: as palavras se ligam e reduzem (want to vira ‘wanna’), então soa diferente da forma escrita. Terceiro, material acima do seu nível, com vocabulário demais de uma vez.", "Entender a causa muda a estratégia: o objetivo não é captar cada palavra, e sim acompanhar a ideia e ir afinando os detalhes."]),
    section("Pare de traduzir em tempo real", ["Traduzir cada palavra enquanto ouve é o maior sabotador do listening. Enquanto você traduz uma palavra, perde as cinco seguintes. Treine deixar o áudio correr e captar o sentido geral, mesmo sem entender tudo.", "Tolerar a incerteza — seguir em frente sem travar numa palavra — é uma das habilidades mais importantes de quem entende bem."]),
    section("Primeira escuta: pegue a ideia geral", ["Na primeira vez, não pause a cada palavra. Pergunte-se: quem fala? onde estão? sobre o quê? qual é o tom? Captar o contexto geral já é uma vitória e facilita entender os detalhes depois.", "Pense como numa conversa real: você raramente entende 100%, mas segue pela ideia central."]),
    section("Segunda escuta: cace detalhes e pistas", ["Agora ouça de novo procurando informações específicas: nomes, números, horários, lugares, palavras que se repetem. O contexto e as palavras vizinhas ajudam a inferir o que você não pegou de primeira.", "Ter uma pergunta em mente (‘a que horas eles vão se encontrar?’) direciona a atenção e melhora o que você capta."]),
    section("Use a transcrição — mas só depois de tentar", ["A transcrição ou a legenda é ótima, desde que usada na hora certa: depois de uma ou duas escutas sem ela. Aí você compara o que ouviu com o que está escrito, marca o trecho que não entendeu e descobre por que (foi uma palavra nova? sons que se ligaram?).", "Repita trechos curtos e difíceis algumas vezes. Ouvir o mesmo áudio várias vezes, cada vez entendendo mais, treina o ouvido melhor do que pular de áudio em áudio."]),
    section("Escolha o material certo e seja constante", ["Comece com áudios um pouco abaixo ou no seu nível, com fala mais clara — e vá subindo. Temas que você gosta mantêm a motivação. Pouco e todo dia funciona melhor que muito de vez em quando: a exposição constante é o que acostuma o ouvido ao ritmo do inglês.", "Com o tempo, a fala conectada (os sons que se ligam) deixa de soar como um borrão e começa a fazer sentido."]),
    section("Perguntas frequentes", ["Devo usar legenda? Sim, mas depois de tentar sem ela — legenda o tempo todo vira leitura, não listening. Legenda em inglês ou português? Em inglês, para ligar som e escrita. Por que entendo a música mas não a conversa? A conversa é mais rápida e imprevisível; é normal. Quanto tempo por dia? 10 a 20 minutos consistentes já fazem diferença."]),
    section("Continue praticando", ["Listening melhora com exposição diária e com o entendimento de como os sons se ligam. Combine este método com o estudo da fala conectada e das contrações, que são o que mais confunde no começo."], undefined, undefined, [{label:"Connected speech: por que os sons se ligam",url:"/blog/connected-speech-ligacao-sons"},{label:"Contrações comuns no inglês falado",url:"/blog/contracoes-ingles-falado"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("como-melhorar-leitura-ingles", "Reading", "Como melhorar a leitura em inglês usando o contexto", "Aprenda a ler melhor em inglês sem traduzir tudo: use pistas do contexto, leia em camadas, infira palavras e decida o que realmente vale pesquisar no dicionário.", "▤", ["melhorar leitura inglês", "reading inglês", "ler em inglês iniciante", "como ler em inglês", "inferir palavras pelo contexto", "ler inglês sem traduzir"], "Muita gente lê em inglês parando a cada palavra desconhecida para traduzir — e desiste no meio, exausta. O problema é o método: ler não é decodificar palavra por palavra, é construir sentido a partir do contexto, como você já faz em português. Nem toda palavra desconhecida impede a compreensão. Neste guia você aprende a ler em camadas, a inferir vocabulário pelo contexto e a decidir quais palavras realmente valem uma busca no dicionário.", [
    section("Antes de começar, observe o texto", ["Boa leitura começa antes da primeira frase. O título, os subtítulos, as imagens, o formato e a fonte (notícia, receita, e-mail?) dão pistas sobre o assunto e o tipo de texto. Use-as para formar uma expectativa — seu cérebro lê melhor o que ele já ‘previu’.", "Essa preparação (pré-leitura) ativa o que você já sabe sobre o tema, o que ajuda a entender mesmo com vocabulário limitado."], ["Olhe título, subtítulos e imagens antes de ler.", "Pergunte-se: que tipo de texto é este? sobre o quê?", "Ative o que você já sabe sobre o assunto."]),
    section("Leia em duas camadas", ["Na primeira passagem, busque só a ideia central: do que o texto trata, qual é a intenção, qual é o tom. Não pare em cada palavra. Na segunda, volte com uma pergunta em mente (quem fez o quê? quando? por quê?) e procure os detalhes que respondem a ela.", "Ler duas vezes com objetivos diferentes rende mais que uma leitura lenta tentando entender tudo de uma vez."], ["1ª leitura: ideia geral, sem parar.", "2ª leitura: detalhes que respondem a uma pergunta.", "Releia só os trechos que importam para o seu objetivo."]),
    section("Infira palavras pelo contexto", ["Antes de correr ao dicionário, tente adivinhar o sentido pela vizinhança: a frase inteira, os exemplos, os sinônimos e contrastes próximos, e a classe da palavra (é um verbo? um adjetivo?). Muitas vezes o contexto entrega o significado aproximado, que já basta para seguir.", "Inferir é uma habilidade de leitor avançado — e treina com prática. Errar a inferência também ensina, quando você confere depois."], ["The shop closes at six, so we should leave soon. — ‘closes’ se deduz pelo horário e por ‘leave soon’.", "It was freezing, so she put on a thick coat. — ‘freezing’ se infere por ‘thick coat’."]),
    section("Decida quais palavras pesquisar", ["Pesquisar toda palavra nova é cansativo e desnecessário. Consulte o dicionário quando a palavra for central para entender o texto, aparecer repetidamente ou mudar o sentido da frase. Palavras secundárias, deixe passar — ou anote para depois.", "Quando pesquisar, prefira ver a palavra em uma frase de exemplo e anote-a com contexto, não só a tradução solta. Assim você aprende a usá-la, não só a reconhecê-la."]),
    section("Leia um pouco todo dia, no seu nível", ["Ler melhora lendo. Comece com textos um pouco abaixo ou no seu nível, sobre temas que você gosta, e suba aos poucos. A regularidade importa mais que a quantidade: páginas curtas todo dia batem capítulos ocasionais.", "Com o tempo, você reconhece palavras mais rápido, infere com mais precisão e depende cada vez menos da tradução."]),
    section("Perguntas frequentes", ["Preciso entender todas as palavras? Não — foque na ideia; ignore palavras secundárias. Posso usar tradutor? Para checar depois de tentar inferir, sim; traduzir tudo de cara atrapalha. Que textos ler no começo? Curtos, no seu nível e sobre temas do seu interesse. Ler em voz alta ajuda? Pode ajudar a pronúncia e o ritmo, mas para compreensão o foco é o sentido."]),
    section("Continue praticando", ["Leitura e vocabulário crescem juntos. Combine estas estratégias com um bom método de vocabulário e com o cuidado com falsos cognatos, e aplique tudo nas aulas e simulados."], undefined, undefined, [{label:"Como aprender e fixar vocabulário",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Falsos cognatos: palavras que enganam",url:"/blog/falsos-cognatos-ingles-portugues"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("perder-medo-de-falar-ingles", "Speaking", "Como perder o medo de falar inglês: um plano em passos pequenos", "Estratégias práticas para vencer o medo e a vergonha de falar inglês: por que o bloqueio acontece, como praticar em etapas e como lidar com erros e com a falta de palavras.", "…", ["medo de falar inglês", "como praticar speaking", "vergonha falar inglês", "como perder o medo de falar inglês", "travar ao falar inglês", "bloqueio falar inglês"], "Entender inglês e travar na hora de falar é uma das queixas mais comuns de quem estuda — e não tem a ver com falta de conhecimento, e sim com medo de errar, de julgar a própria pronúncia ou de ‘dar branco’. A boa notícia: falar é uma habilidade que se treina em passos pequenos, e o medo diminui com exposição gradual, não esperando o dia em que você ‘estará pronto’. Neste guia você vê por que o bloqueio acontece e um plano concreto para soltar a fala.", [
    section("Por que a gente trava", ["O bloqueio quase sempre vem de três fontes: medo de errar e ser julgado, perfeccionismo (querer falar certinho antes de tentar) e a pressão de traduzir tudo em tempo real. Nenhuma delas é sobre o seu inglês em si — são sobre a situação de fala.", "Reconhecer isso ajuda: o objetivo não é eliminar o nervosismo, e sim praticar apesar dele, em contextos de baixa pressão, até ele diminuir."]),
    section("Comece com fala preparada", ["Reduza a pressão preparando antes. Escolha um tema familiar — sua rotina, sua cidade, um hobby — e monte três a cinco frases. Depois repita variando os detalhes, para não depender de decorar um texto inteiro.", "Ter blocos prontos (sua apresentação, como pedir um café, como fazer uma pergunta) dá segurança nos primeiros segundos, que costumam ser os mais difíceis."], ["I like music. I usually listen to pop at home. My favourite singer is… — fala preparada sobre um gosto.", "Prepare antes: apresentação, pedir informação, pedir para repetir."]),
    section("Pratique em etapas crescentes", ["Vá do mais seguro ao mais desafiador. Fale sozinho em voz alta (narre o que está fazendo). Grave-se só se quiser — é opcional e não precisa mostrar a ninguém. Depois, tente uma troca curta com alguém de confiança ou um parceiro de intercâmbio. Aumente a dificuldade aos poucos.", "Cada etapa cumprida reduz o medo da próxima. O segredo é a gradualidade, não o salto."], undefined, ["1. Falar sozinho / narrar ações em voz alta", "2. Gravar-se (opcional, só para você)", "3. Diálogos curtos e previsíveis", "4. Conversas reais com alguém de confiança"]),
    section("O que fazer quando falta a palavra", ["Dar branco é normal, inclusive na língua materna. Em vez de parar, use estratégias de contorno: explique com outras palavras (circumlocution), use uma palavra mais geral, ou ganhe tempo com expressões naturais como Let me think… ou How can I say this…", "Falantes experientes não sabem todas as palavras — eles sabem se virar quando falta uma. Essa habilidade vale mais que vocabulário gigante."], ["Let me think… — Deixa eu pensar…", "How do you say… in English? — Como se diz… em inglês?", "It’s a thing you use to… — É uma coisa que se usa para… (quando falta a palavra exata)"]),
    section("Trate erros como informação", ["Fluência não é ausência de erros — é conseguir comunicar a ideia e manter a conversa. Pessoas entendem você mesmo com deslizes. Em vez de se cobrar perfeição, escolha um ponto para melhorar por vez (um som, um tempo verbal, as perguntas) e deixe o resto fluir.", "Comemore a comunicação bem-sucedida, não a frase perfeita. Isso muda a sua relação com o erro e solta a fala."]),
    section("Crie oportunidades de baixa pressão", ["Procure situações onde errar custa pouco: apps de troca de idiomas, grupos de conversação para iniciantes, pedir informação em inglês numa viagem, comentar em comunidades. Quanto mais exposição de baixo risco, menor o medo.", "Consistência pesa mais que intensidade: cinco minutos de fala por dia valem mais que uma hora tensa por mês."]),
    section("Perguntas frequentes", ["Preciso de um nativo para praticar? Não — outros estudantes e apps funcionam bem no começo. E se eu travar na frente das pessoas? Respire, use Let me think… e siga; ninguém espera perfeição. Meu sotaque é um problema? Não, se você é compreensível — inteligibilidade importa mais que sotaque. Quando perco o medo? Com prática gradual e repetida; o medo diminui, não some de uma vez."]),
    section("Continue praticando", ["Falar melhora falando — de preferência em passos pequenos e frequentes. Comece com uma apresentação pronta, treine pedir para repetir sem vergonha e use as aulas de conversação do curso para ganhar repertório."], undefined, undefined, [{label:"Como se apresentar em inglês",url:"/blog/frases-para-se-apresentar-em-ingles"},{label:"Como pedir para repetir ou falar mais devagar",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("frases-para-se-apresentar-em-ingles", "Conversação", "Como se apresentar em inglês: frases prontas para começar uma conversa", "Aprenda a se apresentar em inglês com frases prontas para nome, origem, trabalho e interesses, saudações formais e informais, perguntas de volta e um exemplo completo.", "Hi!", ["se apresentar em inglês", "frases apresentação inglês", "introdução inglês", "como se apresentar em inglês", "frases para falar sobre si em inglês", "my name is nice to meet you"], "Saber se apresentar é a primeira coisa útil que você usa em qualquer conversa em inglês — numa viagem, numa entrevista, numa aula ou conhecendo alguém. A boa notícia é que uma apresentação é feita de blocos simples e repetíveis: cumprimento, nome, origem, ocupação, um interesse e uma pergunta de volta. Neste guia você tem frases prontas para cada bloco, as diferenças entre situações formais e informais, e um modelo completo para adaptar.", [
    section("A estrutura de uma apresentação", ["Uma boa apresentação não precisa ser longa. Ela costuma seguir uma ordem natural: cumprimento → nome → de onde você é → o que faz → um interesse → uma pergunta de volta. Você escolhe só o que faz sentido para a situação.", "A pergunta de volta (And you? / What about you?) é o que transforma a apresentação em conversa, em vez de um monólogo."], undefined, ["1. Cumprimento (Hi / Hello / Nice to meet you)", "2. Nome (I’m… / My name is…)", "3. Origem (I’m from…)", "4. Ocupação (I’m a… / I work in…)", "5. Interesse (I enjoy… / I like…)", "6. Pergunta de volta (And you?)"]),
    section("Cumprimentos: formal e informal", ["O cumprimento define o tom. Em situações informais, Hi e Hey funcionam bem. Em contextos formais ou profissionais, prefira Hello e expressões como Good morning/afternoon. Ao ser apresentado a alguém, Nice to meet you é quase universal.", "Depois de alguém dizer Nice to meet you, responde-se Nice to meet you too."], ["Hi! / Hey! — informal", "Hello. Good morning. — formal", "Nice to meet you. — Prazer em conhecê-lo.", "Pleased to meet you. — Muito prazer. (mais formal)"]),
    section("Nome, origem e onde você mora", ["Para o nome, I’m… é o mais natural na fala; My name is… soa um pouco mais formal. Para origem, use I’m from + país ou cidade. Se quiser falar onde mora agora, use I live in…", "Uma pergunta de volta mantém a troca viva: Where are you from?"], ["Hi, I’m Lucas. — Oi, eu sou Lucas.", "My name is Ana Souza. — Meu nome é Ana Souza.", "I’m from Brazil, but I live in Portugal now. — Sou do Brasil, mas moro em Portugal agora.", "Where are you from? — De onde você é?"]),
    section("Trabalho, estudo e interesses", ["Para ocupação, use I’m a/an + profissão (I’m a teacher) ou I work in + área (I work in marketing). Para estudos, I’m a student / I study… Para interesses, I like / I enjoy / I’m into + atividade.", "Com profissões, não esqueça o artigo a/an: I’m a nurse, não I’m nurse."], ["I’m a teacher. — Sou professor.", "I work in healthcare. — Trabalho na área da saúde.", "I’m studying English. — Estou estudando inglês.", "I enjoy cooking and reading. — Gosto de cozinhar e ler."]),
    section("Um exemplo completo para adaptar", ["Junte os blocos em uma apresentação curta e natural. Troque os dados pelos seus e ajuste o tom à situação — mais leve entre amigos, mais sóbrio numa entrevista.", "Repare que termina com uma pergunta de volta, que passa a palavra para a outra pessoa."], ["Hi, I’m Maya. I’m from Brazil, and I’m a designer. I really enjoy drawing in my free time. What about you? — Oi, sou a Maya. Sou do Brasil e trabalho como designer. Gosto muito de desenhar no tempo livre. E você?"]),
    section("Erros comuns ao se apresentar", ["Os deslizes mais frequentes: esquecer o artigo na profissão (I’m engineer ✗ → I’m an engineer ✓); dizer I have 25 years em vez de I’m 25 years old (idade usa to be); e traduzir ‘prazer’ ao pé da letra (My pleasure é mais ‘de nada’; use Nice to meet you). Pratique a sua apresentação em voz alta até sair sem pensar.", "Ter a sua apresentação ‘na ponta da língua’ reduz muito o nervosismo em situações reais."], ["I’m engineer. ✗ → I’m an engineer. ✓", "I have 30 years. ✗ → I’m 30 years old. ✓"]),
    section("Perguntas frequentes", ["É ‘my name is’ ou ‘I’m’? Os dois estão certos; I’m é mais comum na fala. Como respondo a ‘Nice to meet you’? Nice to meet you too. Falo idade como? I’m … years old (com to be). Preciso dar muitos detalhes? Não — escolha o que cabe na situação; em contextos profissionais, foque no que é relevante."]),
    section("Continue praticando", ["Apresentar-se conecta várias bases: o verbo to be, as perguntas e o small talk que mantém a conversa. Pratique nas aulas iniciais do curso e treine começar conversas com naturalidade."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Small talk: como iniciar uma conversa",url:"/blog/small-talk-em-ingles"},{label:"Como fazer perguntas em inglês",url:"/blog/como-fazer-perguntas-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("email-simples-em-ingles", "Writing", "Como escrever um e-mail em inglês: estrutura e frases prontas", "Aprenda a escrever e-mails em inglês do começo ao fim: saudação, abertura, corpo, pedido e encerramento, com frases prontas para situações formais e informais.", "@", ["escrever email inglês", "e-mail simples inglês", "saudações e encerramento inglês", "como escrever email em inglês", "frases para email em inglês", "email formal inglês"], "Escrever um e-mail em inglês fica fácil quando você conhece a estrutura: todo e-mail segue o mesmo esqueleto — saudação, abertura, motivo, detalhes e encerramento. Com algumas frases prontas para cada parte, você monta mensagens claras e educadas sem travar. O que mais varia é o grau de formalidade, que muda a saudação e o fecho. Neste guia você tem o modelo completo e um banco de frases para e-mails formais e informais.", [
    section("A estrutura de um e-mail", ["Um e-mail bem organizado tem cinco partes: saudação (Hi… / Dear…), uma frase de abertura, o motivo do contato, os detalhes ou o pedido, e o encerramento com despedida e nome. Essa ordem vale para quase qualquer mensagem.", "Antes de escrever, defina o tom: formal (trabalho, desconhecidos, instituições) ou informal (amigos, colegas próximos). Isso guia as escolhas de palavras."], undefined, ["1. Saudação", "2. Abertura / motivo", "3. Detalhes ou pedido", "4. Encerramento (ação ou agradecimento)", "5. Despedida + nome"]),
    section("A saudação certa para cada tom", ["Para e-mails informais, Hi + nome funciona bem (Hi Sam,). Para formais, use Dear + nome ou título (Dear Ms Lee, Dear Mr Silva,). Se não souber o nome, Dear Sir or Madam ou Hello é seguro.", "Em inglês, costuma-se usar vírgula depois da saudação e começar a frase seguinte com letra maiúscula."], ["Hi Ana, — informal", "Dear Mr Costa, — formal, com nome", "Dear Sir or Madam, — formal, sem nome", "Hello team, — neutro, para grupos"]),
    section("Abertura e motivo do e-mail", ["Comece com uma frase curta e, em seguida, diga por que está escrevendo. Em e-mails formais, I’m writing to… é um clássico. Em respostas, agradeça o contato anterior: Thank you for your email.", "Ir direto ao ponto é valorizado em inglês profissional — evite rodeios longos antes do motivo."], ["I’m writing to ask about the course schedule. — Escrevo para perguntar sobre o horário do curso.", "Thank you for your email. — Obrigado pelo seu e-mail.", "I hope you’re doing well. — Espero que esteja bem. (abertura cordial)"]),
    section("Fazer pedidos com educação", ["Pedidos educados usam could, would e please. Could you…? e Would it be possible to…? soam mais gentis que o imperativo direto. Para anexos, use I’ve attached… / Please find attached…", "Quanto mais formal, mais indireto costuma ser o pedido."], ["Could you please send me the details? — Poderia me enviar os detalhes, por favor?", "I would appreciate it if you could reply by Friday. — Eu agradeceria se pudesse responder até sexta.", "Please find attached the document. — Segue em anexo o documento."]),
    section("Encerramento e despedida", ["Antes de se despedir, feche com uma frase de ação ou cortesia: Looking forward to hearing from you, Thank you for your help. Depois, escolha a despedida conforme o tom: Best regards / Kind regards (formal), Best / Thanks (neutro-informal), Cheers (bem informal, britânico).", "Termine com o seu nome. Em contextos formais, nome completo; entre conhecidos, só o primeiro."], ["Looking forward to hearing from you. — Aguardo seu retorno.", "Best regards, / Kind regards, — Atenciosamente, (formal)", "Thanks, / Best, — informal-neutro", "Thank you for your help. — Obrigado pela ajuda."]),
    section("Erros comuns e revisão", ["Erros frequentes: ser informal demais com desconhecidos (Hey num e-mail formal), traduzir ‘atenciosamente’ de formas estranhas (use Best regards), e esquecer de revisar nome, data e anexo. Releia sempre antes de enviar — um e-mail não dá para ‘tirar de volta’.", "Cuidado também com o tom: em inglês, frases muito diretas podem soar ríspidas; could e please suavizam."], ["Hey, (formal) ✗ → Dear Mr Lee, ✓", "Esquecer o anexo depois de escrever ‘attached’ — revise antes de enviar."]),
    section("Perguntas frequentes", ["‘Dear’ é muito formal? É o padrão para e-mails formais e não soa exagerado. Uso vírgula ou dois-pontos depois da saudação? Vírgula é o comum no inglês britânico; nos EUA, dois-pontos em cartas bem formais. Como assino? Despedida + nome; em formais, nome completo e cargo. Posso usar contrações (I’m, don’t)? Em e-mails informais e semiformais, sim; em muito formais, prefira a forma completa."]),
    section("Continue praticando", ["E-mails são um ótimo exercício de escrita estruturada. Combine este guia com a organização de parágrafos e o uso de conectores para textos mais longos, e pratique nas aulas do curso."], undefined, undefined, [{label:"Como organizar um parágrafo em inglês",url:"/blog/como-escrever-paragrafo-ingles"},{label:"Conectores para ligar ideias",url:"/blog/conectores-para-escrever-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),

  article("comparatives-em-ingles", "Gramática essencial", "Comparativos em inglês: como comparar pessoas e coisas", "Aprenda a formar o comparativo dos adjetivos em inglês: a regra do -er, o more para adjetivos longos, as formas irregulares, as mudanças de ortografia e os erros comuns.", "↔", ["comparativos inglês", "comparar em inglês", "comparative adjectives", "como usar comparativo inglês", "er more than inglês", "adjetivos comparativos inglês"], "Comparar faz parte de qualquer conversa: dizer que algo é maior, melhor ou mais caro que outra coisa. Em inglês, o comparativo dos adjetivos segue duas estratégias principais, decididas pelo tamanho do adjetivo: os curtos recebem -er e os longos usam more. Depois do comparativo, than introduz o segundo elemento. Neste guia você vê as regras, as mudanças de ortografia, as formas irregulares e os deslizes mais comuns.", [
    section("A regra geral: curto x longo", ["A escolha depende do número de sílabas do adjetivo. Adjetivos curtos (uma sílaba) recebem -er: tall → taller. Adjetivos longos (três sílabas ou mais) usam more: expensive → more expensive. Os de duas sílabas variam — muitos com -y usam -er (happy → happier), outros usam more.", "Em todos os casos, than liga as duas coisas comparadas, equivalendo ao ‘(do) que’ do português."], undefined, ["1 sílaba → adjetivo + -er + than", "2 sílabas terminadas em -y → troca y por -ier", "3+ sílabas → more + adjetivo + than"]),
    section("Adjetivos curtos: -er + than", ["Acrescente -er ao adjetivo curto. Há ajustes de ortografia: adjetivos terminados em -e recebem só -r (nice → nicer); os terminados em consoante-vogal-consoante dobram a última letra (big → bigger); os terminados em -y trocam por -ier (easy → easier).", "Depois vem than para introduzir a comparação."], ["My room is smaller than yours. — Meu quarto é menor que o seu.", "This bag is bigger than that one. — Esta bolsa é maior que aquela.", "Today is hotter than yesterday. — Hoje está mais quente que ontem.", "This exercise is easier than the last one. — Este exercício é mais fácil que o anterior."]),
    section("Adjetivos longos: more + than", ["Com adjetivos de duas ou mais sílabas (sobretudo três ou mais), use more antes do adjetivo, sem alterar sua forma: more difficult, more interesting, more expensive.", "O erro clássico aqui é juntar as duas estratégias: nunca use -er e more ao mesmo tempo (more easier ✗)."], ["This exercise is more difficult than the last one. — Este exercício é mais difícil que o último.", "She is more careful than me. — Ela é mais cuidadosa do que eu.", "This phone is more expensive than that one. — Este celular é mais caro que aquele."]),
    section("Formas irregulares", ["Alguns adjetivos muito comuns não seguem nenhuma das regras e têm formas próprias. Vale memorizá-las, porque aparecem o tempo todo: good → better, bad → worse, far → farther/further.", "Essas formas não levam -er nem more — já são o comparativo."], ["good → better: This option is better than the other one. — Esta opção é melhor que a outra.", "bad → worse: The weather is worse today. — O tempo está pior hoje.", "far → farther: The station is farther than I thought. — A estação é mais longe do que eu pensava."]),
    section("Outras formas de comparar", ["Além do comparativo de superioridade, há outras estruturas úteis. Para igualdade, use as … as (tão … quanto): She is as tall as her brother. Para inferioridade, use less … than (menos … que): This is less important than that. E para reforçar uma diferença, use much ou a lot antes do comparativo: much better, a lot cheaper.", "Essas estruturas deixam a comparação mais rica e natural."], ["He’s as fast as you. — Ele é tão rápido quanto você.", "This book is less interesting than the first one. — Este livro é menos interessante que o primeiro.", "It’s much colder today. — Está muito mais frio hoje."]),
    section("Erros comuns com comparativos", ["Os deslizes mais frequentes: usar more com adjetivo curto (more tall ✗ → taller ✓), combinar -er e more (more easier ✗ → easier ✓), e usar that no lugar de than (taller that me ✗ → taller than me ✓). Cuidado também com as formas irregulares: gooder e badder não existem.", "Para fixar, compare coisas da sua vida: a sua cidade e outra, o hoje e o ontem, dois aplicativos que você usa."], ["more tall ✗ → taller ✓", "more easier ✗ → easier ✓", "gooder ✗ → better ✓"]),
    section("Perguntas frequentes", ["Quando um adjetivo de 2 sílabas usa -er ou more? Os terminados em -y, -er, -ow geralmente usam -er (happier, narrower); muitos outros aceitam more. Na dúvida, more quase sempre soa aceitável. É ‘than me’ ou ‘than I’? Na conversa, than me é o natural; than I am é mais formal. O próximo passo depois do comparativo? O superlativo (the biggest, the most important)."]),
    section("Continue praticando", ["Depois de dominar o comparativo, o passo natural é o superlativo, que destaca o ‘mais’ de todos em um grupo. As aulas do curso trabalham adjetivos e comparações em contexto."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Em seguida: superlativos em inglês",url:"/blog/superlatives-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("superlatives-em-ingles", "Gramática essencial", "Superlativos em inglês: como dizer o maior, o melhor e o mais importante", "Aprenda a formar o superlativo dos adjetivos em inglês: a regra do -est, o the most para adjetivos longos, as formas irregulares e os erros comuns.", "★", ["superlativos inglês", "the most", "adjetivos superlativos", "como usar superlativo inglês", "est the most inglês", "superlative adjectives"], "O superlativo serve para destacar algo como o ‘mais’ (ou o ‘menos’) dentro de um grupo: o maior, o melhor, o mais caro. Em inglês, ele segue a mesma divisão do comparativo — adjetivos curtos recebem -est e os longos usam the most — mas com uma diferença marcante: o superlativo quase sempre vem acompanhado de the. Neste guia você vê as regras, a ortografia, as formas irregulares e como indicar o grupo de comparação.", [
    section("A regra geral: curto x longo", ["A escolha depende do tamanho do adjetivo. Adjetivos curtos (uma sílaba) recebem the + -est: tall → the tallest. Adjetivos longos (três sílabas ou mais) usam the most: expensive → the most expensive. Os de duas sílabas variam — com -y usam -est (happy → the happiest).", "O the é quase obrigatório porque o superlativo aponta para algo único dentro de um grupo."], undefined, ["1 sílaba → the + adjetivo + -est", "2 sílabas em -y → the + adjetivo-iest", "3+ sílabas → the most + adjetivo"]),
    section("Adjetivos curtos: the + -est", ["Acrescente -est ao adjetivo curto, com os mesmos ajustes de ortografia do comparativo: -e recebe só -st (nice → the nicest); consoante-vogal-consoante dobra a letra (big → the biggest); -y vira -iest (happy → the happiest).", "Use sempre the antes do adjetivo superlativo."], ["It’s the smallest room in the house. — É o menor quarto da casa.", "She is the happiest person here. — Ela é a pessoa mais feliz aqui.", "Today is the hottest day of the year. — Hoje é o dia mais quente do ano."]),
    section("Adjetivos longos: the most", ["Com adjetivos de duas ou mais sílabas (sobretudo três ou mais), use the most antes do adjetivo, sem alterar sua forma: the most interesting, the most difficult. Para o grau mínimo, use the least: the least expensive (o menos caro).", "Nunca junte as duas formas (the most easiest ✗)."], ["That was the most interesting part of the talk. — Essa foi a parte mais interessante da palestra.", "This is the most expensive option. — Esta é a opção mais cara.", "It’s the least important point. — É o ponto menos importante."]),
    section("Formas irregulares", ["Os mesmos adjetivos irregulares do comparativo têm superlativos próprios: good → the best, bad → the worst, far → the farthest/furthest. Eles não levam -est nem most.", "São muito frequentes, então vale memorizá-los."], ["good → the best: This is the best café in town. — Este é o melhor café da cidade.", "bad → the worst: That was the worst day. — Aquele foi o pior dia.", "far → the farthest: It’s the farthest point. — É o ponto mais distante."]),
    section("Como indicar o grupo de comparação", ["Para dizer dentro de que grupo algo é o ‘mais’, use in com lugares e grupos (the tallest building in the city) e of com conjuntos ou períodos (the best day of my life). Também é comum usar uma oração com relative: the best film I’ve ever seen.", "Esse complemento deixa claro o universo da comparação."], ["the tallest building in the city — o prédio mais alto da cidade", "the best day of the year — o melhor dia do ano", "the most useful app I’ve ever used — o app mais útil que já usei"]),
    section("Erros comuns com superlativos", ["Os deslizes mais frequentes: esquecer o the (She is best ✗ → She is the best ✓); juntar most e -est (the most tallest ✗ → the tallest ✓); e usar as formas irregulares erradas (the goodest ✗, the baddest ✗ no sentido comum → the best, the worst). Cuidado também: em comparação de apenas dois, o inglês prefere o comparativo (the better of the two), não o superlativo.", "Para fixar, descreva recordes: a maior cidade do seu país, o melhor filme que você viu, o dia mais frio do ano."], ["She is best student. ✗ → She is the best student. ✓", "the most tallest ✗ → the tallest ✓", "the goodest ✗ → the best ✓"]),
    section("Perguntas frequentes", ["Preciso sempre usar the? Em quase todos os casos, sim; com possessivos, o the some (my best friend). Qual a diferença de comparativo para superlativo? Comparativo compara dois (taller than); superlativo destaca um no grupo (the tallest). É ‘the most good’? Não — é the best, forma irregular."]),
    section("Continue praticando", ["Comparativos e superlativos andam juntos — se ainda não viu o comparativo, comece por ele. Depois pratique os dois nas aulas do curso, descrevendo e comparando coisas do seu dia a dia."], undefined, undefined, [{label:"Revise antes: comparativos em inglês",url:"/blog/comparatives-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("can-could-habilidade-pedidos", "Gramática essencial", "Can e could: habilidades, possibilidade e pedidos educados em inglês", "Aprenda a usar os modais can e could para falar do que você sabe fazer, de possibilidades e para fazer pedidos educados, com negativas, formas de futuro e erros comuns.", "Can", ["can could diferença", "pedidos educados inglês", "habilidades inglês", "can could modal", "como usar can e could", "could you can you diferença"], "Can e could estão entre os primeiros verbos modais que você aprende, e com razão: servem para falar do que você sabe fazer, do que é possível e para pedir coisas com educação. Can é o presente; could é tanto o passado de can quanto uma forma mais suave de pedir. Como todo modal, eles têm regras próprias — não levam -s, não usam to depois e formam perguntas e negativas sem auxiliar. Neste guia você vê cada uso com exemplos.", [
    section("Como os modais funcionam", ["Can e could são verbos modais, então seguem três regras fixas: o verbo depois vem na forma base, sem to (I can swim, não I can to swim); não mudam com he/she/it (she can, nunca she cans); e formam perguntas e negativas sem do (Can you…? / I can’t…).", "Entender essas regras resolve a maior parte dos erros com modais em geral."], undefined, ["sem to depois: can go (não ‘can to go’)", "sem -s na 3ª pessoa: she can", "pergunta/negativa sem do: Can you? / can’t"]),
    section("Can e could para habilidade", ["Can fala de habilidade no presente: o que você sabe ou consegue fazer. Could é o passado de can: habilidade que você tinha. Para habilidade no futuro, use will be able to (não ‘will can’).", "No sentido de ‘saber fazer’, can equivale ao nosso ‘sei’ e ‘consigo’."], ["I can swim. — Eu sei nadar.", "When I was five, I could read. — Aos cinco anos, eu já sabia ler.", "I’ll be able to drive next year. — Vou poder dirigir ano que vem."]),
    section("Can e could para possibilidade", ["Can também indica possibilidade geral (o que é possível acontecer), e could indica uma possibilidade mais incerta ou hipotética — equivale a ‘poderia’.", "Essa diferença de certeza é útil: can soa mais factual; could, mais aberto a dúvida."], ["It can get cold here at night. — Aqui pode esfriar à noite.", "This could be a problem. — Isto poderia ser um problema.", "She could be at home. — Ela pode estar em casa (não tenho certeza)."]),
    section("Pedidos, permissão e ofertas", ["Can e could são campeões em pedidos. Could you…? soa um pouco mais formal e educado que Can you…?, mas ambos funcionam bem com please. Para pedir permissão, use Can I…? ou, mais educado, Could I…? Para oferecer ajuda, Can I help you?", "O tom e o please contam tanto quanto o modal escolhido."], ["Can you help me, please? — Você pode me ajudar, por favor?", "Could you open the window? — Você poderia abrir a janela?", "Could I use your phone? — Eu poderia usar seu telefone?"]),
    section("Negativas: can't e couldn't", ["A negativa de can é cannot, contraída como can’t (uma palavra só). A de could é could not / couldn’t. Can’t pode indicar incapacidade (I can’t swim) ou impossibilidade/proibição (You can’t park here).", "Atenção à pronúncia: no inglês americano, can e can’t às vezes soam parecidos — o contexto ajuda a distinguir."], ["I can’t come today. — Não posso vir hoje.", "She couldn’t find her keys. — Ela não conseguiu achar as chaves.", "You can’t smoke here. — Você não pode fumar aqui."]),
    section("Erros comuns com can e could", ["Os deslizes mais frequentes: usar to depois (I can to help ✗ → I can help ✓); acrescentar -s (he cans ✗ → he can ✓); e inventar ‘will can’ para o futuro (→ will be able to). Também é comum confundir could com uma forma educada só de pedido, esquecendo que também é o passado de can.", "Para fixar, liste três coisas que você can fazer, três que could fazer quando criança e faça três pedidos com could you."], ["I can to drive. ✗ → I can drive. ✓", "He cans swim. ✗ → He can swim. ✓", "I will can help. ✗ → I will be able to help. ✓"]),
    section("Perguntas frequentes", ["Could é sempre passado? Não — é passado de can, mas também serve para pedidos educados e possibilidades no presente. Qual é mais educado, can you ou could you? Could you tende a soar mais educado, mas os dois são corretos. Como falo de habilidade no futuro? Use will be able to."]),
    section("Continue praticando", ["Can e could abrem a porta para os outros modais, como should, must e have to. Depois de dominá-los, veja como expressar conselho e obrigação, e pratique pedidos nas aulas de conversação do curso."], undefined, undefined, [{label:"Em seguida: should, must e have to",url:"/blog/should-must-have-to-obrigacao"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Pedir para repetir ou falar mais devagar",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("should-must-have-to-obrigacao", "Gramática essencial", "Should, must e have to: conselho, obrigação e necessidade em inglês", "Entenda a diferença entre should, must e have to para dar conselhos, falar de regras e obrigações, com atenção especial às negativas, que mudam totalmente de sentido.", "!", ["should must have to", "conselho obrigação inglês", "modal verbs", "diferença must have to", "shouldn't mustn't don't have to", "should must have to exemplos"], "Should, must e have to são os modais da obrigação e do conselho — e escolher entre eles muda a força do que você diz. Should é mais leve: recomenda. Must e have to são mais fortes: falam de regras e necessidades. O ponto que mais confunde, porém, são as negativas: mustn’t e don’t have to significam coisas completamente diferentes. Neste guia você vê cada uso e o contraste que todo estudante precisa dominar.", [
    section("A escala de força", ["Pense em uma escala. Should é um conselho — você acha que é uma boa ideia, mas não é obrigatório. Must e have to são obrigações fortes — algo necessário ou uma regra. A diferença entre must e have to é sutil: must costuma vir de quem fala (obrigação pessoal ou escrita), e have to, de uma circunstância externa.", "Na conversa do dia a dia, have to é muito mais comum que must para obrigações reais."], undefined, ["should → conselho, recomendação (leve)", "must → obrigação forte, regra (quem fala)", "have to → necessidade, obrigação externa (comum na fala)"]),
    section("Should para conselhos", ["Should + verbo base dá uma recomendação ou opinião: ‘deveria’. É educado e não impõe. Para pedir conselho, use Should I…? A negativa shouldn’t aconselha a não fazer algo.", "Ought to tem sentido parecido com should, mas é menos comum na conversa."], ["You should get some rest. — Você deveria descansar.", "Should I call her? — Será que eu ligo para ela?", "You shouldn’t worry so much. — Você não deveria se preocupar tanto."]),
    section("Must e have to para obrigação", ["Must expressa obrigação forte ou regra, muitas vezes escrita (avisos, instruções): You must wear a seatbelt. Have to expressa necessidade e obrigação vinda das circunstâncias: I have to work on Saturday. Must é modal (não muda, sem to); have to se conjuga (has to, had to) e usa do nas perguntas.", "Para o passado de must no sentido de obrigação, use had to (não ‘musted’)."], ["You must wear a seat belt. — Você deve usar cinto de segurança.", "I have to leave at six. — Tenho que sair às seis.", "She has to study tonight. — Ela tem que estudar hoje à noite.", "We had to wait an hour. — Tivemos que esperar uma hora."]),
    section("O ponto crítico: as negativas", ["Aqui está o erro mais perigoso. Mustn’t significa proibição — você NÃO pode fazer. Don’t have to significa ausência de necessidade — você não precisa, mas pode se quiser. Elas são quase opostas.", "Compare: You mustn’t tell anyone (proibido contar) x You don’t have to tell anyone (não precisa contar, mas pode). Confundir as duas muda completamente a mensagem."], ["You mustn’t park here. — Você não pode (é proibido) estacionar aqui.", "You don’t have to come early. — Você não precisa chegar cedo.", "Shouldn’t = não é uma boa ideia; mustn’t = é proibido."]),
    section("Must para dedução (sentido extra)", ["Must tem um segundo uso importante: dedução lógica — quando você conclui algo com quase certeza. He must be tired (ele deve estar cansado, pela situação). Nesse caso, o oposto é can’t (He can’t be serious = não é possível que ele esteja falando sério), não mustn’t.", "Esse uso aparece bastante em conversa e em provas."], ["You must be joking! — Você só pode estar brincando!", "She must be at work now. — Ela deve estar no trabalho agora.", "That can’t be right. — Isso não pode estar certo."]),
    section("Erros comuns", ["Os deslizes mais frequentes: trocar mustn’t por don’t have to; usar to depois de must (must to go ✗ → must go ✓); esquecer que have to se conjuga (she have to ✗ → she has to ✓); e usar ‘musted’ no passado (→ had to). Para fixar, pense em regras do seu trabalho ou escola: o que você must/has to fazer, o que mustn’t fazer e o que don’t have to fazer.", "Treinar o contraste mustn’t x don’t have to em frases reais evita o erro mais caro."], ["I must to go. ✗ → I must go. ✓", "She have to work. ✗ → She has to work. ✓", "We musted wait. ✗ → We had to wait. ✓"]),
    section("Perguntas frequentes", ["Must ou have to? Na fala, have to é mais comum para obrigações reais; must aparece em regras escritas e em deduções. Qual o passado de must? Had to para obrigação. Mustn’t = don’t have to? Não — mustn’t é proibição; don’t have to é ‘não precisa’. Should é obrigação? Não, é conselho."]),
    section("Continue praticando", ["Esses modais completam o grupo iniciado por can e could. Depois de dominá-los, você consegue dar conselhos, explicar regras e fazer deduções. Pratique nas aulas do curso e em situações práticas como reuniões e entrevistas."], undefined, undefined, [{label:"Revise antes: can e could",url:"/blog/can-could-habilidade-pedidos"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Frases para reuniões de trabalho",url:"/blog/ingles-para-reunioes-trabalho"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("present-perfect-vs-simple-past", "Gramática essencial", "Present perfect ou simple past: qual é a diferença e quando usar cada um?", "A dúvida mais comum do inglês intermediário. Entenda com clareza quando usar o present perfect e quando usar o simple past, com exemplos, marcadores de tempo e erros frequentes.", "↔", ["present perfect vs simple past", "diferença present perfect simple past", "quando usar present perfect", "have has past participle", "present perfect exemplos", "present perfect ou passado simples"], "Essa é provavelmente a dúvida de gramática que mais trava brasileiros no inglês intermediário, porque o português traduz os dois tempos de formas parecidas. A diferença central é de foco: o simple past situa a ação num momento passado definido e encerrado; o present perfect conecta o passado ao presente — uma experiência, um resultado atual ou algo que começou antes e segue relevante. Neste guia você vê a regra, os marcadores de tempo que denunciam cada um e os erros mais comuns.", [
    section("A diferença em uma frase", ["Pense assim: o simple past responde ‘quando?’ e aponta para um momento fechado no passado. O present perfect responde ‘e daí para agora?’ — ele não diz quando, porque o foco é o efeito ou a experiência até o presente.", "Compare: I lost my keys (simple past) só conta um fato passado; I’ve lost my keys (present perfect) sugere que ainda estou sem elas agora. A forma muda e o sentido também."], undefined, ["simple past → momento passado definido e encerrado (quando)", "present perfect → ligação com o presente (experiência, resultado, até agora)"]),
    section("Como formar cada tempo", ["O simple past usa o verbo no passado (regular com -ed ou a forma irregular): I worked, I went. O present perfect usa have ou has + particípio passado (a terceira coluna dos verbos): I have worked, she has gone.", "O particípio de verbos regulares é igual ao passado (worked–worked). Nos irregulares, às vezes muda: go–went–gone, see–saw–seen, do–did–done. Vale aprender as três formas juntas."], ["I finished the report yesterday. — Terminei o relatório ontem. (simple past)", "I have finished the report. — Já terminei o relatório. (present perfect)", "She has gone home. — Ela foi para casa (e não está aqui)."]),
    section("Simple past: tempo passado definido", ["Use o simple past sempre que houver (ou estiver subentendido) um momento passado específico: yesterday, last week, in 2020, two days ago, when I was a child, at 8 o’clock. Perguntas com When…? quase sempre pedem simple past.", "Se a conversa já fixou o momento no passado, continue no simple past para os detalhes."], ["I visited London in 2022. — Visitei Londres em 2022.", "We met last Friday. — Nós nos encontramos na sexta passada.", "When did you arrive? — Quando você chegou?"]),
    section("Present perfect: ligação com o presente", ["Use o present perfect para experiências de vida (sem dizer quando), ações recentes com efeito atual, e situações que começaram no passado e continuam. Marcadores típicos: ever, never, just, already, yet, so far, recently, for e since.", "Com for e since, o present perfect indica duração até agora: for marca o período (for three years) e since marca o ponto de início (since 2020)."], ["Have you ever tried sushi? — Você já experimentou sushi alguma vez?", "I’ve just finished. — Acabei de terminar.", "She has lived here for ten years. — Ela mora aqui há dez anos.", "We’ve known each other since 2015. — Nós nos conhecemos desde 2015."]),
    section("O erro mais comum: misturar os dois", ["Em inglês padrão, não se usa present perfect com um momento passado já encerrado. Dizer I’ve seen him yesterday está errado — como há yesterday, o certo é I saw him yesterday. Esse é o deslize número um de brasileiros.", "A regra prática: se você pode acrescentar ‘quando?’ e a resposta é um tempo fechado, use simple past. Se o foco é ‘até agora’ ou ‘na vida’, use present perfect."], ["I’ve seen him yesterday. ✗ → I saw him yesterday. ✓", "Did you ever go to Japan? → Have you ever been to Japan? (experiência de vida)", "I have finished it last night. ✗ → I finished it last night. ✓"]),
    section("Diferença entre inglês britânico e americano", ["Vale saber: o inglês americano costuma aceitar o simple past em casos onde o britânico prefere o present perfect, sobretudo com just, already e yet. Did you eat yet? soa natural nos EUA; Have you eaten yet? é mais britânico.", "Nos exames internacionais, o present perfect com esses marcadores costuma ser a resposta mais segura. Por isso vale praticá-lo bem."]),
    section("Perguntas frequentes", ["Been ou gone? I’ve been to Paris = fui e voltei (experiência); he’s gone to Paris = foi e ainda está lá. Posso usar present perfect com ‘this week’? Sim, enquanto a semana não terminou (I’ve studied a lot this week). For ou since? For + período (for two hours); since + ponto de início (since Monday)."]),
    section("Continue praticando", ["O jeito de dominar esse contraste é ver os dois tempos lado a lado em muitas frases. As aulas intermediárias do curso trabalham o present perfect em contexto, e os simulados de Cambridge e TOEFL cobram exatamente essa diferença."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Revise antes: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Just, already, yet, ever e never",url:"/blog/present-perfect-just-already-yet-ever-never"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("present-perfect-just-already-yet-ever-never", "Gramática essencial", "Just, already, yet, ever e never: os advérbios do present perfect", "Entenda como just, already, yet, ever e never mudam o sentido do present perfect, onde cada um fica na frase e os erros mais comuns.", "✓", ["just already yet ever never", "present perfect advérbios", "have you ever", "diferença yet already", "onde colocar just already", "ever never present perfect"], "Just, already, yet, ever e never são os advérbios que mais acompanham o present perfect — e dominá-los é o que faz esse tempo soar natural. Cada um tem um papel: just marca algo recentíssimo, already algo que já aconteceu, yet algo ainda esperado, e ever/never falam de experiências na vida toda. Além do sentido, a posição na frase importa. Neste guia você vê o uso, o lugar certo de cada palavra e os deslizes mais comuns.", [
    section("Por que eles combinam com o present perfect", ["Esses advérbios ligam o passado ao presente — exatamente o papel do present perfect (have/has + particípio). Por isso aparecem juntos com tanta frequência. A forma base é have/has + particípio, e o advérbio entra em uma posição específica conforme o caso.", "Lembre que o present perfect não é usado com um tempo passado definido (yesterday), então esses advérbios substituem bem essa ideia de ‘quando’, sem fixar um momento."], undefined, ["just / already → entre have/has e o particípio", "yet → no fim da frase (perguntas e negativas)", "ever / never → entre have/has e o particípio"]),
    section("Just: algo que acabou de acontecer", ["Just indica que a ação aconteceu há muito pouco tempo — ‘acabei de’. Fica entre o auxiliar (have/has) e o particípio.", "É um dos usos mais comuns na conversa para dar notícias recentes."], ["I’ve just finished. — Acabei de terminar.", "She’s just left. — Ela acabou de sair.", "We’ve just arrived. — Acabamos de chegar."]),
    section("Already: já aconteceu (antes do esperado)", ["Already indica que algo já ocorreu, muitas vezes antes do que se esperava. Também fica entre have/has e o particípio, e aparece sobretudo em afirmações e perguntas de surpresa.", "O sentido é de ‘já’, com a ideia de que não é mais preciso fazer aquilo."], ["She has already eaten. — Ela já comeu.", "I’ve already seen this film. — Eu já vi este filme.", "Have you already finished? — Você já terminou? (surpresa)"]),
    section("Yet: ainda não / já (em perguntas e negativas)", ["Yet aparece em perguntas e negativas e vai no fim da frase. Na pergunta, significa ‘já’ (algo esperado aconteceu?); na negativa, significa ‘ainda não’.", "Não confunda com already: already é mais comum em afirmações; yet, em perguntas e negativas."], ["Have you called her yet? — Você já ligou para ela?", "I haven’t called yet. — Ainda não liguei.", "The bus hasn’t arrived yet. — O ônibus ainda não chegou."]),
    section("Ever e never: experiências de vida", ["Ever é usado em perguntas sobre experiências em algum momento da vida: Have you ever…? Never é a resposta negativa — ‘nunca’ — e já carrega a negação, então não se usa com not.", "Ambos ficam entre have/has e o particípio. Como never já nega, dizer haven’t never é erro (dupla negação)."], ["Have you ever been to London? — Você já esteve em Londres alguma vez?", "I’ve never flown alone. — Nunca viajei de avião sozinho.", "Has she ever tried sushi? — Ela já experimentou sushi?"]),
    section("Erros comuns com esses advérbios", ["Os deslizes mais frequentes: colocar yet no meio da frase (I yet haven’t finished ✗ → I haven’t finished yet ✓); usar dupla negação com never (I haven’t never ✗ → I’ve never ✓); e trocar already por yet em negativas. Outro é usar esses advérbios com simple past onde o inglês britânico pede present perfect.", "Para fixar, conte três coisas que você já fez na vida (ever/never), uma que acabou de fazer (just) e uma que ainda não fez (yet)."], ["I yet didn’t eat. ✗ → I haven’t eaten yet. ✓", "I haven’t never been there. ✗ → I’ve never been there. ✓"]),
    section("Perguntas frequentes", ["Qual a diferença entre already e yet? Already = já (afirmação); yet = já/ainda não (pergunta e negativa). Ever significa ‘sempre’? Não — aqui significa ‘alguma vez’. Posso usar esses advérbios no inglês americano com simple past? Com just, already e yet, o inglês dos EUA às vezes aceita o simple past (Did you eat yet?); nos exames, prefira o present perfect."]),
    section("Continue praticando", ["Esses advérbios são a chave para usar o present perfect com naturalidade. Antes deles, vale ter firme a diferença entre present perfect e simple past; depois, pratique nas aulas intermediárias do curso."], undefined, undefined, [{label:"Revise antes: present perfect ou simple past",url:"/blog/present-perfect-vs-simple-past"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("a-an-the-artigos-ingles", "Gramática essencial", "A, an e the: como escolher o artigo certo em inglês?", "Entenda a diferença entre a, an e the, quando usar cada um, quando não usar artigo nenhum e os erros mais comuns de quem fala português.", "a/an", ["a an the inglês", "artigos definidos indefinidos", "quando usar the", "diferença a an the", "a ou an inglês", "quando não usar artigo inglês"], "Os artigos a, an e the são curtinhos, mas estão entre as maiores fontes de erro para brasileiros — em parte porque o inglês usa (e omite) artigos de um jeito diferente do português. A ideia central é simples: a/an apresentam algo não específico pela primeira vez; the aponta para algo que quem fala e quem ouve já conseguem identificar; e muitas vezes não se usa artigo nenhum. Neste guia você vê a regra, a escolha entre a e an, e os casos sem artigo.", [
    section("A diferença entre a/an e the", ["Use a ou an (o artigo indefinido) quando o substantivo é mencionado pela primeira vez ou não é específico — equivale a ‘um/uma’. Use the (o artigo definido) quando o ouvinte sabe exatamente a que você se refere — equivale a ‘o/a’.", "O exemplo clássico mostra os dois juntos: I saw a dog. The dog was friendly. Na primeira frase, o cachorro é novo na conversa (a); na segunda, já sabemos qual é (the)."], ["I saw a dog. The dog was friendly. — Vi um cachorro. O cachorro era amigável.", "She bought a car. The car is red. — Ela comprou um carro. O carro é vermelho."], ["a/an → algo novo ou não específico", "the → algo já identificado pelo contexto"]),
    section("A ou an? Depende do som, não da letra", ["Use a antes de som de consoante e an antes de som de vogal. O que importa é o som falado, não a letra escrita. Por isso dizemos a university (o U soa como /iu/, consoante) mas an hour (o H é mudo, começa com som de vogal).", "Fique atento a palavras que enganam: an umbrella, a European country, an MBA (soa ‘em-bi-ei’), a one-way ticket (soa ‘uan’)."], ["a university / a European / a one-hour class", "an hour / an umbrella / an honest man", "an apple / a banana / an idea"]),
    section("Quando usar the", ["Use the quando o referente é único ou identificável: algo já mencionado, algo único no mundo (the sun, the moon), algo único no contexto (the kitchen, da sua casa), ou com superlativos (the best). Também com muitos nomes geográficos: the United States, the Amazon, the Atlantic.", "The pode acompanhar singular, plural ou incontável — o que define é a identificação, não o número: the book, the books, the water."], ["Please close the door. — Por favor, feche a porta. (sabemos qual)", "The sun is bright today. — O sol está forte hoje.", "This is the best café in town. — Este é o melhor café da cidade."]),
    section("Quando NÃO usar artigo", ["Em inglês, não se usa artigo para falar de coisas em geral no plural ou incontáveis. Dogs need exercise (cães em geral) não leva the. Também não se usa artigo com a maioria dos nomes de refeições, idiomas, esportes, países (Brazil, not the Brazil) e com in/at/to + home, work, school, bed em sentido geral.", "Esse é um ponto em que o português engana: dizemos ‘a música me relaxa’ ou ‘o Brasil’, mas em inglês geral é Music helps me relax e Brazil."], ["Dogs need exercise. — Cães precisam de exercício.", "Music helps me relax. — Música me ajuda a relaxar.", "I speak Portuguese. — Eu falo português. (não ‘the Portuguese’)", "She’s at home / at work. — Ela está em casa / no trabalho."]),
    section("Erros comuns de brasileiros", ["Os deslizes mais frequentes vêm de traduzir o uso português. Colocar the em generalizações (The dogs are loyal ✗ quando se fala de cães em geral), usar the com países comuns (the Brazil ✗), e esquecer a/an com profissões (She is doctor ✗ → She is a doctor ✓).", "Outra confusão é omitir o artigo onde o inglês precisa dele: I have car ✗ → I have a car ✓. Sempre que um substantivo contável estiver no singular, ele quase sempre precisa de a/an ou the."], ["the Brazil ✗ → Brazil ✓", "He is engineer. ✗ → He is an engineer. ✓", "I need umbrella. ✗ → I need an umbrella. ✓"]),
    section("Perguntas frequentes", ["É ‘a hour’ ou ‘an hour’? An hour, porque o H é mudo. É ‘the breakfast’? Não para refeições em geral: I had breakfast. Uso artigo com nomes de pessoas? Não: Maria, not the Maria. Como sei se uso the ou nada? Pergunte se o ouvinte já sabe exatamente qual: se sim, the; se é geral, muitas vezes nenhum."]),
    section("Continue praticando", ["Artigos entram no automático com leitura e prática — raramente com regras decoradas. As aulas iniciais do curso apresentam a, an e the em contexto, e vale combinar este tema com there is/there are e com substantivos contáveis e incontáveis."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Veja também: there is e there are",url:"/blog/there-is-there-are"},{label:"Some, any, much e many",url:"/blog/some-any-much-many"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "9 min"),
  article("first-conditional-em-ingles", "Gramática essencial", "First conditional: como falar de condições futuras possíveis em inglês", "Aprenda a formar o first conditional (if + presente, will + verbo) para falar de situações futuras prováveis, com a ordem das orações, alternativas a will e erros comuns.", "If", ["first conditional", "if clause inglês", "condicional provável inglês", "primeira condicional inglês", "if will inglês", "first conditional exemplos"], "O first conditional é a forma de falar sobre o futuro quando uma coisa depende de outra: ‘se isso acontecer, aquilo acontece’. Usamos para situações reais e prováveis — planos, promessas, avisos. A estrutura tem uma particularidade que confunde muita gente: embora fale do futuro, a parte com if fica no presente. Neste guia você vê a fórmula, a ordem das orações, as alternativas ao will e os erros mais comuns.", [
    section("A fórmula do first conditional", ["A estrutura é: if + simple present (a condição), will + verbo base (o resultado). A oração com if descreve a condição possível; a outra, o resultado provável.", "O detalhe-chave: mesmo sendo sobre o futuro, a parte do if usa o presente, não will. É assim que o inglês funciona nesse padrão."], ["If it rains, we’ll stay home. — Se chover, ficaremos em casa.", "If you study, you’ll pass. — Se você estudar, vai passar.", "She’ll be happy if you call. — Ela vai ficar feliz se você ligar."], ["Condição: if + presente", "Resultado: will + verbo base"]),
    section("A ordem das orações e a vírgula", ["As duas partes podem trocar de ordem sem mudar o sentido. Quando a oração com if vem primeiro, use vírgula entre ela e o resultado. Quando o resultado vem primeiro, normalmente não se usa vírgula.", "As duas versões são igualmente corretas; escolha pela ênfase."], ["If I have time, I’ll help you. — Se eu tiver tempo, te ajudo.", "I’ll help you if I have time. — Te ajudo se eu tiver tempo."]),
    section("Alternativas ao will", ["O resultado nem sempre usa will. Você pode usar can, may, might (possibilidade), should (conselho) ou um imperativo (instrução). Isso deixa o first conditional muito mais versátil.", "A parte do if continua no presente; só o resultado muda."], ["If you finish early, you can go home. — Se terminar cedo, pode ir para casa.", "If it’s cold, take a jacket. — Se estiver frio, leve um casaco.", "If you’re tired, you should rest. — Se estiver cansado, deveria descansar."]),
    section("O erro clássico: will depois de if", ["O deslize número um é usar will na oração com if: If she will have time ✗. O correto é manter o presente: If she has time, she’ll help ✓. O will fica apenas no resultado.", "Há exceções avançadas (pedidos educados com will após if), mas, na estrutura padrão do first conditional, guarde a regra: nada de will depois de if."], ["If it will rain, we’ll stay home. ✗", "If it rains, we’ll stay home. ✓", "If you will study, you’ll pass. ✗ → If you study, you’ll pass. ✓"]),
    section("First conditional x zero conditional", ["Cuidado para não confundir com o zero conditional, que usa if + presente, presente e serve para fatos sempre verdadeiros: If you heat water, it boils. O first conditional fala de um resultado futuro específico (will), não de uma verdade geral.", "Resumo: zero = sempre acontece; first = vai acontecer se a condição se cumprir."], ["Zero: If you mix blue and yellow, you get green. — fato geral", "First: If you call me, I’ll come. — resultado futuro"]),
    section("Perguntas frequentes", ["Posso começar pela oração com if? Sim, e aí use vírgula. O if sempre fica no presente? Na estrutura padrão, sim. Qual a diferença para o second conditional? O first fala de futuro provável (if + presente, will); o second, de situações hipotéticas ou improváveis (if + passado, would). Posso usar unless? Sim — unless significa ‘a menos que’ e equivale a if…not."]),
    section("Continue praticando", ["Depois do first conditional, o passo natural é o second conditional, para situações hipotéticas. Pratique os dois nas aulas do curso, fazendo planos e imaginando cenários sobre a sua vida."], undefined, undefined, [{label:"Em seguida: o second conditional",url:"/blog/second-conditional-situacoes-hipoteticas"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("word-stress-pronuncia-ingles", "Pronúncia", "Word stress: como acertar a sílaba tônica em inglês", "Entenda o que é o word stress, por que ele muda a compreensão, algumas tendências úteis, os pares que mudam de classe e os erros mais comuns de brasileiros.", "ˈ", ["word stress inglês", "sílaba tônica inglês", "pronúncia palavras inglês", "acento tônico inglês", "stress substantivo verbo", "como saber a sílaba forte em inglês"], "Word stress é o destaque que uma sílaba recebe dentro de uma palavra — ela soa mais forte, mais longa e mais clara que as outras. Em inglês, esse destaque é tão importante que colocar o acento na sílaba errada pode deixar a palavra irreconhecível, mesmo com todos os sons certos. Não há uma regra única que resolva todos os casos, mas há tendências úteis e um hábito que faz toda a diferença: aprender cada palavra já com o seu acento. Neste guia você vê como.", [
    section("Por que o word stress importa tanto", ["O inglês é uma língua de ritmo acentual: as sílabas tônicas se destacam e as átonas se reduzem (muitas viram um som neutro, o schwa /ə/). Por isso o ouvinte se apoia na sílaba forte para reconhecer a palavra. Se você acentua a sílaba errada, ele pode simplesmente não entender.", "Acertar o acento costuma ajudar mais na comunicação do que pronunciar cada som perfeitamente. É uma das prioridades de quem quer ser compreendido."]),
    section("Ouça antes de adivinhar", ["Como as regras têm muitas exceções, o caminho mais seguro é ouvir. Use um dicionário com áudio e observe a marca de acento (ˈ) na transcrição fonética: ela vem antes da sílaba tônica. Repita a palavra primeiro devagar, sentindo onde está o destaque, e depois no ritmo normal.", "Treinar o ouvido para localizar a sílaba forte é tão importante quanto produzi-la."], ["TAble — destaque na primeira sílaba (/ˈteɪ.bəl/)", "hoTEL — destaque na segunda sílaba (/həʊˈtel/)", "baNAna — destaque no meio (/bəˈnɑː.nə/)"]),
    section("Algumas tendências úteis", ["Embora não haja regra absoluta, alguns padrões ajudam. Muitas palavras de duas sílabas que são substantivos têm acento na primeira; muitos verbos de duas sílabas, na segunda. Palavras terminadas em -tion, -sion, -ic costumam ter o acento na sílaba imediatamente antes dessa terminação (informATION, fanTAStic).", "Use essas tendências como pistas, não como certezas — sempre confirme ouvindo quando puder."], ["informa-TION → acento antes de -tion", "-ic → fanTAStic, eLECtric", "muitos substantivos de 2 sílabas: PREsent, REcord"]),
    section("Pares que mudam de classe e de acento", ["Há um grupo de palavras que são substantivo e verbo com a mesma grafia, mas mudam a sílaba tônica — e às vezes a vogal. Como regra geral, o substantivo leva o acento na primeira sílaba e o verbo, na segunda.", "Repare como o sentido e a classe mudam com o deslocamento do acento. Nem toda palavra segue isso, mas o padrão é comum."], ["REcord (um disco/registro) x reCORD (gravar)", "PREsent (presente) x preSENT (apresentar)", "OBject (objeto) x obJECT (objetar)", "INcrease (aumento) x inCREASE (aumentar)"]),
    section("Erros comuns de brasileiros", ["Como o português tem suas próprias tônicas, é comum transferi-las para o inglês: dizer ‘HO-tel’ em vez de ho-TEL, ou acentuar a última sílaba de palavras longas por influência da escrita. Outro deslize é pronunciar todas as sílabas com a mesma força, sem reduzir as átonas.", "Para fixar, ao aprender uma palavra nova, marque a sílaba forte (com maiúsculas ou um sinal) e diga a palavra inteira algumas vezes. Aprender o som junto com a escrita evita decorar o acento errado."], ["ho-TEL, não HO-tel", "COMfortable tem o acento no início", "reduza as sílabas fracas, não as pronuncie todas iguais"]),
    section("Perguntas frequentes", ["Existe uma regra única para o acento? Não — há tendências, mas muitas exceções; confirme ouvindo. Por que erro o acento de palavras que leio? Porque a escrita não mostra a tônica; aprenda o som junto. O acento muda o significado? Em alguns pares (REcord/reCORD), sim. Como marco a tônica ao estudar? Com maiúsculas (hoTEL) ou o sinal ˈ antes da sílaba forte."]),
    section("Continue praticando", ["O word stress é parte de um conjunto maior de pronúncia. Combine-o com o estudo das vogais e da fala conectada, e pratique dizendo palavras inteiras em voz alta nas aulas do curso."], undefined, undefined, [{label:"Vogais curtas e longas: ship e sheep",url:"/blog/vogais-curtas-longas-ingles"},{label:"Connected speech: por que os sons se ligam",url:"/blog/connected-speech-ligacao-sons"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("connected-speech-ligacao-sons", "Pronúncia e listening", "Connected speech: por que os sons se ligam no inglês falado", "Entenda a fala conectada do inglês: ligações, reduções e formas fracas que fazem a conversa soar diferente da pronúncia isolada — e como treinar o listening com isso.", "≈", ["connected speech inglês", "ligação de sons inglês", "redução fala inglesa", "por que não entendo inglês falado", "formas fracas inglês", "wanna gonna gotcha"], "Você estuda as palavras, sabe o que elas significam, mas quando os falantes nativos conversam parece tudo grudado e rápido demais. Isso tem nome: connected speech (fala conectada). Na conversa real, as palavras não saem isoladas — elas se ligam, se reduzem e se transformam. Entender esse fenômeno é uma das chaves para destravar o listening e parar de achar que ‘falam rápido demais’. Neste guia você vê os principais tipos de ligação e como treinar.", [
    section("Por que a fala soa diferente do dicionário", ["Quando aprendemos uma palavra, ouvimos sua forma isolada, bem pronunciada. Mas na conversa as palavras se encadeiam, e os sons nas junções mudam para facilitar a fala. O resultado soa diferente da soma das palavras separadas — e é por isso que você reconhece a palavra escrita, mas não a pega no áudio.", "A boa notícia: a fala conectada segue padrões. Depois de reconhecê-los, o ‘borrão’ começa a fazer sentido."]),
    section("Ligação (linking): consoante + vogal", ["Quando uma palavra termina em consoante e a próxima começa com vogal, o som final ‘gruda’ no início da seguinte, como se fossem uma palavra só. É a ligação mais comum e a que mais confunde no começo.", "Treinar isso ajuda tanto a entender quanto a soar mais fluente."], ["pick it up → soa ‘pi-ki-tup’", "turn off → ‘tur-noff’", "an apple → ‘a-napple’"]),
    section("Reduções e formas fracas", ["Palavras gramaticais (artigos, preposições, auxiliares, pronomes) costumam perder destaque quando não carregam a informação principal. To, for, and, of, you viram versões ‘fracas’, bem curtas e com vogal neutra (schwa). Na escrita informal, isso às vezes aparece como wanna (want to), gonna (going to), gotta (got to).", "Essas formas fracas são a regra, não a exceção — é assim que a fala natural soa."], ["want to → wanna", "going to → gonna", "a cup of tea → ‘a cuppa tea’", "and → ‘n’ (fish ’n’ chips)"]),
    section("Sons que se transformam na junção", ["Às vezes, dois sons vizinhos se fundem num terceiro (assimilação) ou um som some (elisão). Por isso did you pode soar ‘didja’ e next day pode perder o /t/. Você não precisa produzir tudo isso de propósito — mas reconhecer ajuda muito a entender.", "O objetivo aqui é o ouvido: saber que esses fenômenos existem já muda a forma como você escuta."], ["did you → ‘didja’", "would you → ‘wudja’", "next day → ‘nexday’ (o /t/ some)"]),
    section("Como treinar sem perder as palavras", ["Pegue um trecho curto de áudio com transcrição. Ouça uma vez pela ideia geral, sem ler. Depois acompanhe a transcrição e marque onde as palavras se ligaram ou reduziram — compare o que você ouviu com o que está escrito. Repita o trecho algumas vezes.", "A técnica de ‘shadowing’ (ouvir e repetir junto, imitando o ritmo) ajuda a internalizar as ligações. Não force um sotaque específico; busque o ritmo e a inteligibilidade."]),
    section("Perguntas frequentes", ["Preciso falar ‘grudado’ para ser entendido? Não — mas reconhecer a fala conectada é essencial para o listening. Wanna e gonna são erro? São reduções naturais da fala; na escrita formal, use want to e going to. Por que entendo música mas não conversa? A conversa é mais imprevisível e cheia de reduções. Como melhoro? Exposição diária e prática com transcrição."]),
    section("Continue praticando", ["A fala conectada é o que mais confunde no listening. Combine este tema com o estudo das contrações e com um método de escuta ativa, e pratique com áudios curtos nas aulas do curso."], undefined, undefined, [{label:"Contrações comuns no inglês falado",url:"/blog/contracoes-ingles-falado"},{label:"Como entender inglês falado sem traduzir",url:"/blog/como-entender-ingles-falado-listening"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("vogais-curtas-longas-ingles", "Pronúncia", "Vogais curtas e longas em inglês: pares como ship e sheep", "Aprenda a diferenciar vogais parecidas do inglês, como em ship e sheep, com pares mínimos, a diferença entre duração e qualidade e os erros mais comuns de brasileiros.", "iː", ["vogais inglês ship sheep", "vogais curtas longas inglês", "pares mínimos inglês", "pronúncia ship sheep", "diferença vogais inglês", "som i longo curto inglês"], "O inglês tem mais sons de vogal do que o português, e vários deles são parecidos entre si — o que leva a confusões que podem mudar o significado da palavra. O par clássico é ship (navio) e sheep (ovelha). A diferença costuma ser descrita como ‘vogal curta x longa’, mas há mais nisso: muda também a qualidade do som (a posição da língua). Neste guia você aprende a ouvir e produzir esses contrastes com pares mínimos e treino em passos curtos.", [
    section("Não é só duração: é qualidade também", ["A ideia de ‘curta x longa’ ajuda, mas pode enganar. A vogal de sheep /iː/ não é apenas o /ɪ/ de ship esticado — ela é produzida com a língua um pouco mais alta e à frente, mais tensa. Por isso, só prolongar o som não resolve: é preciso ajustar a boca.", "Pense em dois sons diferentes, não no mesmo som com durações diferentes. Isso muda a forma de treinar."], ["ship /ɪ/ — língua mais relaxada e central", "sheep /iː/ — língua mais alta, à frente e tensa", "a qualidade importa tanto quanto a duração"]),
    section("Treine com pares mínimos", ["Pares mínimos são palavras que diferem por um único som — perfeitas para afinar o ouvido. Ouça um modelo confiável, identifique qual você ouviu e repita. Comece distinguindo na escuta antes de tentar produzir.", "Esses pares mostram por que o som importa: trocar um pelo outro muda a palavra."], ["ship /ɪ/ x sheep /iː/ — navio x ovelha", "sit x seat — sentar x assento", "bit x beat — pedaço x batida", "live x leave — morar x partir"]),
    section("Outros contrastes que confundem", ["O /ɪ/ x /iː/ é o mais famoso, mas há outros pares que pegam brasileiros: o /ʌ/ de cup e o /æ/ de cat, o /ɒ/ de hot, e o som neutro schwa /ə/ das sílabas fracas. Vale conhecê-los aos poucos, um par por vez.", "Não tente dominar todas as vogais de uma vez — escolha um contraste, treine até ficar confortável e passe ao próximo."], ["cup /ʌ/ x cap /æ/", "full /ʊ/ x fool /uː/", "man /æ/ x men /e/"]),
    section("Pratique em passos curtos", ["Siga uma rotina simples: 1) ouça o par e tente identificar qual é qual; 2) confira; 3) repita cada palavra isolada; 4) use cada uma em uma frase curta. Poucos minutos por dia rendem mais que sessões longas e espaçadas.", "Grave a si mesmo apenas se quiser, para comparar com o modelo — é opcional e só para você."], ["I need a seat. / I need to sit. — treine o contraste em frase.", "The sheep is on the ship. — frase com os dois sons."]),
    section("Erros comuns de brasileiros", ["O português tem menos vogais, então tendemos a ‘encaixar’ vários sons ingleses no mais próximo que conhecemos — geralmente pronunciando tudo como um /i/ só, o que apaga a diferença entre ship e sheep. Outro deslize é compensar só esticando a vogal, sem mudar a posição da língua.", "O objetivo não é copiar um sotaque específico, e sim ser inteligível: produzir sons distintos o bastante para a palavra ser reconhecida."], ["pronunciar ship e sheep igual ✗ — são sons diferentes", "só esticar a vogal ✗ — ajuste também a língua", "mire na inteligibilidade, não num sotaque único"]),
    section("Perguntas frequentes", ["A diferença é só a duração? Não — muda também a qualidade (posição da língua). Preciso aprender os símbolos fonéticos? Ajuda, mas não é obrigatório; o essencial é ouvir e distinguir. Meu sotaque é um problema? Não, se você é compreensível. Por onde começo? Pelo par ship/sheep e um contraste por vez."]),
    section("Continue praticando", ["As vogais são uma peça da pronúncia, ao lado do ritmo e da fala conectada. Combine este treino com o word stress e com a fala conectada, e pratique em frases reais nas aulas do curso."], undefined, undefined, [{label:"Word stress: a sílaba tônica",url:"/blog/word-stress-pronuncia-ingles"},{label:"Connected speech: por que os sons se ligam",url:"/blog/connected-speech-ligacao-sons"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("contracoes-ingles-falado", "Pronúncia e listening", "Contrações em inglês: as formas reduzidas que você precisa reconhecer", "Aprenda as contrações mais comuns do inglês (I'm, don't, they've, it's) para entender conversas e escrever de forma natural, com os pares que mais confundem e os erros a evitar.", "’", ["contrações inglês", "inglês falado contrações", "I'm don't they've", "o que é contração inglês", "its it's diferença", "contrações listening inglês"], "Contrações são formas reduzidas em que duas palavras se juntam e uma letra é substituída por um apóstrofo: I am vira I’m, do not vira don’t. Elas são a regra na conversa e na escrita informal do inglês — tão comuns que a fala soa estranha e robótica sem elas. Reconhecê-las é essencial para o listening, e usá-las deixa o seu inglês mais natural. Neste guia você vê as contrações mais importantes, os pares que confundem e quando evitá-las.", [
    section("O que é uma contração e por que usar", ["Uma contração combina duas palavras e marca com apóstrofo a letra omitida: it is → it’s, they have → they’ve. Na fala, quase sempre usamos a forma contraída; a completa soa enfática ou formal demais. Por isso, reconhecer contrações é metade da batalha do listening.", "Não é gíria: contrações são padrão no inglês falado e na escrita do dia a dia, inclusive profissional informal."]),
    section("Contrações com to be e com have", ["As mais frequentes juntam o sujeito ao verbo to be (am/is/are) ou ao auxiliar have/has. Elas aparecem o tempo todo em conversas e descrições.", "Repare que a mesma contração ’s pode ser is ou has, dependendo do contexto: it’s cold (it is) x it’s gone (it has)."], ["I’m / you’re / he’s / she’s / we’re / they’re — to be", "I’ve / you’ve / he’s / we’ve / they’ve — have/has", "it’s ready (it is) x it’s started (it has)"]),
    section("Contrações negativas", ["Juntam o verbo auxiliar a not: don’t, doesn’t, didn’t, isn’t, aren’t, wasn’t, weren’t, haven’t, won’t, can’t. São essenciais — e no listening o ‘not’ reduzido é fácil de perder, o que inverte o sentido da frase.", "Preste atenção especial a won’t (will not) e can’t (cannot), que mudam bastante em relação à forma completa."], ["don’t / doesn’t / didn’t — negativas com do", "isn’t / aren’t / wasn’t / weren’t — negativas de be", "won’t (will not) / can’t (cannot) — atenção na escuta"]),
    section("Os pares que mais confundem", ["Algumas contrações soam igual a outras palavras e geram erro na escrita. Os campeões: it’s (it is/has) x its (posse); you’re (you are) x your (seu); they’re (they are) x their (deles) x there (lá); who’s (who is) x whose (de quem).", "Um teste rápido: se dá para ‘desmontar’ em duas palavras (it is, you are), é a forma com apóstrofo. Se é posse, não leva apóstrofo."], ["it’s = it is/has ≠ its (posse)", "you’re = you are ≠ your (seu)", "they’re = they are ≠ their (deles) ≠ there (lá)", "who’s = who is ≠ whose (de quem)"]),
    section("Quando evitar contrações", ["Em textos muito formais (documentos oficiais, trabalhos acadêmicos, contratos), a forma completa costuma ser preferida. Em e-mails e mensagens informais, as contrações são bem-vindas. Na fala, use sempre — elas soam naturais.", "Para dar ênfase, às vezes se usa a forma completa de propósito: I do want to go (quero mesmo ir)."]),
    section("Perguntas frequentes", ["Contração é informal demais? Para a fala e a escrita do dia a dia, não — é o padrão; só evite em textos muito formais. Qual a diferença de it’s e its? It’s = it is/has; its = posse (sem apóstrofo). ’s é sempre ‘is’? Não — pode ser is ou has (às vezes possessivo em substantivos). Preciso usar contrações para falar bem? Ajuda muito a soar natural e a entender os outros."]),
    section("Continue praticando", ["Contrações andam de mãos dadas com a fala conectada — juntas, explicam por que o inglês falado soa ‘grudado’. Combine este tema com o estudo do connected speech e pratique ouvindo diálogos curtos nas aulas do curso."], undefined, undefined, [{label:"Connected speech: por que os sons se ligam",url:"/blog/connected-speech-ligacao-sons"},{label:"Como entender inglês falado sem traduzir",url:"/blog/como-entender-ingles-falado-listening"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-no-restaurante", "Inglês para viagens", "Inglês no restaurante: frases para pedir comida do início ao fim", "Frases prontas em inglês para o restaurante: reservar mesa, pedir o cardápio, fazer o pedido, perguntar sobre ingredientes, pedir a conta e lidar com alergias.", "☕", ["inglês restaurante", "pedir comida inglês", "frases restaurante inglês", "inglês para restaurante", "como pedir comida em inglês", "the bill the check restaurante"], "Comer fora é uma das situações em que o inglês de viagem é mais útil — e mais previsível. Do momento em que você entra até pagar a conta, as frases se repetem: pedir mesa, ver o cardápio, fazer o pedido, perguntar sobre um prato, pedir a conta. Neste guia você encontra frases prontas para cada etapa, as perguntas comuns do garçom (para você entender a resposta) e o vocabulário essencial, incluindo como avisar sobre alergias com segurança.", [
    section("Chegando e pedindo uma mesa", ["Ao chegar, você pode dizer quantas pessoas são e se tem reserva. O anfitrião costuma perguntar How many people? ou Do you have a reservation? Entender essas perguntas ajuda a responder com naturalidade.", "Se não houver reserva, basta dizer o número de pessoas."], ["A table for two, please. — Uma mesa para dois, por favor.", "We have a reservation under Silva. — Temos uma reserva em nome de Silva.", "Do you have a table available? — Vocês têm mesa disponível?"]),
    section("Pedindo o cardápio e fazendo o pedido", ["I’d like… e Could I have…? são as formas mais educadas de pedir. Para começar, você pode pedir o cardápio ou recomendações. O garçom costuma perguntar Are you ready to order? e What would you like to drink?", "Use for starters (entrada) e for the main course (prato principal) para organizar o pedido."], ["Could I see the menu, please? — Posso ver o cardápio, por favor?", "What do you recommend? — O que você recomenda?", "I’d like the grilled chicken, please. — Eu gostaria do frango grelhado, por favor.", "For starters, I’ll have the soup. — De entrada, vou querer a sopa."]),
    section("Perguntando sobre os pratos e alergias", ["Se tiver dúvida sobre um prato, pergunte do que ele é feito. E, se você tem alergia ou restrição alimentar, diga isso de forma clara e peça confirmação — não presuma que a equipe entendeu um detalhe importante de saúde.", "Para restrições, deixe explícito e, se necessário, peça que confirmem com a cozinha."], ["What’s in this dish? — O que tem neste prato?", "Is this vegetarian? — Isto é vegetariano?", "I’m allergic to peanuts. Could you check with the kitchen? — Tenho alergia a amendoim. Poderia confirmar com a cozinha?", "Does this contain gluten? — Isto contém glúten?"]),
    section("Durante a refeição", ["Você pode precisar pedir algo a mais, dizer que está tudo bem ou pedir água. Frases curtas com please resolvem a maioria das situações.", "Se algo estiver errado com o pedido, explique de forma objetiva e educada."], ["Could I have some water, please? — Poderia me trazer água, por favor?", "Everything is great, thank you. — Está tudo ótimo, obrigado.", "Excuse me, this isn’t what I ordered. — Com licença, não foi isto que pedi."]),
    section("Pedindo a conta e pagando", ["Para pedir a conta, use Could we have the bill, please? (mais britânico) ou the check (mais americano). Confirme se pode pagar com cartão e, se quiser, pergunte sobre gorjeta — em alguns países ela já vem incluída, em outros é esperada à parte.", "Nunca autorize um pagamento sem conferir o valor."], ["Could we have the bill, please? — Poderia trazer a conta, por favor?", "Can I pay by card? — Posso pagar com cartão?", "Is service included? — O serviço está incluído?"]),
    section("Vocabulário essencial do restaurante", ["Guardar algumas palavras-chave ajuda a entender o cardápio e o garçom. Muitos termos variam entre o inglês britânico e o americano (bill/check, starter/appetizer).", "Anote os que aparecem nos lugares que você costuma frequentar."], undefined, ["starter / appetizer — entrada", "main course — prato principal", "dessert — sobremesa", "the bill / the check — a conta", "waiter / server — garçom", "tip — gorjeta"]),
    section("Perguntas frequentes", ["É ‘the bill’ ou ‘the check’? Bill é mais britânico; check, mais americano — os dois são entendidos. Como peço ‘para viagem’? Can I get this to go? (EUA) ou takeaway (Reino Unido). Preciso dar gorjeta? Depende do país; pergunte Is service included? Como chamo o garçom? Um Excuse me educado basta."]),
    section("Continue praticando", ["O inglês de restaurante faz parte de um conjunto de situações de viagem que se repetem. Pratique nas aulas do curso e combine com os guias de compras e de aeroporto para viajar com mais confiança."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês para fazer compras",url:"/blog/ingles-para-compras"},{label:"Frases úteis no aeroporto",url:"/blog/ingles-no-aeroporto"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-para-compras", "Inglês para viagens", "Inglês para fazer compras: preço, tamanho, pagamento e troca", "Frases prontas em inglês para fazer compras: perguntar preço e disponibilidade, pedir outro tamanho, pagar, trocar ou devolver e lidar com o vocabulário de loja.", "£", ["inglês compras", "perguntar preço inglês", "tamanho pagamento inglês", "inglês para loja", "como comprar roupa em inglês", "frases compras inglês viagem"], "Fazer compras em inglês é uma das situações mais úteis em qualquer viagem — e também das mais previsíveis, porque as frases se repetem: você pergunta o preço, procura um tamanho, experimenta, paga e, às vezes, troca. Com algumas frases prontas e o vocabulário certo, você resolve tudo com confiança, da loja de roupas ao mercado. Neste guia você encontra o que dizer em cada etapa, as perguntas comuns do vendedor e as diferenças entre o inglês britânico e o americano.", [
    section("Entrar na loja e ser atendido", ["O vendedor costuma cumprimentar e perguntar se pode ajudar: Can I help you? Se você só está olhando, uma resposta educada é I’m just looking, thanks. Quando precisar de ajuda, use Could you help me…? ou I’m looking for…", "Essas frases simples deixam a interação leve e natural."], ["Can I help you? — Posso ajudar? (o vendedor)", "I’m just looking, thank you. — Só estou olhando, obrigado.", "I’m looking for a jacket. — Estou procurando uma jaqueta.", "Could you help me find…? — Poderia me ajudar a achar…?"]),
    section("Perguntar preço e disponibilidade", ["Para o preço, use How much is this? (singular) ou How much are these? (plural). Para checar se há o item, use Do you have…? e, para variações, in + cor/tamanho.", "Se o preço não estiver claro, vale confirmar antes de ir ao caixa."], ["How much is this? — Quanto custa isto?", "How much are these shoes? — Quanto custam estes sapatos?", "Do you have this in blue? — Você tem isto em azul?", "Is this on sale? — Isto está em promoção?"]),
    section("Tamanhos e provador", ["Tamanhos variam muito entre países e marcas, então é comum pedir outro. Use Do you have a bigger/smaller size? Para experimentar, pergunte onde fica o provador: Where can I try this on?", "Se não souber o seu tamanho local, peça ajuda: What size is this in the UK/US?"], ["Do you have a smaller size? — Tem um tamanho menor?", "Can I try this on? — Posso experimentar?", "Where’s the fitting room? — Onde fica o provador?", "It doesn’t fit. It’s too tight. — Não serve. Está apertado."]),
    section("Pagar", ["No caixa, confirme o total e a forma de pagamento. Card (cartão) e cash (dinheiro) são as palavras-chave. Peça recibo se precisar: Could I have a receipt? Nunca autorize um valor sem conferir.", "Em alguns lugares perguntam se você quer sacola (Do you need a bag?), às vezes paga."], ["Can I pay by card? — Posso pagar com cartão?", "I’ll pay in cash. — Vou pagar em dinheiro.", "Could I have a receipt, please? — Poderia me dar um recibo?", "Is there a tax refund for tourists? — Há isenção de imposto para turistas?"]),
    section("Trocar ou devolver", ["Se algo não serviu, você pode querer trocar (exchange) ou devolver (return) para reembolso (refund). Guarde o recibo, que costuma ser exigido. Explique o motivo de forma objetiva.", "Pergunte sobre a política de trocas: What’s your return policy?"], ["I’d like to return this, please. — Gostaria de devolver isto.", "Can I exchange it for a different size? — Posso trocar por outro tamanho?", "Here’s the receipt. — Aqui está o recibo.", "Can I get a refund? — Posso receber o reembolso?"]),
    section("Vocabulário essencial de compras", ["Algumas palavras aparecem o tempo todo e mudam entre o inglês britânico e o americano. Conhecê-las evita mal-entendidos no caixa e nas etiquetas.", "Anote as que você encontrar nas lojas que costuma frequentar."], undefined, ["sale / discount — promoção / desconto", "receipt — recibo", "fitting room (UK) / dressing room (US) — provador", "trousers (UK) / pants (US) — calça", "trolley (UK) / cart (US) — carrinho", "queue (UK) / line (US) — fila"]),
    section("Perguntas frequentes", ["É ‘how much is’ ou ‘how much are’? Is para singular, are para plural. Como peço desconto? Is there a discount? / Can you do a better price? (em mercados/feiras). ‘Trousers’ ou ‘pants’? Trousers no Reino Unido; pants nos EUA (no Reino Unido, pants é roupa íntima). Preciso de recibo para trocar? Geralmente sim — guarde-o."]),
    section("Continue praticando", ["O inglês de compras faz parte do conjunto de situações de viagem. Pratique nas aulas do curso e combine com os guias de restaurante e de pedir direções para se virar em qualquer cidade."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês no restaurante",url:"/blog/ingles-no-restaurante"},{label:"Como pedir e entender direções",url:"/blog/pedir-direcoes-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("pedir-direcoes-ingles", "Inglês para viagens", "Como pedir e entender direções em inglês", "Aprenda a perguntar como chegar a um lugar em inglês e, principalmente, a entender a resposta: verbos de movimento, pontos de referência e frases para confirmar o caminho.", "⌖", ["pedir direções em inglês", "como chegar inglês", "instruções de caminho inglês", "direções em inglês frases", "entender direções inglês", "where is how do i get to"], "Perguntar como chegar a algum lugar é fácil — o difícil costuma ser entender a resposta, cheia de verbos de movimento e pontos de referência ditos rápido. Por isso, saber pedir direções em inglês é só metade: a outra metade é reconhecer as instruções comuns e confirmar o que entendeu. Neste guia você aprende as perguntas certas, o vocabulário das respostas e as frases para não se perder, além de dicas de segurança para quando a precisão importa.", [
    section("Comece a pergunta com educação", ["Abra com Excuse me para chamar a atenção de forma educada e vá direto ao destino. Where is…? pergunta onde fica um lugar; How do I get to…? pergunta o caminho. Is there a … near here? serve para procurar algo próximo (farmácia, banco).", "Dizer o destino com clareza — e, se preciso, mostrá-lo escrito — evita confusão com a pronúncia de nomes próprios."], ["Excuse me, where is the train station? — Com licença, onde fica a estação?", "How do I get to the museum? — Como chego ao museu?", "Is there a pharmacy near here? — Há uma farmácia por aqui?", "What’s the best way to the center? — Qual o melhor caminho para o centro?"]),
    section("Entenda os verbos de movimento", ["As respostas giram em torno de poucos verbos e direções: go straight (siga reto), turn left/right (vire à esquerda/direita), take the first/second… (pegue a primeira/segunda…). Reconhecê-los de ouvido é o que mais ajuda.", "Preste atenção aos números ordinais (first, second, third), muito usados para ruas e cruzamentos."], ["Go straight ahead. — Siga reto.", "Turn left at the corner. — Vire à esquerda na esquina.", "Take the second street on the right. — Pegue a segunda rua à direita.", "Go past the bank. — Passe pelo banco."]),
    section("Pontos de referência e posição", ["As pessoas descrevem o caminho por referências: it’s next to (ao lado de), opposite / across from (em frente a), between (entre), on the corner (na esquina), at the end of (no fim de). Esse vocabulário de posição é a chave para achar o ponto final.", "Também é comum ouvir distâncias e tempo: it’s a five-minute walk (fica a cinco minutos a pé)."], ["It’s next to the pharmacy. — Fica ao lado da farmácia.", "It’s across from the park. — Fica em frente ao parque.", "It’s on the corner of King Street. — Fica na esquina da King Street.", "It’s about a ten-minute walk. — Fica a uns dez minutos a pé."]),
    section("Confirme para não se perder", ["Direções ditas rápido são difíceis até para nativos. Não finja que entendeu: repita o ponto principal e confirme. Use So, I turn left and then…? ou peça para repetir e falar devagar. Melhor confirmar do que andar para o lado errado.", "Se a instrução for longa, confirme por partes, um passo de cada vez."], ["Sorry, could you repeat that? — Desculpe, pode repetir?", "So, I go straight and turn right? — Então, sigo reto e viro à direita?", "Is it far? — É longe?", "Could you show me on the map? — Pode me mostrar no mapa?"]),
    section("Dicas de segurança e tecnologia", ["Para trajetos importantes ou à noite, combine a ajuda das pessoas com um mapa no celular — assim você confirma a rota e não depende só do que entendeu de ouvido. Pedir para apontar no mapa (Could you show me on the map?) evita erros de pronúncia e de nomes de ruas.", "Confie no seu bom senso: se algo não parecer seguro, agradeça e confirme a rota por outra fonte."]),
    section("Perguntas frequentes", ["É ‘where is’ ou ‘how do I get to’? Where is pergunta a localização; how do I get to pergunta o caminho. Como digo ‘fica perto/longe’? It’s near / It’s far / It’s a short walk. E se eu não entender a resposta? Peça para repetir devagar ou mostrar no mapa. ‘Opposite’ e ‘across from’ são iguais? Sim, ambos significam ‘em frente a’."]),
    section("Continue praticando", ["Pedir direções é parte do inglês de viagem do dia a dia. Pratique nas aulas do curso e combine com os guias de transporte público e de compras para circular por qualquer cidade com confiança."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês no transporte público",url:"/blog/ingles-transporte-publico"},{label:"Como pedir para repetir em inglês",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-transporte-publico", "Inglês para viagens", "Inglês no transporte público: ônibus, trem e metrô", "Frases prontas em inglês para o transporte público: confirmar o destino, comprar passagem, achar a plataforma, entender conexões e lidar com atrasos e mudanças.", "⇄", ["inglês transporte público", "ônibus trem inglês", "passagem plataforma inglês", "inglês metrô", "como usar transporte público inglês", "frases trem ônibus inglês"], "Usar ônibus, trem e metrô em outro país economiza muito dinheiro — e exige um inglês bem específico, mas previsível. As perguntas se repetem: este transporte vai ao meu destino? de qual plataforma? preciso trocar? Com algumas frases e o vocabulário certo, você compra a passagem, acha o caminho e entende os avisos. Neste guia você vê o que dizer e o que escutar em cada etapa, além das diferenças entre o inglês britânico e o americano.", [
    section("Comprar a passagem", ["Ticket é a palavra-chave para passagem. Você pode pedir ida (single, no Reino Unido; one-way, nos EUA) ou ida e volta (return / round trip). Diga o destino e o tipo. Bilheterias e máquinas são comuns; se tiver dúvida, pergunte onde comprar.", "Confirme o valor antes de pagar e guarde o bilhete, às vezes exigido na saída."], ["Where can I buy a ticket? — Onde compro uma passagem?", "A single to Oxford, please. — Uma passagem de ida para Oxford. (UK)", "A round trip to Boston, please. — Ida e volta para Boston. (US)", "How much is a ticket to the center? — Quanto custa até o centro?"]),
    section("Confirmar o destino e a plataforma", ["Antes de embarcar, confirme que o transporte vai ao seu destino e de onde ele parte. Does this bus/train go to…? resolve a primeira dúvida; Which platform…? (trem) ou Which stop…? (ônibus), a segunda.", "Plataforma é platform; nos EUA, o metrô é subway; no Reino Unido, o metrô de Londres é the Underground ou the Tube."], ["Does this train go to Cambridge? — Este trem vai para Cambridge?", "Which platform does it leave from? — De qual plataforma ele sai?", "Where’s the bus stop for the airport? — Onde fica o ponto do ônibus para o aeroporto?", "Is this the right stop for the museum? — Este é o ponto certo para o museu?"]),
    section("Conexões e trocas", ["Em trajetos maiores, você pode precisar trocar de linha. Change (trocar) e connection (conexão) são as palavras. Pergunte se precisa trocar e onde. Entender a resposta evita descer no lugar errado.", "Em metrô, é comum falar em line (linha) e direção pelo nome da estação final."], ["Do I need to change trains? — Preciso trocar de trem?", "Where do I change for line 2? — Onde troco para a linha 2?", "Is this a direct train? — É um trem direto?", "How many stops is it? — São quantas paradas?"]),
    section("Horários e avisos", ["Pergunte quando parte ou chega e, principalmente, confie nos painéis e anúncios oficiais, sobretudo se houver mudança de serviço. Palavras como delayed (atrasado), cancelled (cancelado) e platform change (mudança de plataforma) aparecem muito.", "Se um anúncio for rápido demais, confirme a informação com um funcionário ou no painel."], ["What time does the next train leave? — Que horas sai o próximo trem?", "Is the train on time? — O trem está no horário?", "The train is delayed. — O trem está atrasado.", "Has the platform changed? — A plataforma mudou?"]),
    section("Quando algo dá errado", ["Perder a parada, pegar o sentido errado ou enfrentar greve acontece. Saber pedir ajuda com clareza resolve rápido. Para o cartão de transporte, use travel card / metro card conforme a cidade.", "Mostrar o nome do destino escrito ajuda quando a pronúncia causa dúvida."], ["I think I’m going the wrong way. — Acho que estou no sentido errado.", "I missed my stop. — Perdi a minha parada.", "Does this card work on the bus too? — Este cartão funciona no ônibus também?", "Could you tell me when to get off? — Pode me avisar quando descer?"]),
    section("Vocabulário essencial do transporte", ["Muitas palavras mudam entre o inglês britânico e o americano. Conhecê-las evita confusão nas placas e nos bilhetes.", "Anote as usadas na cidade que você vai visitar."], undefined, ["single / one-way — só ida", "return / round trip — ida e volta", "platform — plataforma", "the Underground, the Tube (UK) / subway (US) — metrô", "fare — tarifa", "timetable / schedule — horário"]),
    section("Perguntas frequentes", ["É ‘single’ ou ‘one-way’? Single no Reino Unido; one-way nos EUA. Como se chama o metrô? Subway (EUA), the Underground/the Tube (Londres), metro (muitas cidades). Preciso validar o bilhete? Em muitos lugares, sim — confira as máquinas. E se eu errar o transporte? Desça na próxima parada e pergunte o caminho de volta."]),
    section("Continue praticando", ["O transporte público completa o kit de viagem. Pratique nas aulas do curso e combine com os guias de aeroporto e de pedir direções para ir do desembarque ao destino sem estresse."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês no aeroporto",url:"/blog/ingles-no-aeroporto"},{label:"Como pedir e entender direções",url:"/blog/pedir-direcoes-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-no-hotel", "Inglês para viagens", "Inglês no hotel: check-in, pedidos e check-out", "Frases prontas em inglês para o hotel: confirmar a reserva, fazer check-in, pedir serviços, resolver problemas no quarto e fazer o check-out com tranquilidade.", "⌂", ["inglês hotel check-in", "frases recepção hotel", "reserva hospedagem inglês", "inglês para hotel", "check-in check-out inglês", "frases hotel viagem inglês"], "Hospedar-se num hotel fora do país é uma situação em que o inglês se repete de forma bem previsível: você confirma a reserva, faz o check-in, pede alguns serviços, às vezes resolve um problema no quarto e faz o check-out. Com frases prontas para cada etapa e o vocabulário certo, você resolve tudo com segurança na recepção. Neste guia você vê o que dizer e o que a equipe costuma perguntar, do momento da chegada até a saída.", [
    section("Chegada e check-in", ["Ao chegar, diga que tem uma reserva e informe o nome usado. A recepção costuma pedir documento e, às vezes, um cartão para garantia. Perguntas comuns: Do you have a reservation? e Could I see your passport?", "Confirme os detalhes importantes: datas, tipo de quarto e valor."], ["I have a reservation under Silva. — Tenho uma reserva em nome de Silva.", "I’d like to check in, please. — Gostaria de fazer o check-in.", "Could you confirm the dates? — Poderia confirmar as datas?", "Is breakfast included? — O café da manhã está incluído?"]),
    section("Perguntar sobre serviços e horários", ["Confirme horários e serviços diretamente com a equipe: café da manhã, check-out, wi-fi, estacionamento. São as dúvidas mais frequentes e fáceis de resolver com perguntas curtas.", "Anote ou peça por escrito o que for importante (senha do wi-fi, horário do café)."], ["What time is breakfast? — Que horas é o café da manhã?", "What time is check-out? — Que horas é o check-out?", "What’s the wifi password? — Qual é a senha do wi-fi?", "Is there parking? — Tem estacionamento?"]),
    section("Pedidos no quarto", ["Para pedir algo ao quarto ou à recepção, use Could I have…? ou Could you send…? Toalhas extras, outra almofada, despertador, late check-out: tudo se resolve com frases simples e please.", "Para serviço de quarto, a expressão é room service."], ["Could I have extra towels, please? — Poderia trazer toalhas extras?", "Could you send someone to the room? — Poderia enviar alguém ao quarto?", "Is late check-out possible? — É possível fazer o check-out mais tarde?", "Could I have a wake-up call at seven? — Poderia me acordar às sete?"]),
    section("Resolver um problema", ["Se algo não funciona, explique de forma objetiva e educada e peça ajuda. Problemas comuns: cartão-chave, ar-condicionado, chuveiro, barulho. A recepção costuma resolver rápido quando você é claro.", "Descreva o problema sem rodeios, dizendo o número do quarto."], ["The key card isn’t working. — O cartão-chave não está funcionando.", "The air conditioning is broken. — O ar-condicionado está quebrado.", "There’s no hot water. — Não tem água quente.", "The room is too noisy. Could I change rooms? — O quarto é barulhento. Posso trocar?"]),
    section("Check-out e pagamento", ["No check-out, confirme a conta item por item antes de pagar — e questione qualquer cobrança que não reconhecer. Você pode pedir para guardar a bagagem após o check-out, algo comum em hotéis.", "Nunca autorize um pagamento sem conferir o valor e a moeda."], ["I’d like to check out, please. — Gostaria de fazer o check-out.", "Could I have the bill, please? — Poderia me dar a conta?", "What’s this charge for? — Do que é esta cobrança?", "Could you keep my luggage until the afternoon? — Poderia guardar minha bagagem até a tarde?"]),
    section("Vocabulário essencial do hotel", ["Algumas palavras aparecem em toda estadia e vale reconhecê-las nas placas e na conta.", "Anote as que surgirem no seu hotel."], undefined, ["reservation / booking — reserva", "single / double room — quarto de solteiro / casal", "check-in / check-out — entrada / saída", "front desk / reception — recepção", "key card — cartão-chave", "room service — serviço de quarto"]),
    section("Perguntas frequentes", ["Preciso dar gorjeta no hotel? Depende do país; em muitos, é comum para carregadores e camareiras. ‘Booking’ ou ‘reservation’? São sinônimos para reserva. Como peço para guardar a mala? Could you store my luggage, please? E se houver cobrança errada? Questione na hora: What’s this charge for? — confira antes de pagar."]),
    section("Continue praticando", ["O inglês de hotel completa o conjunto de situações de viagem. Pratique nas aulas do curso e combine com os guias de aeroporto e de restaurante para viajar com mais autonomia."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês no aeroporto",url:"/blog/ingles-no-aeroporto"},{label:"Inglês no restaurante",url:"/blog/ingles-no-restaurante"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-no-aeroporto", "Inglês para viagens", "Inglês no aeroporto: frases para check-in, embarque e imigração", "Frases prontas e vocabulário em inglês para o aeroporto: check-in, bagagem, segurança, portão, embarque e as perguntas da imigração que você precisa entender.", "✈", ["inglês aeroporto", "check-in voo inglês", "portão embarque bagagem inglês", "inglês no aeroporto frases", "perguntas imigração inglês", "boarding gate check-in inglês"], "O aeroporto segue um roteiro parecido no mundo todo, e isso facilita muito: as mesmas situações se repetem — check-in, bagagem, segurança, portão, embarque e, em voos internacionais, a imigração. Saber o vocabulário e algumas frases prontas tira o nervosismo e evita perder tempo. Neste guia você acompanha cada etapa, com o que dizer e, tão importante quanto, as perguntas que a equipe costuma fazer para você entender e responder.", [
    section("No check-in", ["No balcão de check-in, você apresenta documento e passagem e despacha a bagagem. O atendente costuma perguntar How many bags are you checking? e Window or aisle? (janela ou corredor). Entender essas perguntas deixa tudo mais rápido.", "Peça ajuda para achar o balcão certo se necessário."], ["Where is the check-in desk for flight BA123? — Onde fica o balcão do voo BA123?", "I’d like a window seat, please. — Eu gostaria de um assento na janela, por favor.", "Can I check this bag? — Posso despachar esta mala?", "Is this flight on time? — Este voo está no horário?"]),
    section("Bagagem e segurança", ["Há vocabulário específico: carry-on (bagagem de mão), checked baggage (despachada), overweight (acima do peso). Na segurança, você costuma ouvir instruções para tirar itens: Take off your belt, Laptops out of the bag.", "Siga as instruções e pergunte se algo não ficou claro."], ["How much is the baggage allowance? — Qual é a franquia de bagagem?", "Do I need to take out my laptop? — Preciso tirar o notebook?", "My suitcase is overweight. — Minha mala está acima do peso."]),
    section("Portão de embarque e boarding", ["Gate é o portão; boarding é o embarque. O portão pode mudar, então confira sempre o painel (departures board). Anúncios comuns: Now boarding, Final call, The gate is closing.", "Se tiver dúvida sobre o portão, pergunte à equipe."], ["Which gate is it for flight AF45? — Qual é o portão do voo AF45?", "Has the gate changed? — O portão mudou?", "When does boarding begin? — Quando começa o embarque?", "Is this the line for boarding? — Esta é a fila do embarque?"]),
    section("Na imigração e alfândega", ["Em voos internacionais, o oficial de imigração faz perguntas padrão: o motivo da viagem, quanto tempo vai ficar e onde vai se hospedar. Responda de forma curta e verdadeira. Essas perguntas se repetem em quase todo país.", "Tenha os documentos à mão e não adivinhe informações — se não entender, peça para repetir."], ["What’s the purpose of your trip? — Qual é o motivo da sua viagem?", "I’m here on vacation. / for business. — Estou aqui a passeio. / a negócios.", "How long will you stay? — Quanto tempo vai ficar?", "I’ll stay for two weeks. — Vou ficar duas semanas."]),
    section("Quando algo dá errado", ["Atrasos, cancelamentos e bagagem extraviada acontecem. Saber pedir ajuda com clareza faz diferença. Para bagagem perdida, procure o balcão de lost luggage / baggage claim.", "Peça informações oficiais e não dependa só do que entendeu de ouvido em um anúncio."], ["My flight was cancelled. What are my options? — Meu voo foi cancelado. Quais são minhas opções?", "My luggage didn’t arrive. — Minha bagagem não chegou.", "Could you repeat that, please? — Poderia repetir, por favor?"]),
    section("Vocabulário essencial do aeroporto", ["Reconhecer essas palavras nos painéis e anúncios é metade do caminho. Muitas são parecidas em vários idiomas, o que ajuda.", "Anote as que você encontrar na sua próxima viagem."], undefined, ["departure / arrival — partida / chegada", "boarding pass — cartão de embarque", "gate — portão", "delayed / cancelled — atrasado / cancelado", "connection / layover — conexão / escala", "baggage claim — esteira de bagagem"]),
    section("Perguntas frequentes", ["Preciso falar inglês perfeito na imigração? Não — respostas curtas e verdadeiras bastam. Como peço para repetir? Sorry, could you repeat that? O que é ‘layover’? Uma escala entre voos. ‘Carry-on’ é o quê? Bagagem de mão. E se eu travar? Mostrar a passagem e apontar costuma resolver; peça ajuda sem medo."]),
    section("Continue praticando", ["O inglês de aeroporto faz parte do kit de viagem. Pratique nas aulas do curso e combine com os guias de hotel e de transporte público para se virar do desembarque até o destino."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Inglês para o check-in no hotel",url:"/blog/ingles-no-hotel"},{label:"Inglês no transporte público",url:"/blog/ingles-transporte-publico"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "9 min"),
  article("ingles-medico-farmacia", "Inglês para viagens", "Como explicar sintomas em inglês na farmácia ou no médico", "Frases em inglês para descrever sintomas, falar de alergias e remédios e pedir ajuda na farmácia ou numa consulta — com um aviso importante sobre emergências.", "+", ["sintomas inglês", "inglês farmácia médico", "descrever dor inglês", "explicar sintomas em inglês", "frases médico inglês", "inglês para emergência saúde"], "Precisar de uma farmácia ou de um médico em viagem é estressante — e fazer isso em inglês, mais ainda. Mas você não precisa de vocabulário técnico: com frases simples para dizer o que sente, quando começou e do que tem alergia, já consegue ser atendido e entendido. Neste guia você encontra as frases essenciais para a farmácia e para a consulta. Importante: este é um guia de idioma, não de saúde — em emergências, procure imediatamente os serviços locais.", [
    section("Dizer o que você sente", ["Há duas estruturas-chave. Para muitos sintomas, use I have a/an… (I have a headache). Para dor em uma parte do corpo, use My … hurts (My back hurts) ou I have a pain in my… Diga também há quanto tempo começou.", "Frases curtas e diretas funcionam melhor que tentar traduzir termos médicos."], ["I have a headache / a fever / a cough. — Estou com dor de cabeça / febre / tosse.", "My throat hurts. — Minha garganta dói.", "I have a pain in my stomach. — Tenho uma dor no estômago.", "It started two days ago. — Começou há dois dias."]),
    section("Na farmácia", ["A farmácia (pharmacy no inglês americano, chemist’s no britânico) resolve sintomas leves. Diga o sintoma e pergunte o que recomendam. O farmacêutico pode perguntar sobre alergias e outros remédios.", "Pergunte como tomar: How often should I take it? (de quanto em quanto tempo)."], ["Do you have anything for a cold? — Você tem algo para resfriado?", "What do you recommend for a headache? — O que recomenda para dor de cabeça?", "How often should I take this? — De quanto em quanto tempo tomo isto?", "Do I need a prescription? — Preciso de receita?"]),
    section("Falar de alergias e remédios", ["Informação de saúde precisa ser clara. Diga suas alergias e os remédios que usa com precisão, e peça confirmação se algo não ficou claro. Não presuma que um detalhe importante foi entendido.", "Se necessário, peça que escrevam a orientação: Could you write that down?"], ["I’m allergic to penicillin. — Tenho alergia à penicilina.", "I take medication for… — Tomo remédio para…", "Is this safe with other medicines? — Isto é seguro com outros remédios?", "Could you write that down, please? — Poderia escrever isso?"]),
    section("Na consulta médica", ["No médico, você vai descrever os sintomas, responder desde quando sente e seguir orientações. Responda de forma curta e verdadeira. Se não entender uma instrução, peça para repetir ou explicar de outro jeito — entender o tratamento é essencial.", "Pergunte o que precisar sobre o diagnóstico e os próximos passos."], ["I’ve been feeling sick since yesterday. — Estou me sentindo mal desde ontem.", "It hurts when I move. — Dói quando eu me movo.", "Could you explain that again? — Poderia explicar de novo?", "What should I do next? — O que devo fazer agora?"]),
    section("Emergências: priorize o atendimento", ["Em uma emergência, não dependa de frases decoradas: procure imediatamente os serviços locais. Vale saber o número de emergência do país (112 na Europa, 911 nos EUA, 999 no Reino Unido) e a frase para pedir ajuda. Um guia de idioma não oferece diagnóstico nem recomendação de tratamento.", "Se possível, peça a alguém que ligue por você e informe a localização."], ["I need an ambulance. — Preciso de uma ambulância.", "It’s an emergency. — É uma emergência.", "Please call a doctor. — Por favor, chame um médico.", "Where’s the nearest hospital? — Onde fica o hospital mais próximo?"]),
    section("Vocabulário essencial de saúde", ["Reconhecer essas palavras ajuda na farmácia, na consulta e nas bulas.", "Anote as que forem relevantes para você (alergias, condições, remédios de uso contínuo)."], undefined, ["pharmacy (US) / chemist’s (UK) — farmácia", "prescription — receita médica", "painkiller — analgésico", "allergy — alergia", "symptom — sintoma", "appointment — consulta marcada"]),
    section("Perguntas frequentes", ["Preciso de inglês avançado para ser atendido? Não — frases simples e verdadeiras bastam. Como digo que tenho alergia? I’m allergic to… ‘Pharmacy’ ou ‘chemist’? Pharmacy nos EUA; chemist’s no Reino Unido. E numa emergência? Ligue para o número local (911/999/112) e diga It’s an emergency — não confie só em frases decoradas."]),
    section("Continue praticando", ["Saúde é uma das situações práticas de viagem. Pratique nas aulas do curso e combine com os guias de hotel e de pedir para repetir, úteis quando você precisa confirmar uma informação importante."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como pedir para repetir em inglês",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Inglês no hotel",url:"/blog/ingles-no-hotel"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("marcar-consulta-por-telefone-ingles", "Inglês para situações práticas", "Como marcar ou alterar um horário por telefone em inglês", "Aprenda a marcar, remarcar e cancelar um horário por telefone em inglês: abrir a ligação, pedir uma data, confirmar os detalhes e lidar com a dificuldade de entender ao telefone.", "☎", ["marcar consulta inglês telefone", "appointment phone call english", "alterar horário inglês", "como marcar horário por telefone inglês", "remarcar consulta inglês", "frases telefone inglês"], "Falar ao telefone em inglês assusta mais que uma conversa presencial — sem gestos nem expressões, você depende só do áudio, e ainda por cima costuma ser com um desconhecido. Marcar um horário (uma consulta, um corte de cabelo, uma reunião) é uma das ligações mais comuns, e felizmente segue um roteiro previsível: você abre, diz o que quer, acerta a data e confirma. Neste guia você vê as frases de cada etapa e como lidar quando não entende a resposta.", [
    section("Abrir a ligação", ["Comece cumprimentando e dizendo o motivo. Hello / Hi é suficiente, seguido de I’d like to… ou I’m calling to… Dizer logo o objetivo ajuda a pessoa do outro lado a te direcionar.", "Se precisar, identifique-se com o nome no começo ou quando pedirem."], ["Hello, I’d like to make an appointment. — Olá, gostaria de marcar um horário.", "I’m calling to book a table for Saturday. — Estou ligando para reservar uma mesa para sábado.", "Hi, this is Ana Souza. — Oi, aqui é a Ana Souza."]),
    section("Pedir uma data e horário", ["Appointment é a palavra para consulta ou compromisso marcado; booking/reservation para reservas. Peça disponibilidade e ofereça suas preferências. A pessoa pode perguntar What day suits you? ou What time works for you?", "Diga dia e período para agilizar: morning, afternoon, evening."], ["Do you have anything available on Friday? — Há algo disponível na sexta?", "Could I book an appointment for next week? — Poderia marcar para a semana que vem?", "Is there anything in the morning? — Tem algum horário de manhã?", "Any time after 5 p.m. works for me. — Qualquer horário depois das 17h serve."]),
    section("Remarcar ou cancelar", ["Para mudar um horário já marcado, use reschedule (remarcar) ou cancel (cancelar). Explique o que precisa e ofereça uma alternativa, se souber. Seja educado — um please ou sorry suaviza.", "Avise com antecedência quando puder; alguns lugares cobram cancelamento em cima da hora."], ["I need to reschedule my appointment. — Preciso remarcar meu horário.", "Could I change it to Monday morning? — Poderia mudar para segunda de manhã?", "I’m afraid I have to cancel. — Infelizmente preciso cancelar.", "Sorry for the short notice. — Desculpe o aviso em cima da hora."]),
    section("Confirmar os detalhes", ["Antes de desligar, repita os dados principais — dia, horário, local e nome — para ter certeza. Esse resumo final evita o erro mais comum ao telefone: entender a data errada.", "Em contexto internacional, confirme dia e mês separadamente, porque os formatos de data mudam (03/04 pode ser 3 de abril ou 4 de março)."], ["So, that’s Tuesday the 10th at 3 p.m.? — Então é terça, dia 10, às 15h?", "Let me confirm: Friday morning, under the name Souza. — Deixe-me confirmar: sexta de manhã, em nome de Souza.", "Could you confirm the address? — Poderia confirmar o endereço?"]),
    section("Quando você não entende", ["Ao telefone é normal não captar tudo. Não finja que entendeu um horário ou endereço — peça para repetir, falar devagar ou soletrar. É melhor um pedido educado do que aparecer no dia errado.", "Para datas e números, peça que digam devagar ou por extenso."], ["Sorry, could you repeat that? — Desculpe, poderia repetir?", "Could you speak a little more slowly, please? — Poderia falar um pouco mais devagar?", "Could you spell the name for me? — Poderia soletrar o nome?"]),
    section("Perguntas frequentes", ["Como atendo e me identifico? This is + seu nome (This is Ana). ‘Appointment’ ou ‘reservation’? Appointment para consultas/compromissos; reservation/booking para mesas e hotéis. E se eu travar? Diga Sorry, could you repeat that? e confirme por partes. Preciso falar rápido? Não — devagar e claro é melhor, inclusive para você entender a resposta."]),
    section("Continue praticando", ["Ligações seguem roteiros que você pode treinar antes. Pratique nas aulas do curso e combine este guia com o de pedir para repetir e o de soletrar nomes e números, essenciais ao telefone."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como pedir para repetir em inglês",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Como soletrar nomes, e-mails e números",url:"/blog/soletrar-nome-email-ingles"},{label:"Como dizer as horas em inglês",url:"/blog/como-dizer-horas-em-ingles"}]),
  ], "8 min"),
  article("small-talk-em-ingles", "Conversação", "Small talk em inglês: como iniciar e manter uma conversa casual", "Aprenda a fazer small talk em inglês: como começar, bons assuntos e temas a evitar, frases para manter a conversa e como encerrar com educação, sem travar.", "…", ["small talk inglês", "conversa casual inglês", "iniciar conversa em inglês", "small talk frases", "como puxar conversa em inglês", "temas de conversa inglês"], "Small talk é aquela conversa leve e breve que acontece antes de uma reunião, numa festa, no elevador ou esperando um café. Em culturas de língua inglesa, ela é importante para quebrar o gelo e criar conexão — e muita gente acha mais difícil que gramática avançada, porque exige espontaneidade. A boa notícia: small talk segue padrões previsíveis. Neste guia você aprende a começar, manter e encerrar uma conversa casual, com frases prontas e os temas a evitar.", [
    section("O que é small talk e por que importa", ["Small talk é conversa social, sem o objetivo de resolver algo — serve para criar um clima agradável. Em contextos profissionais e sociais de língua inglesa, participar dela é visto como educação e sociabilidade, não como perda de tempo.", "Não precisa ser profundo: o valor está em mostrar interesse e simpatia, não em dizer algo brilhante."]),
    section("Como começar: assuntos seguros", ["Os melhores inícios partem de algo compartilhado: o lugar, o evento, o clima, a comida, uma situação em comum. São temas neutros e fáceis de responder, o que deixa o outro confortável.", "Uma observação seguida de pergunta funciona muito bem para abrir."], ["How are you enjoying the event? — O que está achando do evento?", "Have you tried the coffee here? — Já experimentou o café daqui?", "Lovely weather today, isn’t it? — Belo tempo hoje, não é?", "Is this your first time here? — É a sua primeira vez aqui?"]),
    section("Como manter a conversa viva", ["Conversa não é interrogatório. O segredo é o equilíbrio: responda à pergunta, acrescente um detalhe e devolva a palavra. Perguntas abertas (com what, how, why) rendem mais que as de sim/não. E reagir ao que o outro diz (Oh, really? That sounds great!) mostra atenção.", "Esse vai e volta — responder, acrescentar, perguntar de volta — é o motor do small talk."], ["What do you do? — O que você faz?", "I work in design. What about you? — Trabalho com design. E você?", "Oh, really? How interesting! — Ah, é mesmo? Que interessante!", "That sounds great. Tell me more. — Que legal. Conta mais."]),
    section("Temas a evitar", ["Alguns assuntos são arriscados com quem você não conhece bem, sobretudo em contextos profissionais: política, religião, dinheiro/salário, idade, peso e perguntas muito pessoais. A regra é manter o tom leve e não presumir intimidade.", "Na dúvida, fique nos temas seguros: trabalho (de forma geral), viagens, comida, hobbies, o evento, planos de fim de semana."], undefined, ["Evite: política, religião, salário, idade, peso, temas íntimos", "Prefira: trabalho em geral, viagens, hobbies, comida, o evento, fim de semana"]),
    section("Como encerrar com educação", ["Terminar bem é tão importante quanto começar. Sinalize o fim com uma frase de transição e algo cordial. Se a outra pessoa responde pouco ou parece ocupada, encerre sem insistir.", "Um fecho simpático deixa uma boa impressão e abre espaço para futuras conversas."], ["It was great talking to you. — Foi ótimo conversar com você.", "I should get going, but have a great day! — Preciso ir, mas tenha um ótimo dia!", "Let’s catch up later. — A gente se fala depois."]),
    section("Frases prontas para não travar", ["Ter algumas frases ‘de bolso’ ajuda nos momentos de silêncio. Perguntas sobre fim de semana, planos e o que a pessoa anda fazendo quase sempre funcionam e são fáceis de responder.", "Pratique essas frases até saírem naturalmente — assim você não congela quando surge a oportunidade."], ["Any plans for the weekend? — Planos para o fim de semana?", "How was your weekend? — Como foi seu fim de semana?", "What do you like to do in your free time? — O que você gosta de fazer no tempo livre?"]),
    section("Perguntas frequentes", ["Small talk é obrigatório? Em muitos contextos de língua inglesa é esperado, mas pode ser curto. E se der um silêncio? É normal; use uma frase pronta ou um comentário sobre o ambiente. Falar do tempo é clichê? É clássico e seguro, justamente por isso funciona. Preciso ser engraçado? Não — interesse e simpatia valem mais que piadas."]),
    section("Continue praticando", ["Small talk combina sua apresentação, suas perguntas e sua escuta. Pratique começar conversas nas aulas do curso e tenha pronta a sua apresentação para os primeiros segundos."], undefined, undefined, [{label:"Como se apresentar em inglês",url:"/blog/frases-para-se-apresentar-em-ingles"},{label:"Como fazer perguntas em inglês",url:"/blog/como-fazer-perguntas-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("pedir-para-repetir-em-ingles", "Conversação", "Como pedir para repetir ou falar mais devagar em inglês", "Frases educadas em inglês para pedir repetição, falar mais devagar, esclarecer uma palavra ou confirmar o que entendeu — sem fingir que compreendeu.", "↻", ["pedir para repetir inglês", "fale mais devagar inglês", "could you repeat that", "não entendi em inglês", "como pedir esclarecimento inglês", "sorry pardon diferença"], "Uma das habilidades mais subestimadas de quem fala inglês não é saber muitas palavras — é saber o que dizer quando não entende. Fingir que compreendeu leva a mal-entendidos; pedir esclarecimento, de forma educada, mantém a conversa fluindo e mostra interesse. Falantes experientes pedem repetição o tempo todo, inclusive na própria língua. Neste guia você aprende frases para repetir, desacelerar, esclarecer e confirmar — curtas e educadas.", [
    section("Peça para repetir", ["A frase mais útil é Sorry, could you repeat that? Para versões curtas, Sorry? e Pardon? funcionam (Pardon soa um pouco mais formal). Evite só um What? seco, que pode soar brusco.", "Acrescentar sorry no começo deixa qualquer pedido mais educado."], ["Sorry, could you repeat that? — Desculpe, poderia repetir?", "Sorry? / Pardon? — Como? / Perdão?", "I didn’t catch that. — Não peguei isso.", "Could you say that again, please? — Poderia dizer de novo?"]),
    section("Peça para falar mais devagar", ["Se a pessoa fala rápido, peça para desacelerar — é comum e ninguém se ofende. Could you speak more slowly? resolve. Você também pode explicar o motivo: I’m still learning English.", "Dizer que está aprendendo costuma deixar o outro mais paciente e claro."], ["Could you speak a little more slowly, please? — Poderia falar um pouco mais devagar?", "I’m still learning English, so please speak slowly. — Ainda estou aprendendo; fale devagar, por favor.", "That was a bit fast for me. — Foi um pouco rápido para mim."]),
    section("Esclareça uma palavra específica", ["Às vezes você entendeu quase tudo, menos uma palavra. Em vez de pedir a frase toda de novo, aponte o que faltou: What does ‘…’ mean? ou peça que soletrem ou escrevam.", "Isso é mais eficiente e mostra que você acompanhou o resto."], ["What does ‘receipt’ mean? — O que significa ‘receipt’?", "Sorry, what do you mean by that? — Desculpe, como assim?", "Could you spell that? — Poderia soletrar?", "Could you write it down? — Poderia anotar?"]),
    section("Confirme o que você entendeu", ["Uma técnica poderosa é repetir com suas palavras para confirmar (paraphrasing). Assim você checa o entendimento e dá à pessoa a chance de corrigir. Use So, you mean…? ou Let me check…", "Isso é ainda mais importante com números, horários, datas e endereços."], ["So, you mean the meeting is at three? — Então a reunião é às três?", "Let me check — platform 4, right? — Deixe-me confirmar — plataforma 4, certo?", "Just to be sure: you said Friday? — Só para confirmar: você disse sexta?"]),
    section("Mantenha o tom educado e leve", ["Pedir esclarecimento não é sinal de fraqueza — é parte normal da comunicação. Um sorry no início, um please no fim e um sorriso (mesmo ao telefone, pela voz) fazem toda a diferença. Não peça desculpas em excesso; um pedido claro basta.", "Lembre: é melhor pedir para repetir três vezes do que sair com a informação errada."]),
    section("Perguntas frequentes", ["Qual a diferença de ‘Sorry?’ e ‘Pardon?’ Ambos pedem repetição; Pardon soa um pouco mais formal. ‘What?’ é rude? Sozinho e seco pode soar; prefira Sorry? Posso pedir para escrever? Sim — Could you write it down? é ótimo para nomes e números. Pedir muito para repetir é ruim? Não — é melhor que entender errado."]),
    section("Continue praticando", ["Saber pedir esclarecimento destrava conversas reais e tira o medo de falar. Pratique nas aulas do curso e combine com o guia de como perder o medo de falar e com as situações de telefone, onde essas frases são essenciais."], undefined, undefined, [{label:"Como perder o medo de falar inglês",url:"/blog/perder-medo-de-falar-ingles"},{label:"Marcar um horário por telefone",url:"/blog/marcar-consulta-por-telefone-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("entrevista-emprego-ingles", "Inglês para trabalho", "Como se preparar para uma entrevista de emprego em inglês", "Prepare-se para uma entrevista em inglês: apresentação, perguntas clássicas (pontos fortes e fracos), respostas com exemplos pelo método STAR e perguntas para fazer ao entrevistador.", "CV", ["entrevista emprego inglês", "job interview answers", "perguntas entrevista inglês", "como se preparar entrevista inglês", "método STAR entrevista", "tell me about yourself resposta"], "Uma entrevista de emprego em inglês junta dois desafios: a pressão da entrevista em si e o idioma. A boa notícia é que as perguntas são bastante previsíveis e se repetem entre empresas e países. Com respostas preparadas (mas não decoradas palavra por palavra), exemplos reais e algumas estruturas prontas, você entra muito mais confiante. Neste guia você vê como responder às perguntas clássicas, o método STAR para exemplos e o que perguntar no final.", [
    section("Prepare a sua apresentação (Tell me about yourself)", ["Quase toda entrevista começa com Tell me about yourself. Não conte sua vida: faça um resumo de 30–60 segundos ligando sua experiência ao cargo — presente, um pouco do passado relevante e o que busca agora.", "Prepare e pratique esse bloco em voz alta; ele dá o tom da entrevista e acalma o início."], ["I’m a customer support specialist with three years of experience. — Sou especialista em atendimento com três anos de experiência.", "Currently, I work at…, where I handle… — Atualmente trabalho na…, onde cuido de…", "I’m looking for a role where I can… — Busco uma função em que eu possa…"]),
    section("Perguntas clássicas e como respondê-las", ["Prepare-se para as recorrentes: pontos fortes e fracos, por que quer a vaga, por que saiu do emprego anterior. Para fraquezas, cite algo real e o que faz para melhorar — nunca ‘não tenho defeitos’.", "Mantenha o tom positivo e foque no que é relevante para a função."], ["My greatest strength is… — Meu maior ponto forte é…", "One area I’m working on is… — Um ponto que estou desenvolvendo é…", "I’m interested in this role because… — Tenho interesse nesta vaga porque…", "I’m looking for a new challenge. — Estou em busca de um novo desafio."]),
    section("Responda com exemplos: o método STAR", ["Para perguntas de comportamento (Tell me about a time when…), use STAR: Situation (situação), Task (o que precisava fazer), Action (o que você fez) e Result (o resultado). Isso dá respostas concretas e organizadas, em vez de frases vagas.", "Use dados verdadeiros — nunca invente experiência ou números para impressionar."], ["Situation: In my last role, we had a delay… — Na minha função anterior, tivemos um atraso…", "Action: I reorganized the schedule and… — Reorganizei o cronograma e…", "Result: As a result, we delivered on time. — Como resultado, entregamos no prazo."]),
    section("Vocabulário e frases úteis", ["Algumas expressões soam naturais e profissionais em entrevistas. Vale tê-las prontas para falar de experiência, responsabilidades e conquistas.", "Prefira verbos de ação no passado para descrever o que você fez: managed, led, improved, created."], undefined, ["I’m responsible for… — Sou responsável por…", "I have experience in… — Tenho experiência em…", "I improved / managed / led… — Eu melhorei / gerenciei / liderei…", "I’m a team player. — Trabalho bem em equipe."]),
    section("Faça perguntas ao entrevistador", ["No fim, quase sempre perguntam Do you have any questions? Dizer que não pode passar desinteresse. Prepare duas ou três perguntas sobre a função, a equipe, o dia a dia ou os próximos passos do processo.", "Boas perguntas mostram interesse e ajudam você a avaliar a vaga também."], ["What does a typical day look like? — Como é um dia típico?", "What are the next steps in the process? — Quais são os próximos passos do processo?", "How is the team structured? — Como a equipe é organizada?"]),
    section("Perguntas frequentes", ["Devo decorar as respostas? Não — prepare ideias e pratique, mas fale de forma natural. E se eu não entender uma pergunta? Peça para repetir: Could you repeat the question? Preciso de inglês perfeito? Não — clareza e exemplos concretos contam mais que perfeição. Como falo de defeitos? Cite um real e o que faz para melhorar."]),
    section("Continue praticando", ["Entrevistas se treinam ensaiando respostas em voz alta. Pratique nas aulas do curso e combine com os guias de reuniões de trabalho e de perder o medo de falar para ganhar confiança oral."], undefined, undefined, [{label:"Frases para reuniões de trabalho",url:"/blog/ingles-para-reunioes-trabalho"},{label:"Como perder o medo de falar inglês",url:"/blog/perder-medo-de-falar-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("ingles-para-reunioes-trabalho", "Inglês para trabalho", "Frases em inglês para participar de reuniões de trabalho", "Frases prontas em inglês para reuniões: abrir e conduzir, pedir a palavra, concordar e discordar com educação, pedir esclarecimento e resumir ações e próximos passos.", "◎", ["inglês reuniões trabalho", "frases reunião inglês", "meeting phrases", "inglês para call de trabalho", "como participar reunião inglês", "frases para videoconferência inglês"], "Participar de uma reunião em inglês — ainda mais por videochamada — é um dos momentos em que muita gente trava: você quer contribuir, mas não sabe como entrar na conversa sem soar rude, nem como discordar com educação. A boa notícia é que reuniões usam um repertório bem definido de frases. Com elas prontas, você pede a palavra, dá sua opinião, concorda, discorda e confirma o combinado com naturalidade. Neste guia você encontra esse kit de frases.", [
    section("Abrir e conduzir a reunião", ["Se você conduz, algumas frases ajudam a começar, apresentar a pauta e passar a palavra. Isso organiza a conversa e mostra domínio.", "Mesmo participando, é útil reconhecê-las para acompanhar o fluxo."], ["Thanks, everyone, for joining. — Obrigado a todos por participar.", "Let’s get started. — Vamos começar.", "Today we’ll talk about… — Hoje vamos falar sobre…", "Let’s move on to the next point. — Vamos ao próximo ponto."]),
    section("Pedir a palavra e dar opinião", ["Para entrar na conversa sem interromper de forma brusca, use uma frase de introdução. Could I add something? ou Can I jump in? abrem espaço com educação. Para opinar, I think…, In my opinion…, From my point of view…", "Numa call, é comum avisar antes de falar, já que não há a linguagem corporal de uma sala."], ["Could I add something here? — Posso acrescentar uma coisa aqui?", "Can I jump in for a second? — Posso entrar rapidinho?", "In my opinion, we should… — Na minha opinião, deveríamos…", "I’d like to point out that… — Eu gostaria de destacar que…"]),
    section("Concordar e discordar com educação", ["Concordar é fácil (I agree, That’s a good point). Discordar exige mais tato: suavize com uma concordância parcial antes do ‘mas’. I see your point, but… soa muito melhor que um You’re wrong.", "Em inglês profissional, a discordância direta demais pode soar agressiva; o tom indireto é valorizado."], ["I completely agree. — Concordo totalmente.", "That’s a good point. — É um bom argumento.", "I see your point, but… — Entendo o seu ponto, mas…", "I’m not sure I agree with that. — Não sei se concordo com isso."]),
    section("Pedir esclarecimento", ["Se uma sigla, um prazo ou uma decisão não ficou clara, pergunte — é mais seguro do que assumir e executar algo errado. Numa reunião, isso é visto como atenção, não como falha.", "Pedir para repetir é especialmente importante em calls com áudio ruim."], ["Sorry, could you clarify that? — Desculpe, poderia esclarecer?", "What do you mean by…? — O que você quer dizer com…?", "Could you repeat the deadline? — Poderia repetir o prazo?", "Just to make sure I understand… — Só para ter certeza de que entendi…"]),
    section("Resumir e confirmar os próximos passos", ["No fim, repita quem faz o quê e até quando (action items). Isso reduz ambiguidades e deixa todos alinhados. Use So, to summarize… e atribua tarefas com nomes e prazos.", "Confirmar o combinado em voz alta evita o clássico ‘eu achei que era você que ia fazer’."], ["So, to summarize… — Então, resumindo…", "I’ll send the draft by Thursday. — Envio o rascunho até quinta.", "Who’s taking care of this? — Quem fica responsável por isto?", "Let’s follow up next week. — Vamos retomar na semana que vem."]),
    section("Perguntas frequentes", ["Como entro na conversa sem interromper? Com Could I add something? ou Can I jump in? Como discordo sem ser rude? Comece concordando em parte: I see your point, but… E se eu não entender numa call? Peça para repetir: Sorry, could you repeat that? Preciso falar muito? Não — contribuições curtas e claras já têm valor."]),
    section("Continue praticando", ["As frases de reunião entram no automático com uso. Pratique nas aulas do curso e combine com os guias de entrevista de emprego e de pedir para repetir, úteis no ambiente profissional."], undefined, undefined, [{label:"Como se preparar para uma entrevista em inglês",url:"/blog/entrevista-emprego-ingles"},{label:"Como pedir para repetir em inglês",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("mensagens-curtas-em-ingles", "Writing", "Como escrever mensagens curtas em inglês com clareza", "Aprenda a escrever mensagens curtas e claras em inglês para trabalho e dia a dia: dizer o objetivo, dar os detalhes, ajustar o tom e usar (com cuidado) abreviações comuns.", "✉", ["mensagens curtas inglês", "escrever mensagem inglês", "text message english", "como escrever mensagem em inglês", "abreviações inglês chat", "mensagem profissional inglês"], "Mensagens — de WhatsApp, chat de trabalho, SMS — são o tipo de texto que mais escrevemos hoje, e em inglês elas têm suas próprias convenções: diretas, com o objetivo logo no início e um tom que varia muito conforme o destinatário. Uma boa mensagem é clara e fácil de responder. Neste guia você aprende a estruturar uma mensagem curta, a ajustar a formalidade e a usar (ou evitar) as abreviações e emojis que povoam o inglês informal.", [
    section("Comece pelo objetivo", ["Mensagens curtas valorizam a clareza: diga logo o que você quer. Em vez de rodeios, abra com o pedido, a informação ou a pergunta. Quem recebe entende na hora o que fazer.", "Mensagens vagas (‘oi, tudo bem?’ e nada mais) travam a conversa quando você precisa de algo específico."], ["Hi! Could you send me the file today? — Oi! Poderia me enviar o arquivo hoje?", "Quick question: what time is the call? — Pergunta rápida: que horas é a call?", "I’m running 10 minutes late. — Vou me atrasar 10 minutos."]),
    section("Dê os detalhes necessários", ["Inclua o que a pessoa precisa para responder sem ter que perguntar de volta: data, horário, link, nome. Uma mensagem completa economiza idas e vindas.", "Se há vários pontos, uma lista curta ou frases separadas ajudam a leitura."], ["Can we meet on Tuesday at 3? — Podemos nos encontrar terça às 3?", "Here’s the link: … Let me know if it works. — Segue o link: … Me avise se funciona.", "I’ll be there around 7. — Chego por volta das 7."]),
    section("Ajuste o tom ao destinatário", ["O grau de formalidade muda tudo. Para amigos, contrações, abreviações e emojis são naturais. Para o chefe ou um cliente, prefira frases completas, educação e menos (ou nenhum) emoji. Na dúvida, seja um pouco mais formal.", "Um pedido educado (Could you…?, please, thanks) funciona bem em quase todo contexto profissional."], ["Informal: Hey, can you call me later? 🙂 — Ei, me liga depois?", "Neutro: Hi, could you call me when you have a minute? — Oi, poderia me ligar quando tiver um minuto?", "Formal: Could you please give me a call today? Thank you. — Poderia me ligar hoje? Obrigado."]),
    section("Abreviações comuns (e quando evitá-las)", ["O inglês de mensagens tem abreviações que vale reconhecer, mesmo que você não as use. Em contexto profissional ou com quem você não conhece, escreva por extenso — muitas abreviações soam informais demais.", "Reconhecer é útil para entender o que recebe; usar, só quando o tom permite."], undefined, ["ASAP — as soon as possible (o quanto antes)", "FYI — for your information (para a sua informação)", "BTW — by the way (a propósito)", "thx / pls — thanks / please (bem informais)", "LMK — let me know (me avise)"]),
    section("Revise antes de enviar", ["Mesmo numa mensagem curta, uma conferência rápida evita problemas: destinatário certo, data e horário corretos, anexo ou link incluído. Em combinações de reunião entre fusos diferentes, informe o fuso (3 p.m. BRT).", "Para o trabalho, reler uma vez antes de enviar é um hábito que evita retrabalho e mal-entendidos."]),
    section("Perguntas frequentes", ["Posso usar emojis no trabalho? Com colegas próximos, talvez; com chefia e clientes, com parcimônia ou nenhum. Preciso cumprimentar sempre? Um Hi + nome é cordial; em chats rápidos, nem sempre é necessário. Abreviações como ASAP são rudes? Dependem do tom; por extenso é mais seguro no formal. Como marco horário entre países? Inclua o fuso (ex.: 3 p.m. BRT)."]),
    section("Continue praticando", ["Mensagens claras são um ótimo exercício de escrita objetiva. Pratique nas aulas do curso e combine com os guias de e-mail e de conectores para textos um pouco mais longos."], undefined, undefined, [{label:"Como escrever um e-mail em inglês",url:"/blog/email-simples-em-ingles"},{label:"Conectores para ligar ideias",url:"/blog/conectores-para-escrever-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "7 min"),
  article("como-escrever-paragrafo-ingles", "Writing", "Como organizar um parágrafo em inglês", "Aprenda a estruturar um parágrafo claro em inglês: frase-tópico, frases de apoio com exemplos, uso de conectores e uma revisão final de unidade e coerência.", "¶", ["escrever parágrafo inglês", "paragraph writing", "organizar texto inglês", "como escrever parágrafo em inglês", "topic sentence", "estrutura de parágrafo inglês"], "Escrever bem em inglês começa no parágrafo — a unidade básica de qualquer texto, de um e-mail a uma redação de exame. Um bom parágrafo não é um amontoado de frases: ele tem uma ideia central e tudo gira em torno dela. A estrutura clássica (frase-tópico, apoio e fechamento) é uma ferramenta que organiza o pensamento e deixa o texto fácil de seguir. Neste guia você aprende essa estrutura, como usar conectores e como revisar a coerência.", [
    section("A estrutura clássica do parágrafo", ["Um parágrafo bem organizado costuma ter três partes: uma frase-tópico (topic sentence) que apresenta a ideia central, algumas frases de apoio (supporting sentences) que explicam ou exemplificam, e às vezes uma frase de fechamento. Tudo deve se referir à mesma ideia.", "Essa estrutura é uma ferramenta útil para textos expositivos e de exame — não uma regra rígida para todo gênero (uma narrativa, por exemplo, pode fugir dela)."], undefined, ["Topic sentence — a ideia central do parágrafo", "Supporting sentences — explicações, razões, exemplos", "Closing sentence — fechamento ou ligação (opcional)"]),
    section("Comece pela frase-tópico", ["A primeira frase costuma anunciar o assunto do parágrafo. Ela dá ao leitor uma expectativa clara e mantém você focado. Evite abrir vários temas de uma vez sem mostrar a relação entre eles.", "Uma boa frase-tópico é específica o bastante para ser desenvolvida em poucas frases."], ["Learning a language takes regular practice. — Aprender uma língua exige prática regular.", "There are several ways to improve your listening. — Há várias formas de melhorar o listening."]),
    section("Desenvolva com apoio e exemplos", ["Depois da ideia central, sustente-a: dê uma razão, um detalhe, dados ou um exemplo concreto. Exemplos tornam a ideia tangível e convincente. Conectores como for example e for instance introduzem ilustrações.", "Cada frase de apoio deve reforçar a frase-tópico — não puxar para um assunto novo."], ["For example, listening to a short dialogue every day builds the habit. — Por exemplo, ouvir um diálogo curto todo dia cria o hábito.", "This is because the brain needs repetition to remember. — Isso porque o cérebro precisa de repetição para lembrar."]),
    section("Use conectores para ligar as ideias", ["Conectores (linking words) mostram a relação entre as frases: adição (also, in addition), contraste (however, but), causa e resultado (because, so), sequência (first, then, finally). Eles guiam o leitor pelo raciocínio.", "Use-os pelo sentido, não para enfeitar: um conector errado confunde mais do que ajuda."], ["In addition, reading helps expand vocabulary. — Além disso, ler ajuda a ampliar o vocabulário.", "However, speaking requires a different kind of practice. — No entanto, falar exige outro tipo de prática.", "First… then… finally… — Primeiro… depois… por fim…"]),
    section("Revise unidade e coerência", ["Ao terminar, cheque três coisas: unidade (todas as frases falam da mesma ideia?), coerência (a ordem faz sentido e os conectores ligam bem?) e clareza (os pronomes têm referentes claros?). Corte o que fugir do tema.", "Ler o parágrafo em voz alta ajuda a perceber frases desconexas ou longas demais."]),
    section("Perguntas frequentes", ["A frase-tópico precisa ser a primeira? Normalmente sim, mas pode vir depois em alguns estilos. Quantas frases tem um parágrafo? Não há número fixo; o suficiente para desenvolver uma ideia. Posso ter uma ideia por parágrafo só? Sim — é justamente o ideal. Essa estrutura vale para redação de exame? Sim, é muito valorizada em provas como IELTS e TOEFL."]),
    section("Continue praticando", ["Dominar o parágrafo é a base para textos maiores, como e-mails e redações. Pratique nas aulas do curso e combine com os guias de conectores e de e-mail para escrever com mais estrutura."], undefined, undefined, [{label:"Conectores para ligar ideias",url:"/blog/conectores-para-escrever-ingles"},{label:"Como escrever um e-mail em inglês",url:"/blog/email-simples-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("niveis-cefr-ingles-a1-c2", "Níveis e exames", "Níveis de inglês A1, A2, B1, B2, C1 e C2: o que significa cada um?", "Entenda a escala CEFR do A1 ao C2: o que você consegue fazer em cada nível, quanto tempo leva para avançar e como descobrir o seu ponto de partida.", "CEFR", ["CEFR níveis inglês", "A1 A2 B1 B2 C1 C2", "nível de inglês", "o que significa A1 A2 B1 B2", "níveis de inglês CEFR", "qual meu nível de inglês"], "Quando alguém diz que tem ‘inglês nível B2’ ou está ‘no A2’, está usando o CEFR — o Quadro Europeu Comum de Referência para Línguas. É a escala mais usada no mundo para descrever o que alguém consegue fazer em um idioma, dividida em seis níveis, do A1 (iniciante) ao C2 (domínio). Entender essa escala ajuda a escolher cursos, materiais e exames no ponto certo. Neste guia você vê o que caracteriza cada nível e como identificar o seu.", [
    section("Como a escala CEFR é organizada", ["O CEFR agrupa a proficiência em três faixas, cada uma com dois níveis: usuário básico (A1 e A2), usuário independente (B1 e B2) e usuário proficiente (C1 e C2). Os descritores são do tipo ‘consegue fazer’ (can-do): descrevem tarefas reais, não regras de gramática.", "Importante: o CEFR é uma referência de habilidades, não um certificado automático. Um teste rápido sugere uma faixa; só um exame oficial comprova um nível."], undefined, ["A1–A2 → usuário básico", "B1–B2 → usuário independente", "C1–C2 → usuário proficiente"]),
    section("A1 e A2: usuário básico", ["No A1 (iniciante), você usa frases e expressões muito simples: se apresentar, dar informações básicas e interagir de forma elementar, desde que a outra pessoa fale devagar e ajude. É o nível de quem está começando.", "No A2 (básico), você já lida com tarefas rotineiras e previsíveis: fazer compras, falar da sua rotina, trocar informações simples sobre assuntos familiares. Entende mensagens curtas e diretas."], ["A1: Hi, I’m Ana. I’m from Brazil. — apresentação simples.", "A2: I usually work from nine to five. — falar da rotina."]),
    section("B1 e B2: usuário independente", ["No B1 (intermediário), você se vira na maioria das situações de viagem e do dia a dia, entende os pontos principais de uma fala clara sobre temas conhecidos e consegue narrar experiências e explicar planos. É o nível em que muita gente começa a ‘destravar’.", "No B2 (intermediário superior), você acompanha textos e discussões mais complexos, interage com naturalidade com falantes nativos e defende um ponto de vista com detalhes. É o nível frequentemente pedido por universidades e empregos."], ["B1: I think the film was good, but a bit long. — dar opinião simples.", "B2: I’d argue that remote work has clear advantages and drawbacks. — argumentar."]),
    section("C1 e C2: usuário proficiente", ["No C1 (avançado), você usa a língua de forma flexível e eficaz em contextos sociais, acadêmicos e profissionais, entende textos longos e exigentes e se expressa com fluidez, sem procurar muito as palavras.", "No C2 (domínio), você compreende praticamente tudo o que lê e ouve, e se expressa com grande precisão, inclusive em situações complexas. C2 não significa ‘ser nativo’ nem perfeição absoluta em tudo — é o topo da escala de proficiência prática."], ["C1: a nuance between ‘imply’ and ‘infer’ — distinções sutis.", "C2: entender ironia, registro e detalhes culturais com facilidade."]),
    section("Quanto tempo leva para avançar de nível", ["Não há um número exato — depende de quantas horas por semana você estuda, da qualidade da prática e da sua exposição à língua. Como referência muito geral, estima-se que cada nível do CEFR exija algumas centenas de horas de estudo acumulado, e que os níveis mais altos levem mais tempo que os iniciais.", "Mais útil que cronometrar é observar o que você já consegue fazer. Se as tarefas de um nível ficaram fáceis, é hora de subir; se parecem difíceis demais, vale reforçar o nível anterior."]),
    section("Como descobrir o seu nível", ["O jeito mais rápido é fazer um teste de nível orientativo, que indica uma faixa de partida com base no que você reconhece. Lembre que é uma orientação, não uma certificação — para comprovar o nível (em universidade, emprego ou visto), é preciso um exame oficial como Cambridge, IELTS, TOEFL ou TOEIC.", "Com o seu nível em mãos, você escolhe aulas, leituras e simulados no ponto certo — nem fáceis demais, nem frustrantes."]),
    section("Perguntas frequentes", ["Qual nível preciso para trabalhar/estudar fora? Varia por instituição, mas B2 costuma ser um corte comum. C2 é ser fluente/nativo? Não — é o topo da proficiência prática, sem exigir perfeição. O teste de nível vale como certificado? Não; é orientativo. Em quanto tempo chego ao B2? Depende do estudo e da exposição; pense em progresso, não em prazo fixo."]),
    section("Continue praticando", ["Saber o seu nível é o primeiro passo para estudar com eficiência. Faça o teste orientativo, comece pelas aulas da sua faixa e, se precisar de certificado, veja qual exame combina com o seu objetivo."], undefined, undefined, [{label:"Faça o teste de nível grátis",url:"/diagnostico"},{label:"Comece pelas aulas de inglês A1–C2",url:"/curso"},{label:"A1 e A2: o que muda entre os iniciantes",url:"/blog/diferenca-entre-a1-e-a2-ingles"},{label:"Qual certificado de inglês fazer",url:"/blog/como-escolher-exame-certificacao-ingles"}]),
  ], "9 min"),
  article("diferenca-entre-a1-e-a2-ingles", "Níveis e exames", "A1 ou A2 em inglês: o que muda entre os níveis iniciantes?", "Entenda a diferença entre os níveis A1 e A2 do CEFR: o que você consegue fazer em cada um, que gramática e vocabulário cada nível cobre e como saber em qual você está.", "A1/A2", ["diferença A1 A2 inglês", "nível iniciante inglês", "CEFR A1 A2", "o que é nível A1 A2", "sou A1 ou A2", "inglês básico A1 A2"], "A1 e A2 são os dois níveis do inglês básico na escala CEFR — a fase em que você constrói a fundação do idioma. A diferença entre eles é de autonomia: no A1 você se comunica de forma muito elementar, sempre com apoio; no A2 já se vira sozinho em situações rotineiras e previsíveis. Saber em qual você está ajuda a escolher aulas e materiais no ponto certo. Neste guia você vê o que caracteriza cada nível e como distingui-los.", [
    section("A1: o primeiro contato com o idioma", ["No A1 (iniciante), você usa frases e expressões muito simples para necessidades imediatas: cumprimentar, se apresentar, dar informações pessoais básicas e fazer perguntas elementares. Você entende e se faz entender desde que a outra pessoa fale devagar, de forma clara e ajude.", "É o nível de quem está começando praticamente do zero, construindo as primeiras estruturas."], ["Hi, I’m Ana. I’m from Brazil. — apresentação básica.", "Where is the bathroom? — pergunta elementar.", "I have two brothers. — informação pessoal simples."]),
    section("A2: autonomia em situações do dia a dia", ["No A2 (básico), você já lida com tarefas rotineiras e previsíveis que exigem uma troca simples de informações: fazer compras, falar da sua rotina, descrever sua família e seu trabalho, entender avisos e mensagens curtas. Você consegue conversar sobre assuntos familiares, ainda que de forma simples.", "A diferença-chave é a autonomia: no A2 você depende menos de ajuda e consegue resolver situações comuns por conta própria."], ["I usually start work at nine and finish at six. — falar da rotina.", "How much is this? Do you have a smaller size? — resolver uma compra.", "Last weekend, I visited my family. — contar algo simples do passado."]),
    section("O que muda em gramática e vocabulário", ["Em termos de conteúdo, o A1 costuma cobrir o verbo to be, o presente simples, artigos, plurais, números, pronomes e vocabulário básico (família, cores, comida, rotina). O A2 amplia para o passado simples, o futuro com going to, comparativos, advérbios de frequência e mais vocabulário do cotidiano.", "São referências gerais — o importante é o que você consegue fazer, não ter decorado uma lista exata de tópicos."], undefined, ["A1: to be, presente simples, artigos, plurais, números", "A2: passado simples, going to, comparativos, mais vocabulário do dia a dia"]),
    section("Compare tarefas, não só gramática", ["O CEFR descreve o que você consegue fazer, não quantas regras você sabe. Para se situar, pergunte-se: consigo só me apresentar e dar informações básicas com ajuda (A1)? Ou já consigo falar da minha rotina, fazer compras e entender mensagens simples sozinho (A2)?", "Seu nível pode variar entre habilidades — talvez você entenda (listening) num nível e fale (speaking) em outro. Isso é normal."]),
    section("Como saber em qual nível você está", ["A forma mais rápida é fazer um teste de nível orientativo, que sugere uma faixa com base no que você reconhece. Lembre que é uma orientação para escolher por onde começar, não uma certificação.", "Com o resultado, comece pelas aulas da sua faixa: nem fáceis demais (que entediam), nem difíceis demais (que frustram)."]),
    section("Perguntas frequentes", ["Quanto tempo leva para ir de A1 a A2? Depende do estudo e da exposição; pense em progresso, não em prazo fixo. A2 já é ‘bom’? É uma base sólida do cotidiano, mas ainda básico — para trabalho ou estudo, costuma-se pedir B1/B2. Posso pular o A1? Se você já se vira sozinho em situações rotineiras, provavelmente já está no A2 — o teste ajuda a confirmar."]),
    section("Continue praticando", ["A1 e A2 são a base de tudo. Descubra seu nível, comece pelas aulas certas e, quando dominar o básico, veja o que muda nos níveis intermediários B1 e B2."], undefined, undefined, [{label:"Faça o teste de nível grátis",url:"/diagnostico"},{label:"Comece pelas aulas de inglês A1–C2",url:"/curso"},{label:"Entenda todos os níveis do CEFR",url:"/blog/niveis-cefr-ingles-a1-c2"},{label:"Em seguida: a diferença entre B1 e B2",url:"/blog/diferenca-entre-b1-e-b2-ingles"}]),
  ], "8 min"),
  article("diferenca-entre-b1-e-b2-ingles", "Níveis e exames", "B1 ou B2 em inglês: como distinguir os níveis intermediários?", "Entenda a diferença entre B1 e B2 no CEFR: o que você consegue fazer em cada nível, por que o B2 é tão pedido por universidades e empregos e como saber onde você está.", "B1/B2", ["diferença B1 B2 inglês", "nível intermediário CEFR", "B1 vs B2", "o que é nível B1 B2", "sou B1 ou B2", "nível B2 para que serve"], "B1 e B2 são os dois níveis do usuário independente no CEFR — a fase em que o inglês deixa de ser só ‘sobrevivência’ e vira uma ferramenta real de comunicação. A diferença entre eles é grande na prática: o B1 (intermediário) resolve o essencial em temas familiares; o B2 (intermediário superior) permite interagir com naturalidade, acompanhar discussões complexas e argumentar. Por isso o B2 é tão pedido por universidades e empregos. Neste guia você vê o que separa os dois.", [
    section("B1: comunicar-se com independência básica", ["No B1, você entende os pontos principais de uma fala clara sobre temas conhecidos (trabalho, escola, lazer), se vira na maioria das situações de viagem, e consegue narrar experiências, descrever sonhos e planos e dar opiniões simples com justificativas curtas.", "É o nível em que muita gente sente que ‘finalmente destravou’: você já sustenta uma conversa sobre o que conhece, mesmo com limitações."], ["I think the film was good because the story was original. — opinião com justificativa.", "Last year I traveled to Chile and visited the mountains. — narrar experiência.", "I’d like to improve my English to get a better job. — falar de planos."]),
    section("B2: interação ampla e espontânea", ["No B2, o salto é notável. Você acompanha textos e discussões mais complexos, inclusive sobre temas abstratos, interage com falantes nativos com espontaneidade (sem esforço visível dos dois lados) e defende um ponto de vista com argumentos detalhados, pesando prós e contras.", "A fluência aumenta: você hesita menos, usa uma gama maior de estruturas e entende nuances que passariam despercebidas no B1."], ["I’d argue that remote work increases flexibility, although it can blur boundaries. — argumentar com nuance.", "On the one hand… on the other hand… — estruturar um argumento.", "entender debates, podcasts e séries sobre temas variados com mais conforto."]),
    section("Por que o B2 é um marco importante", ["O B2 costuma ser o corte pedido por muitas universidades, programas e empregos que exigem inglês. A razão é prática: no B2, a pessoa consegue estudar, trabalhar e se comunicar em inglês de forma autônoma, sem precisar que tudo seja simplificado para ela.", "Por isso, chegar ao B2 é um objetivo comum de quem estuda com um fim profissional ou acadêmico — e é o nível de exames como o B2 First da Cambridge."]),
    section("O que muda em habilidades e vocabulário", ["Do B1 para o B2, a compreensão deixa de depender de fala pausada e passa a lidar com ritmo natural e sotaques variados. O vocabulário cresce e fica mais preciso, incluindo expressões idiomáticas e linguagem mais formal. Na escrita e na fala, você organiza textos mais longos, com conectores e argumentação.", "Resumindo: do B1 (lidar com o familiar) para o B2 (lidar com o complexo e o abstrato), muda a amplitude e a precisão."]),
    section("Como saber em qual nível você está", ["Pergunte-se: eu me comunico bem sobre temas conhecidos, mas travo quando o assunto fica abstrato ou a fala acelera (B1)? Ou já acompanho discussões complexas e argumento com certa naturalidade (B2)? Um teste de nível orientativo ajuda a situar seu ponto de partida.", "Lembre que o nível pode variar por habilidade — e que só um exame oficial comprova o B1 ou o B2 para fins formais."]),
    section("Perguntas frequentes", ["B2 é fluente? É um nível avançado de uso independente, mas ainda não é o topo (C1/C2); muita gente já se considera funcional em inglês no B2. Quanto tempo de B1 a B2? Varia bastante; é um dos saltos que mais exige exposição e prática. Que exame comprova o B2? Cambridge B2 First, além de IELTS, TOEFL e TOEIC com as notas correspondentes. Preciso de B2 para trabalhar fora? Muitas vagas pedem, mas depende do cargo e do país."]),
    section("Continue praticando", ["Sair do B1 para o B2 pede muita exposição e prática variada. Descubra seu nível, estude com material no ponto certo e, se o objetivo é comprovar o nível, veja qual exame combina com você."], undefined, undefined, [{label:"Faça o teste de nível grátis",url:"/diagnostico"},{label:"Entenda todos os níveis do CEFR",url:"/blog/niveis-cefr-ingles-a1-c2"},{label:"B2 First (FCE): para que serve",url:"/blog/cambridge-b2-first-como-funciona"},{label:"Treine com os simulados de inglês grátis",url:"/simulados"}]),
  ], "8 min"),
  article("gramatica-para-falar-ingles", "Speaking", "Preciso estudar gramática para falar inglês?", "Entenda o papel real da gramática na fala: por que você não precisa dominar tudo antes de falar, como aprender estruturas ligadas a tarefas e como equilibrar precisão e fluência.", "A↗", ["gramática para falar inglês", "precisa gramática inglês", "falar inglês erros", "gramática ou conversação", "quanto de gramática para falar inglês", "aprender inglês sem gramática"], "‘Preciso saber toda a gramática antes de falar?’ é uma das dúvidas que mais paralisam quem estuda inglês. A resposta curta é não — esperar dominar todas as regras é a receita para nunca começar. Mas a gramática também não é inimiga: um pouco de estrutura ajuda a organizar ideias e a ser entendido. O segredo é o equilíbrio e a ordem certa. Neste guia você vê qual é o papel real da gramática na fala e como estudá-la sem travar a conversa.", [
    section("A gramática é ferramenta, não pré-requisito", ["Você não precisa de gramática completa para se comunicar — crianças falam antes de aprender regras. Mas a gramática é uma ferramenta que acelera e organiza: saber formar o passado ou uma pergunta evita mal-entendidos. O erro é inverter a ordem, estudando regras por anos sem nunca falar.", "Pense na gramática a serviço da comunicação, não como um portão que você precisa atravessar antes de abrir a boca."]),
    section("Aprenda estruturas ligadas a tarefas", ["Em vez de estudar gramática ‘em geral’, aprenda a estrutura que você precisa para uma tarefa real. Quer se apresentar? Pratique o verbo to be e perguntas simples. Quer falar da rotina? Estude o simple present com horários. Assim a regra já nasce conectada ao uso.", "Esse foco torna o estudo mais leve e imediatamente útil na fala."], ["Para se apresentar: to be + perguntas (I’m…, Where are you from?)", "Para a rotina: simple present (I work, I usually…)", "Para o passado: simple past (I went, I saw)"]),
    section("Equilibre precisão e fluência", ["Há dois modos de praticar, e os dois têm valor. Na prática de precisão (accuracy), você foca em acertar uma estrutura, devagar. Na prática de fluência (fluency), você mantém a conversa sem parar a cada frase, aceitando pequenos erros. Alterne os dois: não tente ser perfeito e fluente ao mesmo tempo.", "Numa conversa real, priorize a fluência; guarde a correção fina para exercícios específicos."]),
    section("Priorize a gramática que afeta o sentido", ["Nem todo erro atrapalha. Esquecer um -s de terceira pessoa raramente impede a comunicação; já confundir tempos verbais ou a ordem da pergunta pode mudar o sentido. Concentre-se primeiro na gramática de alto impacto: tempos verbais básicos, perguntas, negativas.", "Deixar de lado o perfeccionismo com detalhes menores solta a fala e acelera o progresso."], undefined, ["Alto impacto: tempos verbais, perguntas, negativas, ordem das palavras", "Baixo impacto: um -s esquecido, um artigo trocado (não travam a mensagem)"]),
    section("Use os erros como bússola de estudo", ["Os seus erros mostram exatamente o que estudar a seguir. Se um erro se repete e atrapalha o entendimento, aí sim vale parar, revisar a regra e refazer a tarefa. Não interrompa toda conversa por cada pequeno deslize — anote o padrão e trabalhe depois.", "Esse ciclo (falar, notar o erro recorrente, revisar, falar de novo) ensina mais que decorar regras isoladas."]),
    section("Perguntas frequentes", ["Posso aprender a falar sem estudar gramática? Até certo ponto, mas um mínimo de estrutura ajuda muito. Quanta gramática preciso para começar? O básico de to be, presente e passado já destrava muita conversa. Errar gramática atrapalha? Só quando muda o sentido; pequenos erros não impedem a comunicação. Gramática ou conversação? Os dois — um pouco de estrutura aplicada à prática oral."]),
    section("Continue praticando", ["O melhor estudo de gramática é o que você aplica falando. Comece pelas estruturas básicas, pratique-as nas aulas do curso e combine com o guia de como perder o medo de falar."], undefined, undefined, [{label:"Como perder o medo de falar inglês",url:"/blog/perder-medo-de-falar-ingles"},{label:"Simple present ou present continuous",url:"/blog/simple-present-vs-present-continuous"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("second-conditional-situacoes-hipoteticas", "Gramática essencial", "Second conditional: como falar de situações hipotéticas em inglês", "Aprenda a formar o second conditional (if + passado, would + verbo) para imaginar situações hipotéticas ou improváveis, com o uso de were, a diferença para o first conditional e erros comuns.", "If…", ["second conditional inglês", "if would", "hipóteses inglês", "segunda condicional inglês", "if i were you", "second conditional exemplos"], "O second conditional é a estrutura dos ‘e se…’: serve para imaginar situações que não são reais agora — hipóteses, sonhos, conselhos e cenários improváveis. ‘Se eu ganhasse na loteria…’, ‘se eu fosse você…’. A fórmula usa o passado na condição e would no resultado, mas o sentido é presente ou futuro imaginário, não passado real. Neste guia você vê a estrutura, o caso especial de were e como não confundir com o first conditional.", [
    section("A fórmula do second conditional", ["A estrutura é: if + simple past (a condição imaginada), would + verbo base (o resultado hipotético). O passado aqui não fala de ontem — ele marca distância da realidade, a ideia de que a situação é imaginária ou pouco provável.", "Would costuma aparecer contraído como ’d: I’d, she’d, we’d."], ["If I had more time, I would learn another language. — Se eu tivesse mais tempo, aprenderia outra língua.", "If I won the lottery, I’d travel the world. — Se eu ganhasse na loteria, viajaria o mundo.", "She would help if she could. — Ela ajudaria se pudesse."], ["Condição: if + passado simples", "Resultado: would + verbo base"]),
    section("If I were: o caso especial", ["No second conditional, o verbo to be vira were para todos os sujeitos em inglês cuidadoso: If I were you, If he were here. Isso se chama subjuntivo. Na conversa informal, você também ouve was (If I was rich), mas were é a forma recomendada, sobretudo em provas.", "A expressão If I were you… é a forma mais comum de dar conselhos em inglês."], ["If I were you, I’d ask for help. — Se eu fosse você, pediria ajuda.", "If she were here, she’d know what to do. — Se ela estivesse aqui, saberia o que fazer.", "What would you do if you were in my place? — O que você faria no meu lugar?"]),
    section("Para que serve o second conditional", ["Além de hipóteses, ele é muito usado para dar conselhos (If I were you…), falar de desejos e sonhos, e ser mais educado em pedidos (Would it be possible…?). A chave é sempre a ideia de algo não real ou improvável no presente.", "Compare o resultado com could ou might para suavizar: If I had time, I could help (poderia); I might go (talvez fosse)."], ["If I knew her number, I’d call her. — Se eu soubesse o número dela, ligaria.", "If we had more money, we could buy a house. — Se tivéssemos mais dinheiro, poderíamos comprar uma casa."]),
    section("Second conditional x first conditional", ["Essa é a confusão mais comum. O first conditional fala de futuro real e provável: if + presente, will (If it rains, I’ll stay home — pode mesmo chover). O second fala de hipótese improvável ou irreal: if + passado, would (If it rained gold, I’d be rich — não vai acontecer).", "Pergunte-se: é algo que realmente pode acontecer (first) ou uma imaginação/improbabilidade (second)?"], ["First: If I have money, I’ll buy it. — é possível", "Second: If I had a million dollars, I’d buy it. — hipotético"]),
    section("Erros comuns com o second conditional", ["Os deslizes mais frequentes: usar would na oração com if (If I would have time ✗ → If I had time ✓); misturar com o first (If I had time, I will… ✗ → I would… ✓); e esquecer o were formal (If I was you, na escrita cuidadosa, → If I were you). Para fixar, complete frases sobre você: ‘If I could live anywhere, I’d…’, ‘If I were the boss, I’d…’.", "Mantenha a simetria: passado no if, would no resultado."], ["If I would have time, I’d read more. ✗ → If I had time, I’d read more. ✓", "If I had money, I will travel. ✗ → …I would travel. ✓"]),
    section("Perguntas frequentes", ["É ‘if I was’ ou ‘if I were’? Were é o recomendado; was aparece na fala informal. O passado significa que aconteceu? Não — marca que a situação é imaginária. Qual a diferença para o third conditional? O third fala de hipóteses no passado (if + past perfect, would have), já encerradas; o second fala do presente/futuro imaginário."]),
    section("Continue praticando", ["First e second conditional juntos cobrem a maior parte das situações com if. Revise o first se ainda não viu, e pratique os dois nas aulas do curso imaginando cenários e dando conselhos."], undefined, undefined, [{label:"Revise antes: o first conditional",url:"/blog/first-conditional-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("used-to-vs-simple-past", "Gramática essencial", "Used to: como falar de hábitos antigos em inglês", "Aprenda a usar used to para hábitos e estados do passado que mudaram, as formas negativa e interrogativa, a diferença para o simple past e para be used to, com erros comuns.", "↺", ["used to diferença simple past", "hábitos passado inglês", "used to exemplos", "used to be used to diferença", "didn't use to", "como usar used to"], "Used to é a forma favorita do inglês para falar de hábitos e situações que eram verdadeiros no passado, mas não são mais: ‘eu costumava…’, ‘eu morava…’, ‘antes eu…’. Ele carrega sempre a ideia de contraste com o presente. Parece simples, mas há dois pontos que confundem: a forma negativa e interrogativa (que perde o -d) e a diferença para a expressão parecida be used to. Neste guia você vê tudo com exemplos.", [
    section("O que used to expressa", ["Used to + verbo base fala de um hábito repetido ou de um estado permanente no passado que mudou. A frase sugere ‘antes sim, agora não’. Serve tanto para ações repetidas (used to play) quanto para estados (used to live, used to have).", "É diferente do português, que usa o imperfeito (‘eu morava’, ‘eu costumava’) — em inglês, used to deixa o contraste explícito."], ["I used to live in Recife. — Eu morava em Recife (agora não).", "She used to play tennis. — Ela costumava jogar tênis.", "There used to be a cinema here. — Antes havia um cinema aqui."]),
    section("Negativa e pergunta: atenção ao -d", ["Aqui mora o erro mais comum. Na negativa e na pergunta, usa-se did/didn’t + use to — sem o -d em use. Porque o did já marca o passado, used volta a use.", "Então: Did you use to…? e I didn’t use to… (não ‘didn’t used to’, na escrita cuidadosa)."], ["Did you use to walk to school? — Você costumava ir a pé para a escola?", "I didn’t use to like coffee. — Eu não costumava gostar de café.", "Did you used to…? ✗ → Did you use to…? ✓"]),
    section("Used to x simple past", ["O simple past conta o que aconteceu (uma vez ou várias), sem enfatizar mudança. Used to enfatiza que era um hábito ou estado que já acabou. Para um evento único no passado, use simple past, nunca used to.", "Compare: I used to go to the gym (hábito antigo, não vou mais) x I went to the gym yesterday (um evento). Com um período definido (for two years), prefira o simple past."], ["I used to play football. — Eu jogava futebol (hábito antigo).", "I played football yesterday. — Joguei futebol ontem (evento).", "I lived there for two years. — Morei lá por dois anos (período fechado)."]),
    section("Used to x be used to x get used to", ["Cuidado para não confundir três estruturas parecidas. Used to + verbo = hábito passado (I used to smoke). Be used to + -ing/substantivo = estar acostumado com algo (I’m used to waking up early). Get used to = acostumar-se, processo (I’m getting used to the new job).", "A diferença é enorme: a primeira fala do passado; as outras, de (estar/ficar) acostumado. Note o to seguido de -ing em be/get used to."], ["I used to drive. — Eu dirigia (antes).", "I’m used to driving. — Estou acostumado a dirigir.", "She’s getting used to the cold. — Ela está se acostumando com o frio."]),
    section("Would para hábitos antigos", ["Para hábitos repetidos no passado, would também pode ser usado, sobretudo em narrativas: When I was a child, we would visit my grandmother every summer. Mas would só serve para ações repetidas, não para estados — não se diz I would live there (→ I used to live there).", "Por segurança, used to funciona para ações e estados; would, só para ações."], ["Every summer, we would go to the beach. — Todo verão íamos à praia.", "I would ✗ para estados → I used to have a dog. ✓"]),
    section("Erros comuns com used to", ["Os deslizes mais frequentes: manter o -d na negativa/pergunta (didn’t used to ✗); confundir com be used to (I used to wake up early querendo dizer ‘estou acostumado’ ✗ → I’m used to waking up early); e usar used to para eventos únicos. Para fixar, liste três hábitos que você used to ter e já não tem, e uma coisa a que you’re used to hoje.", "Mantenha claro: used to = passado que mudou; be used to = acostumado."], ["I didn’t used to study. ✗ → I didn’t use to study. ✓", "I used to be tired every day (hoje). ✗ para ‘estou acostumado’ → I’m used to it. ✓"]),
    section("Perguntas frequentes", ["É ‘use to’ ou ‘used to’? Na afirmativa, used to; com did/didn’t, use to. Used to serve para o presente? Não — para hábitos presentes use usually (I usually wake up at seven). Qual a diferença de ‘I used to’ para ‘I’m used to’? A primeira é hábito passado; a segunda é estar acostumado."]),
    section("Continue praticando", ["Used to conecta diretamente com o simple past — vale ter os dois firmes. Pratique nas aulas do curso contando como era a sua vida antes e como é agora."], undefined, undefined, [{label:"Revise antes: o simple past",url:"/blog/simple-past-verbos-regulares-irregulares"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("perguntas-indiretas-educadas-ingles", "Gramática essencial", "Perguntas indiretas em inglês: como perguntar com mais educação", "Aprenda a transformar perguntas diretas em indiretas (Could you tell me…?) para soar mais educado, com a mudança de ordem, o uso de if/whether e os erros comuns.", "?", ["perguntas indiretas inglês", "perguntas educadas inglês", "could you tell me", "indirect questions inglês", "como perguntar educadamente inglês", "do you know where"], "Perguntar direto (Where is the station?) é correto, mas às vezes soa brusco — sobretudo com estranhos ou em situações formais. As perguntas indiretas resolvem isso: começam com uma introdução educada (Could you tell me…? / Do you know…?) e soam muito mais gentis. O segredo é uma mudança de estrutura que confunde quase todo estudante: dentro da pergunta indireta, a ordem volta a ser a de uma frase afirmativa. Neste guia você domina esse mecanismo.", [
    section("Por que e quando usar perguntas indiretas", ["Perguntas indiretas tornam o pedido mais suave e educado. São ótimas para falar com desconhecidos, pedir informação em lojas e aeroportos, ou em contextos formais. Em vez de disparar a pergunta, você a ‘embrulha’ em uma introdução gentil.", "O sentido é o mesmo; muda só o tom, que fica mais respeitoso."], ["Direta: Where is the station? — Onde fica a estação?", "Indireta: Could you tell me where the station is? — Você poderia me dizer onde fica a estação?"]),
    section("A mudança de ordem (o ponto-chave)", ["Numa pergunta direta com verbo auxiliar, há inversão (is the station, does it start). Dentro de uma pergunta indireta, essa inversão desaparece: a ordem volta a sujeito + verbo, como numa afirmação.", "Além disso, do/does/did somem na parte indireta, e o verbo volta à forma normal (com -s ou passado conforme o caso)."], ["Where is the station? → Could you tell me where the station is?", "What time does it start? → Do you know what time it starts?", "Where did she go? → Do you know where she went?"]),
    section("Introduções educadas mais comuns", ["Várias expressões servem para iniciar uma pergunta indireta. Com Could you tell me…? e Do you know…?, a frase toda ainda é uma pergunta a alguém, então termina com ponto de interrogação. Com I wonder… ou I’d like to know…, a frase é afirmativa e termina com ponto.", "Escolha a introdução pelo grau de formalidade desejado."], undefined, ["Could you tell me…? — Você poderia me dizer…?", "Do you know…? — Você sabe…?", "I wonder if… — Eu queria saber se…", "Would you mind telling me…? — Você se importaria de me dizer…?"]),
    section("Perguntas de sim/não: use if ou whether", ["Quando a pergunta direta é de sim/não (sem palavra interrogativa), a indireta precisa de if ou whether para ligar as orações. Is there a bank near here? vira Do you know if there is a bank near here?", "Sem o if/whether, a frase fica incompleta. Os dois são equivalentes; whether soa um pouco mais formal."], ["Is it open? → Do you know if it’s open?", "Did he call? → Could you tell me whether he called?", "Are we late? → I wonder if we’re late."]),
    section("Erros comuns com perguntas indiretas", ["O erro número um é manter a inversão dentro da parte indireta: Could you tell me where is the station? ✗. O certo é where the station is ✓. Outro deslize é manter do/does/did: Do you know where does she live? ✗ → where she lives ✓. E, em perguntas de sim/não, esquecer o if/whether.", "Para fixar, pegue cinco perguntas diretas e transforme em indiretas, prestando atenção à ordem e ao if."], ["Could you tell me where is the station? ✗ → …where the station is. ✓", "Do you know what does it mean? ✗ → …what it means. ✓", "Do you know is it open? ✗ → Do you know if it’s open? ✓"]),
    section("Perguntas frequentes", ["Perguntas indiretas são sempre mais formais? Soam mais educadas; servem bem com estranhos e em pedidos. Uso ponto ou interrogação? Se a introdução é uma pergunta (Could you tell me…?), interrogação; se é afirmação (I wonder…), ponto. Preciso sempre de if? Só nas perguntas de sim/não; nas com where, what, when etc., a palavra interrogativa já faz a ligação."]),
    section("Continue praticando", ["Perguntas indiretas combinam com as perguntas diretas — vale ter as duas firmes. Elas são muito úteis em viagens e situações práticas, como pedir direções ou informações no aeroporto."], undefined, undefined, [{label:"Revise antes: como fazer perguntas em inglês",url:"/blog/como-fazer-perguntas-em-ingles"},{label:"Como pedir e entender direções",url:"/blog/pedir-direcoes-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("adjetivos-ed-ing-diferenca", "Gramática essencial", "Adjetivos com -ed e -ing: bored ou boring? Qual a diferença?", "Entenda de uma vez a diferença entre adjetivos terminados em -ed e -ing (bored/boring, interested/interesting): quem sente a emoção e o que a provoca.", "ed/ing", ["bored boring diferença", "adjetivos ed ing", "interested interesting", "bored ou boring", "adjetivos terminados ed ing", "diferença ed ing adjetivo"], "Dizer I’m boring quando você quer dizer ‘estou entediado’ é um dos erros mais comuns — e engraçados — de quem aprende inglês (I’m boring significa ‘eu sou chato’!). A diferença entre os adjetivos em -ed e -ing é simples quando você entende a lógica: -ed descreve quem sente a emoção; -ing descreve o que causa a emoção. Neste guia você fixa essa diferença com muitos exemplos e aprende a nunca mais trocar os dois.", [
    section("A regra em uma frase", ["A forma em -ed descreve o sentimento de uma pessoa (ou animal): como ela se sente. A forma em -ing descreve a causa: a característica de algo ou alguém que provoca esse sentimento.", "Então: a pessoa fica -ed por causa de algo -ing. I’m bored (eu me sinto assim) because the class is boring (a aula causa isso)."], undefined, ["-ed → como a pessoa se sente (quem recebe a emoção)", "-ing → o que causa a emoção (a fonte)"]),
    section("-ed: o sentimento de quem vive a experiência", ["Use a forma em -ed para falar de como você ou outra pessoa se sente em reação a algo. Quase sempre se refere a gente (ou bichos), porque são eles que sentem.", "Repare que, depois de adjetivos em -ed, costuma vir uma preposição: interested in, worried about, excited about, tired of, surprised by."], ["I’m bored. — Estou entediado.", "They were interested in the story. — Eles ficaram interessados na história.", "She’s worried about the exam. — Ela está preocupada com a prova.", "We were excited about the trip. — Estávamos animados com a viagem."]),
    section("-ing: a característica que provoca a reação", ["Use a forma em -ing para descrever a coisa, a pessoa ou a situação que causa o sentimento. Responde à pergunta ‘como é isso?’.", "Uma pessoa também pode ser descrita com -ing — mas aí você está dizendo o efeito que ela causa nos outros, não o que ela sente."], ["The film is boring. — O filme é entediante.", "It was an interesting story. — Foi uma história interessante.", "The exam is worrying. — A prova é preocupante.", "He’s an annoying person. — Ele é uma pessoa irritante (irrita os outros)."]),
    section("A comparação que evita o erro", ["O jeito mais seguro é se perguntar: quem sente? (use -ed) ou o que causa? (use -ing). Veja o contraste no mesmo par: I’m confused (eu me sinto confuso) x The instructions are confusing (as instruções causam confusão).", "E cuidado com o clássico: I’m boring = eu sou chato (causo tédio nos outros); I’m bored = estou entediado. São frases bem diferentes!"], ["I’m confused. — Estou confuso. / The map is confusing. — O mapa é confuso.", "I’m tired. — Estou cansado. / The trip was tiring. — A viagem foi cansativa.", "I’m boring. — Eu sou chato. / I’m bored. — Estou entediado."]),
    section("Pares mais comuns para memorizar", ["Vale guardar os pares que mais aparecem, sempre lembrando qual lado é o sentimento e qual é a causa. São muito usados em conversas, provas e no dia a dia.", "Todos seguem a mesma regra: pessoa -ed, causa -ing."], undefined, ["interested / interesting (interessado / interessante)", "excited / exciting (animado / empolgante)", "surprised / surprising (surpreso / surpreendente)", "tired / tiring, relaxed / relaxing, frustrated / frustrating"]),
    section("Perguntas frequentes", ["‘I’m exciting’ está certo? Só se você quer dizer que você é empolgante para os outros; para ‘estou animado’, é I’m excited. Pessoa sempre leva -ed? Para o sentimento, sim; mas uma pessoa pode ser -ing se você fala do efeito dela. Que preposição vai depois de -ed? Varia: interested in, worried about, tired of — vale aprender junto."]),
    section("Continue praticando", ["Esses adjetivos aparecem toda hora para falar de sentimentos e opiniões. Pratique nas aulas do curso descrevendo filmes, aulas e experiências — e como elas fazem você se sentir."], undefined, undefined, [{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Como aprender e fixar vocabulário",url:"/blog/como-aprender-vocabulario-ingles"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "7 min"),
  article("cognatos-verdadeiros-ingles-portugues", "Vocabulário e uso", "Cognatos em inglês: centenas de palavras que você já sabe", "Descubra como os cognatos — palavras parecidas entre inglês e português — dão um atalho de vocabulário, com os padrões de terminações (-tion, -ty, -ly) e os cuidados necessários.", "≈", ["cognatos inglês português", "palavras parecidas inglês", "cognatos verdadeiros", "cognatos exemplos inglês", "terminação tion ty inglês", "palavras iguais inglês português"], "Aqui vai uma boa notícia para quem fala português: você já reconhece centenas de palavras em inglês sem nunca tê-las estudado. São os cognatos — palavras de origem comum (em geral latina) com forma e significado parecidos nos dois idiomas, como hospital, animal, important e nation. Reconhecer os padrões que ligam o português ao inglês é um dos atalhos mais rápidos para ampliar vocabulário e ler melhor. Neste guia você vê esses padrões e aprende a usá-los com segurança.", [
    section("O que são cognatos e por que ajudam", ["Cognatos são palavras que compartilham origem e, por isso, se parecem em duas línguas. Como o português e o inglês têm muitas raízes latinas em comum (o inglês as absorveu do francês e do latim), há milhares delas — sobretudo em vocabulário acadêmico, científico e formal.", "Isso significa que, ao ler um texto técnico ou formal em inglês, boa parte das palavras ‘difíceis’ é justamente a mais fácil para você, porque é cognata."], ["The hospital is near the park. — O hospital fica perto do parque.", "This is an important decision. — Esta é uma decisão importante.", "The animal lives in the forest. — O animal vive na floresta."]),
    section("Padrão -tion ↔ -ção", ["Um dos padrões mais produtivos: palavras portuguesas terminadas em -ção quase sempre têm uma equivalente em inglês terminada em -tion, com o mesmo sentido. Isso desbloqueia centenas de palavras de uma vez.", "Basta trocar a terminação para reconhecer (ou arriscar) a palavra em inglês."], undefined, ["nation ↔ nação", "information ↔ informação", "education ↔ educação", "situation ↔ situação", "communication ↔ comunicação"]),
    section("Outros padrões de terminação úteis", ["Além de -tion, há vários padrões regulares entre os dois idiomas. Conhecê-los acelera tanto a leitura quanto a produção de vocabulário novo.", "Veja os mais comuns e teste trocando a terminação em palavras que você já conhece em português."], undefined, ["-ty ↔ -dade: city/cidade, university/universidade, activity/atividade", "-ly ↔ -mente: exactly/exatamente, normally/normalmente", "-ment ↔ -mento: moment/momento, document/documento", "-ance/-ence ↔ -ância/-ência: importance/importância, difference/diferença", "-ous ↔ -oso: famous/famoso, nervous/nervoso"]),
    section("Use a semelhança como pista de leitura", ["Ao ler, deixe os cognatos trabalharem a seu favor: eles costumam ser as palavras-chave do texto (substantivos e adjetivos ‘grandes’). Reconhecê-los dá a espinha dorsal do sentido, e aí você infere o resto pelo contexto.", "Isso reduz muito a necessidade de dicionário e aumenta a velocidade de leitura."]),
    section("O cuidado necessário: os falsos cognatos", ["A semelhança é uma ferramenta, não uma garantia. Alguns pares parecidos têm significados diferentes — são os falsos cognatos (push = empurrar, library = biblioteca, actually = na verdade). Por isso, quando a tradução ‘óbvia’ deixar a frase estranha, desconfie e confira.", "Confirme também a classe gramatical e a pronúncia: um cognato pode existir, mas ser usado de forma um pouco diferente, e quase sempre tem pronúncia distinta da portuguesa."]),
    section("Cuidado extra: a pronúncia engana", ["Mesmo quando a escrita é quase igual, a pronúncia costuma mudar bastante. Hotel, hospital e important se escrevem parecido, mas soam bem diferente em inglês (a sílaba tônica e as vogais mudam). Aprenda o cognato com o áudio, não só com a grafia.", "Assim você aproveita o atalho do significado sem carregar um sotaque que dificulta ser entendido."]),
    section("Perguntas frequentes", ["Posso confiar sempre nos cognatos? Na maioria, sim, mas confira quando a frase ficar estranha — pode ser falso cognato. A pronúncia é igual? Quase nunca; aprenda com áudio. Isso vale para que tipo de texto? Especialmente textos formais, acadêmicos e científicos, ricos em cognatos. Vale decorar os padrões de terminação? Sim — eles desbloqueiam vocabulário em massa."]),
    section("Continue praticando", ["Cognatos aceleram muito a leitura, mas andam de mãos dadas com o cuidado contra os falsos cognatos. Veja a lista de armadilhas e aplique tudo lendo textos reais em inglês."], undefined, undefined, [{label:"Falsos cognatos: palavras que enganam",url:"/blog/falsos-cognatos-ingles-portugues"},{label:"Como melhorar a leitura usando contexto",url:"/blog/como-melhorar-leitura-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
  article("conectores-para-escrever-ingles", "Writing", "Conectores em inglês: como ligar ideias em um texto", "Aprenda a usar os conectores (linking words) do inglês por função — adição, contraste, causa, resultado, sequência e exemplo — com a pontuação certa e os erros mais comuns.", "↗", ["conectores inglês", "linking words", "conectar ideias inglês", "conectores em inglês lista", "however therefore inglês", "palavras de ligação inglês"], "Conectores (linking words) são as palavras que mostram a relação entre as ideias de um texto: se uma soma, contrasta, explica, conclui ou exemplifica a outra. Usá-los bem é o que transforma frases soltas em um texto que flui — e é muito valorizado em redações de exame. Mas atenção: conector não é enfeite; cada um tem um sentido específico e uma pontuação própria. Neste guia você organiza os principais por função, com exemplos e os erros mais comuns.", [
    section("Como escolher um conector", ["A regra de ouro: escolha pela relação lógica entre as ideias, não para ‘decorar’ o texto. Antes de ligar duas frases, pergunte-se: a segunda ideia soma à primeira? contrasta? explica a causa? mostra o resultado? A resposta indica o grupo de conector certo.", "Encher o texto de conectores sem relação real confunde o leitor e soa artificial."], undefined, ["Adição → and, also, in addition, moreover", "Contraste → but, however, although, on the other hand", "Causa/resultado → because, so, therefore", "Sequência/exemplo → first, then, finally, for example"]),
    section("Adição e contraste", ["Para somar ideias, use and e also (dentro da frase) ou in addition e moreover (começo de frase, mais formal). Para contraste, but liga dentro da frase; however e on the other hand abrem frase; although liga duas orações.", "Repare na pontuação: however no início de frase costuma vir seguido de vírgula."], ["The course is short, but it’s very useful. — O curso é curto, mas muito útil.", "The task is simple. However, it takes time. — A tarefa é simples. No entanto, leva tempo.", "Although it was raining, we went out. — Embora estivesse chovendo, saímos."]),
    section("Causa e resultado", ["Para causa, because introduz a razão (liga duas orações). Para resultado, so é informal e conecta dentro da frase; therefore é formal e abre frase, geralmente com vírgula. As expressões due to e as a result também aparecem.", "Não confunda because (causa) com so (resultado): eles apontam em direções opostas."], ["I stayed home because I was tired. — Fiquei em casa porque estava cansado.", "It was late, so we took a taxi. — Era tarde, então pegamos um táxi.", "The data was incomplete. Therefore, we postponed the decision. — Os dados estavam incompletos. Portanto, adiamos a decisão."]),
    section("Sequência e exemplo", ["Para organizar etapas, use first, second, then, next, finally. Para introduzir uma ilustração, for example e for instance. Esses conectores dão ordem ao texto e ajudam o leitor a acompanhar o raciocínio.", "Em listas de passos, cada conector de sequência costuma abrir a frase, seguido de vírgula."], ["First, read the text. Then, answer the questions. — Primeiro, leia o texto. Depois, responda às perguntas.", "Many activities help, for example, reading and listening. — Muitas atividades ajudam, por exemplo, ler e ouvir.", "Finally, review your answers. — Por fim, revise suas respostas."]),
    section("Erros comuns com conectores", ["Os deslizes mais frequentes: usar conector sem relação lógica real; confundir because e so (causa x resultado); e tratar however como and (however marca contraste, não adição). Cuidado também com a pontuação: muitos conectores de início de frase pedem vírgula depois.", "Para fixar, pegue duas frases suas e ligue-as de formas diferentes, percebendo como o conector muda o sentido."], ["I was tired, therefore I stayed ✗ → I was tired; therefore, I stayed. ✓", "However I like it (para ‘embora’) ✗ → Although I like it… ✓", "escolha pela relação, não para enfeitar"]),
    section("Perguntas frequentes", ["Preciso usar muitos conectores? Não — use os necessários pela lógica; excesso polui. Qual a diferença de ‘however’ e ‘but’? Ambos contrastam; but liga dentro da frase, however costuma abrir frase (com vírgula). ‘So’ é informal? Para resultado, é comum na fala; em textos formais, prefira therefore. Conectores ajudam na redação de exame? Muito — mostram organização e coesão."]),
    section("Continue praticando", ["Conectores são a cola de um bom texto. Combine este guia com a estrutura de parágrafo e com o guia de e-mail, e pratique escrevendo textos curtos nas aulas do curso."], undefined, undefined, [{label:"Como organizar um parágrafo em inglês",url:"/blog/como-escrever-paragrafo-ingles"},{label:"Como escrever um e-mail em inglês",url:"/blog/email-simples-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Treine com os simulados grátis",url:"/simulados"}]),
  ], "8 min"),
  article("soletrar-nome-email-ingles", "Inglês para situações práticas", "Como soletrar nomes, e-mails e confirmar números em inglês", "Aprenda a soletrar e confirmar dados em inglês: o alfabeto falado, o truque do ‘A as in Apple’, como ditar e-mails e números e como evitar erros com letras e sons parecidos.", "ABC", ["soletrar em inglês", "alfabeto inglês telefone", "confirmar números inglês", "como soletrar nome em inglês", "alfabeto fonético inglês", "ditar email em inglês"], "Informar um nome, um e-mail ou um número por telefone é onde muitos erros acontecem — letras e sons parecidos (b/d, m/n) e algarismos mal ouvidos viram dados errados. Saber soletrar e confirmar em inglês resolve isso. Há algumas ferramentas simples: o alfabeto falado, o truque do ‘A as in Apple’ para letras confusas e um jeito claro de ditar e-mails e números. Neste guia você aprende tudo para não precisar adivinhar nem ser mal entendido.", [
    section("Peça (ou ofereça) para soletrar", ["Spell é o verbo ‘soletrar’. Para pedir, use Could you spell that, please? Para oferecer, Let me spell it for you. Dizer as letras devagar e em grupos ajuda quem anota.", "Ao soletrar, faça pausas naturais e confirme no fim."], ["Could you spell your last name, please? — Poderia soletrar seu sobrenome?", "Let me spell it for you: S-O-U-Z-A. — Deixe-me soletrar: S-O-U-Z-A.", "That’s M-A-R-I-A, right? — É M-A-R-I-A, certo?"]),
    section("O truque do ‘A as in Apple’", ["Algumas letras soam parecidas ao telefone (b/p/d/t, m/n, f/s). Para evitar confusão, diga uma palavra de referência: B as in Boy, D as in Dog. Isso é o alfabeto fonético informal, e qualquer palavra clara serve.", "Existe o alfabeto fonético oficial (Alpha, Bravo, Charlie…), mas no dia a dia o ‘as in’ com palavras comuns resolve."], ["B as in Boy, not D as in Dog. — B de Boy, não D de Dog.", "M as in Mary. — M de Mary.", "F as in Friday, S as in Sunday. — F de Friday, S de Sunday."]),
    section("Ditar um e-mail", ["Para e-mails, há vocabulário específico: at para @, dot para o ponto, underscore para _, hyphen/dash para -. Soletre a parte do nome e nomeie os símbolos. Diga também se é tudo junto ou minúsculo.", "Confirme o domínio inteiro, que costuma ser onde mais ocorre erro."], ["It’s ana dot souza at gmail dot com. — É ana ponto souza arroba gmail ponto com.", "a-n-a, all lowercase. — a-n-a, tudo minúsculo.", "That’s one word, no spaces. — É uma palavra só, sem espaços."]),
    section("Confirmar números", ["Diga os algarismos um a um, devagar. Alguns pontos ajudam: zero pode ser dito ‘oh’ em sequências (‘five-oh-two’), e números repetidos às vezes viram double (double four = 44). Peça para repetir devagar quando precisar.", "Para telefones, agrupe os números em blocos para facilitar."], ["My number is seven, three, one… — Meu número é sete, três, um…", "double four, five — quatro-quatro, cinco (4-4-5)", "Could you repeat the number slowly? — Poderia repetir o número devagar?"]),
    section("Confirme no final", ["Antes de encerrar, repita o dado completo e confirme — nome, e-mail ou número inteiro. Essa checagem final é o que de fato evita o erro, principalmente ao telefone, em formulários e em documentos importantes.", "Peça confirmação explícita: Is that correct? ou Did I get that right?"], ["So, that’s j-o-a-o at hotmail dot com? — Então é j-o-a-o arroba hotmail ponto com?", "Let me read it back to you… — Deixe-me repetir para você…", "Is that correct? — Está correto?"]),
    section("Perguntas frequentes", ["Como digo ‘arroba’ e ‘ponto’? At e dot. Preciso do alfabeto fonético oficial? Não — ‘B as in Boy’ com qualquer palavra clara basta. Como falo um zero? Zero, ou ‘oh’ dentro de uma sequência de números. E se não entenderem meu nome? Soletre com o truque ‘as in’ e confirme letra a letra."]),
    section("Continue praticando", ["Soletrar e confirmar dados é essencial ao telefone e em formulários. Pratique nas aulas do curso e combine com os guias de marcar horário por telefone e de pedir para repetir."], undefined, undefined, [{label:"Marcar um horário por telefone",url:"/blog/marcar-consulta-por-telefone-ingles"},{label:"Como pedir para repetir em inglês",url:"/blog/pedir-para-repetir-em-ingles"},{label:"Pratique nas aulas de inglês grátis",url:"/curso"},{label:"Descubra seu nível no teste grátis",url:"/diagnostico"}]),
  ], "8 min"),
];

const certificateGuides: Article[] = [
  article("certificado-cambridge-qual-exame-escolher", "Certificações de inglês", "Qual exame Cambridge escolher? A2 Key, B1 Preliminary, B2 First, C1 Advanced ou C2 Proficiency", "Compare as principais qualificações Cambridge por nível CEFR, objetivo e próximo passo — sem tratar um exame como solução universal.", "C", ["exames Cambridge qual escolher", "Cambridge A2 Key B1 Preliminary B2 First", "C1 Advanced C2 Proficiency", "certificado Cambridge inglês"], "As qualificações Cambridge English cobrem diferentes etapas do CEFR: A2 Key, B1 Preliminary, B2 First, C1 Advanced e C2 Proficiency. A escolha depende do nível que você consegue demonstrar hoje e de quem receberá o resultado. Antes de pagar, verifique no site oficial do exame e na instituição destinatária qual certificado, modalidade, nota e data são aceitos.", [
    section("Como os exames se relacionam aos níveis CEFR", ["Cambridge posiciona A2 Key em A2, B1 Preliminary em B1, B2 First em B2, C1 Advanced em C1 e C2 Proficiency em C2. Os nomes das qualificações indicam o nível-alvo; um resultado na Cambridge English Scale pode, conforme o exame e a faixa obtida, reconhecer desempenho em outro nível. Confirme a tabela atual na página oficial da qualificação."], ["A2 Key → A2", "B1 Preliminary → B1", "B2 First → B2", "C1 Advanced → C1", "C2 Proficiency → C2"], undefined, [{label:"Lista oficial de qualificações Cambridge",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"CEFR e Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}]),
    section("Qual deles faz sentido para o seu objetivo?", ["Para documentar uma meta intermediária, selecione o exame alinhado ao nível que já consegue sustentar em leitura, escrita, escuta e fala. Para universidade, emprego ou imigração, não escolha apenas pelo nível: consulte a lista do destinatário. Requisitos podem especificar exame, versão, nota mínima por habilidade e prazo de validade da evidência."], undefined, ["Estudo geral ou marco pessoal: escolha o nível-alvo realista e confira o formato do exame.", "Universidade ou bolsa: procure a página de admissões do curso e registre notas totais e por habilidade exigidas.", "Trabalho ou imigração: consulte o órgão ou empregador responsável; regras variam por programa e podem mudar."]),
    section("O certificado Cambridge expira?", ["A Cambridge informa qualificações e resultados; não presuma que a regra de aceitação de uma instituição seja igual à política do emissor. A página de cada curso, universidade ou empregador é a referência para saber se aceita um certificado antigo ou pede evidência recente. Guarde o resultado e confirme a política diretamente com quem o avaliará." ]),
    section("Como comparar o nível com sua capacidade atual", ["O nível CEFR descreve competências linguísticas, não uma certificação automática. Use descritores para identificar o que consegue fazer, depois experimente tarefas no formato oficial. Um diagnóstico ou aula gratuita pode orientar a prática, mas não substitui uma prova oficial nem garante aprovação."], undefined, undefined, [{label:"Cambridge: qualificações e exames",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"B2 First",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"C1 Advanced",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"},{label:"C2 Proficiency",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/proficiency/"},{label:"Quadro CEFR da Cambridge",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}])
  ], "8 min"),
  article("cambridge-b2-first-como-funciona", "Certificações de inglês", "B2 First (FCE): para que serve e como se preparar?", "Entenda o nível-alvo, o uso do B2 First e o que verificar antes de escolher a prova.", "B2", ["B2 First FCE para que serve", "exame Cambridge B2 First", "preparação B2 First", "nível B2 Cambridge"], "B2 First, antes conhecido pela sigla FCE, é uma qualificação Cambridge voltada ao nível B2 do CEFR. A Cambridge descreve a prova como evidência de que a pessoa pode viver ou trabalhar em ambiente anglófono ou estudar em inglês. Isso não significa aceitação automática em todo curso ou processo: cada destinatário publica seus próprios requisitos.", [
    section("O que o B2 First demonstra", ["A prova é orientada a tarefas de inglês de nível B2. A página oficial apresenta a qualificação e os componentes do exame; consulte-a para confirmar formato, versão digital ou em papel, duração, taxas e disponibilidade no centro escolhido, pois esses detalhes operacionais podem mudar."], undefined, undefined, [{label:"B2 First: página oficial",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"Formato e componentes oficiais",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/format/"}]),
    section("Como saber se B2 First é o exame adequado", ["Comece pelo requisito escrito da instituição: ela pede especificamente B2 First ou aceita outros testes? Existe nota mínima global e por habilidade? Aceita resultados de qualquer data? Se a resposta exigir um exame diferente ou recente, um certificado de nível compatível não necessariamente substitui a prova solicitada."], ["1. Copie o nome do teste e os mínimos exatamente como aparecem no requisito.", "2. Confirme prazo de validade e forma de envio diretamente com o destinatário.", "3. Escolha data de prova com margem para resultado, repetição ou envio documental."]),
    section("Como se preparar sem estudar só para macetes", ["Faça uma tarefa diagnóstica cronometrada para cada habilidade. Depois classifique erros por causa: vocabulário insuficiente, interpretação do enunciado, organização de texto, controle gramatical ou falta de tempo. Use provas de amostra e materiais oficiais para conhecer o formato, mas também mantenha prática ampla de leitura, escuta, produção oral e escrita."], undefined, ["Treine uma escrita por gênero e revise propósito, leitor, coesão e precisão.", "Na fala, grave respostas se desejar e avalie desenvolvimento, clareza e interação; não apenas velocidade.", "Refaça tarefas semelhantes após feedback e compare erros recorrentes."]),
    section("Perguntas frequentes", ["O B2 First é o mesmo que FCE? FCE é o nome antigo ainda usado informalmente; consulte o nome atual e a versão reconhecida pela instituição. O resultado vale para sempre? Não infira aceitação institucional a partir do nome: pergunte ao destinatário se há prazo. A prova garante admissão? Não; a instituição avalia todos os requisitos do processo."], undefined, undefined, [{label:"Página oficial B2 First",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/first/"},{label:"Resultados e Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/"}])
  ], "7 min"),
  article("cambridge-c1-advanced-o-que-e", "Certificações de inglês", "C1 Advanced: o que é o CAE e quem costuma precisar dele?", "Veja o nível C1, o que a qualificação demonstra e como verificar requisitos de aceitação.", "C1", ["C1 Advanced o que é", "CAE Cambridge C1", "certificado C1 Cambridge", "exame avançado de inglês"], "C1 Advanced, anteriormente conhecido como CAE, é uma qualificação Cambridge no nível C1 do CEFR. A página oficial descreve usos acadêmicos e profissionais para pessoas que precisam de inglês de alto nível. Ela não transforma o certificado em requisito universal: a instituição, o empregador ou o órgão que recebe a candidatura define o que aceita.", [
    section("O que significa C1 neste exame", ["Na Cambridge English Scale, C1 Advanced tem pontuação-alvo indicada na página oficial. A Cambridge também pode reportar níveis conforme a faixa de desempenho do candidato. Leia a tabela oficial atual para interpretar resultado, nível reportado e certificado; não converta uma pontuação isolada em garantia de competência em todos os contextos."], undefined, undefined, [{label:"C1 Advanced: nível e escala",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"},{label:"Cambridge English Scale",url:"https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/"}]),
    section("Para quem pode fazer sentido", ["Pode ser relevante quando uma universidade, empregador ou plano pessoal pede evidência de inglês avançado e aceita explicitamente C1 Advanced. Antes da inscrição, confira o curso/programa exato, notas totais e por componente, modalidade de prova, prazo de resultado e política para certificados antigos."], undefined, ["Procure o nome do exame na página de requisitos do destinatário.", "Registre se a exigência é C1 global, nota mínima ou desempenho por habilidade.", "Se o destinatário pede teste recente, pergunte se aceita resultado Cambridge de data anterior."]),
    section("Como estudar para C1 com consistência", ["Combine prática geral de C1 — leitura extensa, escuta de diferentes registros, escrita revisada e interação oral — com o formato oficial. Analise tarefas modelo para identificar rubricas e limitações de tempo. Faça simulados apenas quando puder revisar os resultados; repetir testes sem feedback pode repetir os mesmos erros."], ["Plano de 4 semanas: diagnóstico → prática focada → revisão de erros → simulado e reflexão.", "Em escrita: revise tese, estrutura, coesão, registro e precisão lexical.", "Em fala: desenvolva ideias, responda ao interlocutor e sustente afirmações com exemplos pertinentes."]),
    section("Dúvidas comuns sobre o CAE", ["CAE ainda é usado como nome? Sim, é uma designação histórica/informal; o nome atual é C1 Advanced. O certificado expira? A página de exame não deve ser tratada como política universal de admissão: confirme diretamente com quem recebe o documento. C1 Advanced é melhor que IELTS? Não há “melhor” universal; são instrumentos diferentes e o requisito do destinatário decide."], ["[Página oficial C1 Advanced](https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/)", "[Cambridge English Scale](https://www.cambridgeenglish.org/exams-and-tests/cambridge-english-scale/)", "[CEFR e Cambridge](https://www.cambridgeenglish.org/exams-and-tests/cefr/)"])
  ], "7 min"),
  article("ielts-ou-cambridge-qual-prova-escolher", "Certificações de inglês", "IELTS ou Cambridge: qual prova de inglês escolher?", "Compare finalidade, formato, prazo de uso do resultado e aceitação pelo destinatário.", "↔", ["IELTS ou Cambridge", "diferença IELTS Cambridge", "qual certificado inglês escolher", "validade IELTS Cambridge"], "IELTS e Cambridge English atendem a objetivos diferentes; a escolha mais segura é seguir o requisito da instituição que receberá o resultado. IELTS é reportado por bandas e costuma ser usado em processos que pedem um resultado recente. Cambridge oferece qualificações associadas a níveis CEFR específicos. Não decida só por reputação ou por uma tabela de equivalência genérica.", [
    section("Diferenças que ajudam na decisão", ["IELTS Academic e General Training têm finalidades e formatos próprios; verifique qual módulo o programa exige. IELTS recomenda considerar resultados como evidência de proficiência por até dois anos, mas instituições definem suas políticas. Cambridge B2 First, C1 Advanced e C2 Proficiency são qualificações associadas a níveis CEFR; a aceitação e a exigência de atualidade também dependem do destinatário."], ["IELTS: confira Academic/General Training, banda global, bandas por habilidade e data exigida.", "Cambridge: confira qualificação/nome atual, nível, resultado e notas mínimas pedidos.", "Em ambos: confirme o requisito na página da instituição antes de pagar a inscrição."]),
    section("Como escolher por objetivo", ["Para admissão, bolsa ou imigração, abra o requisito oficial e anote exame, versão, nota, validade, modalidade, prazo e forma de envio. Se duas opções forem aceitas, compare disponibilidade local, formato, custo atualizado, tempo de resultado e familiaridade com as tarefas. Consulte fontes oficiais para taxas e datas, pois variam por país e centro."], undefined, ["Se há prazo curto, priorize disponibilidade e tempo oficial de processamento.", "Se o resultado é para visto, confirme a lista de testes autorizados do programa específico.", "Se é meta pessoal, escolha o formato que melhor corresponde ao que deseja demonstrar."]),
    section("Validade: o ponto que costuma gerar confusão", ["IELTS recomenda uma janela de dois anos para interpretar resultados como evidência de capacidade atual, mas não é uma lei que determine a política de toda organização. Um certificado Cambridge não deve ser presumido aceito indefinidamente em todo processo: a universidade, empresa ou órgão pode pedir prova recente. Confirme sempre com o destinatário."], undefined, undefined, [{label:"IELTS: interpretação e validade recomendada",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"Cambridge: exames e qualificações",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"Cambridge C1 Advanced",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/advanced/"}]),
    section("Perguntas frequentes", ["IELTS equivale a um nível Cambridge? Há tabelas de comparação indicativas, mas uma instituição pode definir seus próprios cortes. Posso enviar qualquer exame? Só se o destinatário aceitar aquela versão. Preciso escolher o exame mais difícil? Não: escolha aquele que atende ao requisito e cujo formato você consegue preparar com evidência suficiente." ])
  ], "8 min"),
  article("ielts-academic-ou-general-training", "Certificações de inglês", "IELTS Academic ou General Training: qual módulo é o certo?", "Entenda a finalidade dos módulos IELTS e confirme o requisito antes de reservar a prova.", "I", ["IELTS Academic ou General Training", "diferença IELTS Academic General", "qual IELTS fazer", "IELTS para universidade imigração"], "IELTS tem módulos Academic e General Training. A escolha deve seguir o propósito e o requisito publicado pelo curso, órgão ou empregador: não existe um módulo universalmente correto para todas as candidaturas. Verifique as regras específicas antes de pagar ou marcar a prova.", [
    section("Quando o Academic pode ser solicitado", ["IELTS Academic avalia inglês em contextos ligados a estudo superior e, em alguns casos, registro profissional. A instituição define o módulo, a pontuação global e possíveis mínimos por habilidade. Não presuma que qualquer programa aceita General Training apenas porque a pontuação parece suficiente." ]),
    section("Quando o General Training pode ser solicitado", ["General Training é usado em alguns contextos de trabalho, formação e migração; as exigências dependem do país, do visto e do processo. Órgãos podem limitar quais testes, formatos ou versões aceitam. Consulte a página oficial do programa, não apenas recomendações de terceiros." ]),
    section("Checklist antes de reservar", ["Leia a fonte oficial da candidatura e confirme módulo, formato, centro, data, prazo de resultado e regra para resultados anteriores. Se a página não estiver clara, pergunte ao setor responsável por escrito. O mesmo IELTS pode ser adequado para um objetivo e inadequado para outro, mesmo que os níveis de inglês sejam comparáveis."], undefined, ["1. Nome do programa/curso e ano de candidatura.", "2. Academic ou General Training, incluindo modalidade autorizada.", "3. Banda global e mínimos de Listening, Reading, Writing e Speaking.", "4. Prazo de validade que o destinatário aplica."]),
    section("IELTS e validade do resultado", ["IELTS recomenda considerar resultados por até dois anos como evidência do nível atual; instituições mantêm a decisão de aceitar ou não um resultado em seu processo. Confirme a política da organização mesmo quando seu TRF ainda está disponível."], undefined, undefined, [{label:"IELTS: Understanding IELTS scoring",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"IELTS: Academic e General Training",url:"https://ielts.org/take-a-test/test-types"}])
  ], "6 min"),
  article("toefl-ibt-o-que-e-validade-e-aceitacao", "Certificações de inglês", "TOEFL iBT: o que é, para que serve e por quanto tempo vale?", "Entenda o uso acadêmico do TOEFL iBT, os resultados e como confirmar exigências institucionais.", "T", ["TOEFL iBT o que é", "validade TOEFL dois anos", "TOEFL para universidade", "TOEFL nota CEFR"], "TOEFL iBT é um teste de inglês usado por instituições em processos acadêmicos e outros contextos que aceitam seus resultados. Requisitos variam: confirme a versão, nota global, cortes por habilidade e prazo diretamente com a universidade ou órgão. A ETS informa que as pontuações TOEFL têm validade de dois anos a partir da data do teste.", [
    section("O que verificar no resultado", ["Consulte sua conta ETS para o boletim oficial, a escala de notas vigente e a opção de envio às instituições. A pontuação solicitada é definida pelo destinatário; não há uma nota única que garanta admissão. Confirme também a data em que o resultado precisa estar válido e recebido." ]),
    section("Como escolher TOEFL ou outro exame", ["Primeiro verifique se o programa aceita TOEFL iBT e qual versão/modalidade reconhece. Depois compare datas, processamento, custo vigente e formato de tarefas com outras alternativas aceitas. Uma comparação CEFR pode ajudar a interpretar nível, mas não substitui o corte definido pela instituição."], undefined, ["Confirme o código/nome do exame na página de admissões.", "Anote nota total e mínimos por seção.", "Planeje o teste com margem para relatório oficial ou nova tentativa."]),
    section("Validade e envio", ["A ETS afirma que as pontuações TOEFL são válidas por dois anos após a data do teste. Se o resultado ultrapassou esse prazo, verifique se ainda pode ser enviado e se o destinatário o aceita; não trate disponibilidade técnica ou uma comparação de nível como extensão da validade oficial."], undefined, undefined, [{label:"ETS: TOEFL iBT scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores.html"},{label:"ETS: Understand your scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores/understand-scores.html"}])
  ], "7 min"),
  article("pte-academic-o-que-e-validade", "Certificações de inglês", "PTE Academic: como funciona e quando é aceito?", "Veja o formato computadorizado, as quatro habilidades e os cuidados com validade e aceitação.", "P", ["PTE Academic como funciona", "validade PTE Academic", "PTE para universidade", "PTE Academic inglês"], "PTE Academic é um teste computadorizado de inglês que avalia speaking, writing, reading e listening em uma sessão. Pearson informa que a prova dura aproximadamente duas horas e atende a objetivos de estudo, trabalho e migração nos contextos em que o resultado é aceito. O destinatário, não o nome do teste, define se ele serve ao processo específico.", [
    section("Formato e habilidades", ["A página de Pearson descreve tarefas integradas e seções de Speaking & Writing, Reading e Listening. Consulte a página oficial antes de reservar porque duração, tarefas, disponibilidade de centro e serviços podem mudar. Conheça o formato usando os materiais oficiais atuais."], undefined, undefined, [{label:"PTE Academic: formato oficial",url:"https://www.pearsonpte.com/pte-academic/"}]),
    section("Validade do PTE Academic", ["Pearson informa validade de dois anos a partir da data da prova. Ainda assim, confira o prazo que a universidade, empregador ou autoridade aplica e se exige resultado recebido antes de uma data de corte. Uma pontuação dentro do prazo não garante aceitação se o programa não aceitar esse teste."], undefined, undefined, [{label:"PTE Academic: prazo e detalhes oficiais",url:"https://www.pearsonpte.com/pte-academic/"}]),
    section("Perguntas antes de pagar", ["Confirme se o destinatário aceita PTE Academic, qual nota global e por habilidade pede, se aceita a versão pretendida e como os resultados devem ser enviados. Compare valores apenas em páginas oficiais e na moeda/localidade aplicável; não use preços antigos de artigos de terceiros."], undefined, undefined, [{label:"PTE Academic: formato e validade",url:"https://www.pearsonpte.com/pte-academic/"},{label:"Cambridge: comparação CEFR para orientação",url:"https://www.cambridgeenglish.org/exams-and-tests/cefr/"}])
  ], "6 min"),
  article("duolingo-english-test-o-que-saber", "Certificações de inglês", "Duolingo English Test: o que é e o que conferir antes de fazer?", "Entenda o teste remoto e verifique a aceitação do programa antes de contar com o resultado.", "D", ["Duolingo English Test aceitação", "DET validade resultado", "teste inglês online universidade", "Duolingo English Test CEFR"], "Duolingo English Test (DET) é uma avaliação de inglês realizada online sob regras e supervisão definidas pelo emissor. A aceitação não é universal: cada universidade ou organização decide se recebe o DET, quais pontuações exige e em que datas. Antes de se preparar, consulte o site oficial da candidatura e a lista atualizada de instituições que aceitam o teste.", [
    section("Como confirmar se uma instituição aceita o DET", ["Procure o nome exato da universidade e do curso na página oficial de admissões. Verifique a pontuação global, subscores, prazo de validade, forma de envio e limitações para programas específicos. A aceitação geral de uma instituição não garante que cada faculdade, bolsa ou curso aceite o teste." ]),
    section("Validade do resultado", ["A política oficial pode mudar; consulte a página atual de resultados do DET e as exigências da organização destinatária antes de reservar. Não presuma que um score report disponível continuará aceito em um ciclo de candidatura futuro. Registre a data da prova e a data-limite publicada pelo programa."], undefined, undefined, [{label:"Duolingo English Test: resultados e pontuações",url:"https://englishtest.duolingo.com/scores"},{label:"Instituições que aceitam o DET",url:"https://englishtest.duolingo.com/institutions"}]),
    section("Preparação e condições do teste", ["Leia as regras técnicas, de identidade, ambiente e integridade acadêmica antes de pagar. Pratique as tarefas de amostra oficiais em um equipamento compatível. Um teste feito remotamente ainda exige cumprir os procedimentos de segurança do emissor e não elimina os requisitos acadêmicos da candidatura."], undefined, ["[Duolingo English Test: resultados e pontuações](https://englishtest.duolingo.com/scores)", "[Duolingo English Test: instituições](https://englishtest.duolingo.com/institutions)"])
  ], "6 min"),
  article("como-escolher-exame-certificacao-ingles", "Certificações de inglês", "Qual certificado de inglês fazer? Um checklist para escolher sem desperdiçar dinheiro", "Comece pelo requisito de quem receberá a nota, não por listas genéricas de “melhores provas”.", "✓", ["qual certificado inglês fazer", "melhor prova de inglês para universidade", "Cambridge IELTS TOEFL PTE", "validade certificado inglês"], "Não existe um único “melhor certificado de inglês” para todas as pessoas. IELTS, TOEFL iBT, PTE Academic, Duolingo English Test e Cambridge English podem atender a necessidades diferentes, mas o processo de admissão, visto, empregador ou órgão define quais testes reconhece. O primeiro passo é consultar esse requisito oficial.", [
    section("Checklist em cinco etapas", ["Use esta sequência para comparar provas com segurança."], undefined, ["Identifique quem receberá o resultado e o objetivo (curso, visto, trabalho ou meta pessoal).", "Confirme o teste e a versão autorizados para o programa e o ciclo atual.", "Anote pontuação global, mínimos por habilidade, CEFR se informado, validade e prazo de envio.", "Compare datas disponíveis, local/modalidade, tempo de processamento e custo atualizado em fontes oficiais.", "Escolha uma data que permita receber e, se necessário, refazer a prova antes do prazo."]),
    section("Comparação rápida sem equivalências simplistas", ["Cambridge oferece qualificações como B2 First, C1 Advanced e C2 Proficiency associadas a níveis CEFR. IELTS reporta bandas e recomenda interpretar resultados por até dois anos, enquanto a instituição define sua política. TOEFL iBT e PTE Academic informam validade de dois anos para resultados. Para Duolingo English Test, confirme a validade e a aceitação atuais nas páginas do emissor e do destinatário. Esses sistemas não são intercambiáveis automaticamente."], undefined, undefined, [{label:"Cambridge English",url:"https://www.cambridgeenglish.org/exams-and-tests/qualifications/"},{label:"IELTS scoring",url:"https://ielts.org/organisations/ielts-for-organisations/understanding-ielts-scoring"},{label:"TOEFL iBT scores",url:"https://www.ets.org/toefl/test-takers/ibt/scores.html"},{label:"PTE Academic",url:"https://www.pearsonpte.com/pte-academic/"},{label:"Duolingo English Test",url:"https://englishtest.duolingo.com/scores"}]),
    section("O curso prepara para esses certificados?", ["Uma trilha CEFR e atividades de inglês podem desenvolver competências gerais, mas não equivalem a um exame oficial nem garantem pontuação. Use uma aula de diagnóstico para escolher o nível de estudo e acrescente prática específica do exame aceito pelo seu destinatário."], ["[Explore a trilha de inglês A1–C2](/curso)", "[Faça o diagnóstico orientativo](/diagnostico)"])
  ], "8 min"),
];

const existingArticleSlugs = new Set(articleDrafts.map((item) => item.slug));
const duplicateCertificateSlugs = certificateGuides.filter((item) => existingArticleSlugs.has(item.slug));
if (duplicateCertificateSlugs.length) throw new Error(`Duplicate article slug: ${duplicateCertificateSlugs.map((item) => item.slug).join(", ")}`);

export const articles: Article[] = [...articleDrafts, ...certificateGuides];

